-- Seed CAPM Lot 3 questions for Supabase
-- Generated from CAPM Lot 3 EN/FR DOCX files.

insert into public.exam_lots (id, exam_type, title_fr, title_en, source, question_count, active) values ('capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'CAPM 2026 - Lot 3 - Complet - Questions 1 ? 150', 'CAPM 2026 - Lot 3 - Full Exam - Questions 1 to 150', 'CAPM 2026 Lot 3 complet  150 questions.docx + CAPM_2026_Lot_3_Traduction_FR_Questions_01-150.docx', 150, true) on conflict (id) do update set exam_type = excluded.exam_type, title_fr = excluded.title_fr, title_en = excluded.title_en, source = excluded.source, question_count = excluded.question_count, active = excluded.active;

insert into public.question_bank (id, lot_id, exam_type, question_type, prompt_fr, prompt_en, options_fr, options_en, correct_indexes, explanation_fr, explanation_en, eco_fr, eco_en, performance_domain_fr, performance_domain_en, approach_fr, approach_en, active) values

('L3Q1', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Dans un projet d’aménagement intérieur d’une bibliothèque, le client demande à l’équipe d’augmenter le nombre d’étagères au-delà de ce qui avait été convenu. Comme le projet respecte l’échéancier et que l’ajout d’étagères supplémentaires ne fera aucune différence, le chef de projet accepte la demande du client. Ceci est un exemple de :', 'In an interior design project for a library, the client asks the team to increase the number of bookshelves beyond what was agreed on. Since the project is on schedule and adding additional shelves will make no difference, the project manager consents to the client’s request. This is an example of:', '["Gold plating", "Obsession client", "Dérive du périmètre", "Projet réussi"]'::jsonb, '["Gold Plating", "Customer Obsession", "Scope Creep", "Successful Project"]'::jsonb, '[2]'::jsonb, 'La dérive du périmètre (également appelée « dérive des fonctionnalités » ou « dérive des exigences ») désigne l’expansion non maîtrisée du périmètre du projet (PMBOK, 8e édition, page 273). Option A : la situation décrite n’est pas considérée comme du gold plating, puisque c’est le client qui a formulé la demande de changement ; ce ne sont ni le chef de projet ni les membres de l’équipe qui ont ajouté des changements sans l’approbation du client, comme l’implique le gold plating. Option B : l’obsession client consiste à se concentrer de manière excessive sur l’amélioration de l’expérience client en satisfaisant, voire en dépassant, ses besoins. Toutefois, elle ne devrait pas signifier livrer au-delà du périmètre, car cela peut augmenter la durée et le coût du projet et, par conséquent, réduire ses chances de réussite.', 'Scope creep (also known as “feature creep” or “requirement creep”) refers to the uncontrolled expansion of the project’s scope (PMBOK 8th edition, page 273). Option A: The tackled situation is not considered gold plating since the client is the one who brought up the change request; it was neither the project manager nor team members who added changes without the client’s approval, as gold plating implies. Option B: Customer obsession consists of an excessive focus on providing a better customer experience by meeting and even exceeding your client’s needs. However, customer obsession shouldn’t mean delivering beyond scope since the latter can increase the project schedule and cost, thus decreasing the success rate of the project.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Scope', 'Scope', 'Predictive', 'Predictive', true),
('L3Q2', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Quel outil garantit que chaque exigence de la solution est reliée aux besoins, buts et objectifs business, ainsi qu’aux attentes des parties prenantes ?', 'Which tool ensures that each solution requirement is linked to the business needs, goals, and objectives, as well as stakeholder expectations?', '["Matrice de traçabilité des exigences", "Matrice d’évaluation de l’engagement des parties prenantes", "Évaluation de l’état de préparation", "MoSCoW"]'::jsonb, '["Requirements traceability matrix", "Stakeholder engagement assessment matrix", "Readiness assessment", "MoSCoW"]'::jsonb, '[0]'::jsonb, 'La matrice de traçabilité des exigences garantit que chaque exigence de la solution apporte de la valeur et reste dans le périmètre en la reliant aux besoins et objectifs business, aux objectifs du projet et aux exigences des parties prenantes. Elle est généralement utilisée dans un environnement prédictif (PMBOK, 8e édition, pages 131-132). Option B : la matrice d’évaluation de l’engagement des parties prenantes sert à comparer le niveau d’engagement actuel au niveau souhaité (PMBOK, 8e édition, page 200). Option C : une évaluation de l’état de préparation mesure le degré de préparation d’une organisation à transférer une solution vers la maintenance et les opérations. Elle comprend une analyse approfondie de l’état de préparation dans tous les domaines, l’identification des écarts qui présentent des risques pour l’atteinte du résultat souhaité et l’élaboration de réponses pour traiter ces risques. Option D : MoSCoW est une technique de priorisation qui classe les exigences en quatre catégories : « Must Have », « Should Have », « Could Have » et « Won’t Have » (PMBOK, 8e édition, page 187). Cette méthode aide les Business Analysts à prioriser les caractéristiques et les fonctions, afin d’allouer les ressources aux éléments les plus précieux d’un projet. MoSCoW peut être appliquée dans des environnements prédictifs, hybrides et adaptatifs.', 'The requirements traceability matrix ensures that each solution requirement is valuable and within scope by linking it to business needs and goals, project objectives, and stakeholder requirements. RTM is typically used in a predictive environment (PMBOK 8th Edition, pages 131-132). Stakeholder engagement assessment matrix is used to compare the current engagement against the desired engagement level (PMBOK 8th Edition, page 200). A readiness assessment evaluates an organization’s preparedness to transition a solution to maintenance and operations. It involves a thorough analysis of readiness across all areas, identifying gaps that pose risks to achieving the desired outcome, and developing responses to address these risks. MoSCoW is a prioritization technique used to categorize requirements into four groups: "Must Have," "Should Have," "Could Have," and "Won''t Have" (PMBOK 8th Edition, page 187). This method helps business analysts prioritize features and functions, ensuring that resources are allocated to the most valuable aspects of a project. MoSCoW can be applied in predictive, hybrid, and adaptive project environments.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Predictive', 'Predictive', true),
('L3Q3', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Une équipe, dont les rôles ne sont pas définis, utilise un tableau et des cartes pour classer les tâches en « À faire », « En cours » et « Terminé ». Sans trop de restrictions, les membres de l’équipe prennent une carte de la liste « À faire » et commencent à travailler. Quel cadre Agile est décrit ?', 'A team, with no defined roles, uses a board and cards to categorize tasks into “To do”, “Doing”, and “Done”. Without too many restrictions, team members grab a card from the “To do” list and begin to work. What agile framework is being described? Scrum', '["Scrum", "Kanban", "Lean", "Kaizen"]'::jsonb, '["Scrum", "Kanban", "Lean", "Kaizen"]'::jsonb, '[1]'::jsonb, 'Option A : contrairement à Scrum, l’équipe Kanban ne comporte aucun rôle formel. De plus, la pratique Kanban impose moins de restrictions que Scrum. Option B : Kanban est une méthode Agile qui utilise un système de travail en flux tiré dans lequel les tâches ne sont affectées que lorsque les ressources sont disponibles. Option C : Lean n’est pas un cadre Agile. Agile et Kanban sont plutôt des sous-ensembles de Lean (Agile Practice Guide, page 11). Option D : Kaizen est une philosophie de management de la qualité et des ressources qui consiste à apporter continuellement de petites améliorations afin d’accroître la productivité et de réduire les coûts.', 'Unlike Scrum, the Kanban team has no formal roles. Additionally, Kanban practice has fewer restrictions than Scrum. Kanban is an agile method that employs a pull-based work system where tasks are assigned only when resources are available. Lean is not an agile framework. In contrast, agile and kanban are subsets of lean (Agile Practice Guide, page 11). Kaizen is a quality and resource management philosophy of applying continuous small improvements to increase productivity and reduce costs.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'resources and Risks', 'Resources and Risks', 'Agile', 'Agile', true),
('L3Q4', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Le processus d’engagement des parties prenantes comporte cinq étapes. Quel est leur enchaînement logique selon la figure ci-dessous ?', 'The stakeholder engagement process involves five steps. What is their logical sequencing according to the figure below?', '["A. Identifier, B. Engager, C. Comprendre et analyser, D. Surveiller", "A. Identifier, B. Comprendre et analyser, C. Engager, D. Surveiller", "A. Identifier, B. Surveiller, C. Comprendre et analyser, D. Engager", "A. Comprendre et analyser, B. Identifier, C. Engager, D. Surveiller"]'::jsonb, '["A. Identify, B. Engage, C. Understand & analyze, D. Monitor", "A. Identify, B. Understand & analyze, C. Engage, D. Monitor", "A. Identify, B. Monitor, C. Understand & analyze, D. Engage", "A. Understand & analyze, B. Identify, C. Engage, D. Monitor"]'::jsonb, '[1]'::jsonb, 'A = Identifier, B = Comprendre et analyser, C = Engager, D = Surveiller. L’engagement des parties prenantes commence par l’identification de toutes les parties directement ou indirectement liées au projet ou impliquées dans celui-ci. Ensuite, les parties prenantes identifiées doivent être pleinement comprises quant à leurs convictions, attitudes, attentes, etc. à l’égard du projet, afin de pouvoir analyser le niveau de pouvoir, d’intérêt, d’impact, etc. de chacune et de les prioriser en conséquence. Un plan d’engagement est ensuite élaboré à partir des résultats des étapes précédentes. Le chef de projet doit alors assurer une communication claire et constante, la satisfaction des exigences et attentes des parties prenantes ainsi que la résolution des problèmes lorsque cela est nécessaire. La surveillance des parties prenantes constitue la dernière étape du processus ; elle consiste à suivre tout changement dans leurs attitudes ou leurs niveaux de pouvoir afin d’adapter le plan d’engagement en conséquence.', 'A = Identify, B = Understand & analyze, C = Engage, D = Monitor. Stakeholder engagement starts by identifying all parties directly or indirectly connected or involved in the project. Next, the identified stakeholders must be fully understood in terms of their beliefs, attitudes, expectations, etc. towards the project in order to be able to analyze each one’s level of power, interest, impact, etc., and prioritize them accordingly. After that, an engagement plan is created according to the findings of the previous steps, where a project manager should ensure clear and constant communication, the satisfaction of stakeholders’ requirements and expectations, and issue resolution when needed. Monitoring stakeholders is the final step in the process, and it entails monitoring any changes in their attitudes or power levels to adapt the engagement plan accordingly.', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Stakeholders', 'Stakeholders', 'Predictive', 'Predictive', true),
('L3Q5', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Quel est l’objectif d’une charte de projet ?', 'What is the purpose of a project charter?', '["Documenter l’approche du projet", "Autoriser formellement le projet et documenter ses exigences initiales", "Servir de référence lors de la réunion de lancement du projet", "Établir le code de conduite du projet"]'::jsonb, '["To document the project approach", "To formally authorize the project and document its initial requirements", "To be used as a reference during the project kick-off meeting", "To set up the project code of conduct"]'::jsonb, '[1]'::jsonb, 'Une charte de projet sert à autoriser formellement le chef de projet à démarrer le projet, ainsi qu’à documenter les objectifs du projet et son périmètre de haut niveau. Elle définit également les responsabilités et les rôles de toutes les parties impliquées dans le projet (PMBOK, 8e édition, pages 17-18).', 'A project charter is used to formally authorize both the project manager to start the project, as well as document the project’s objectives and its high-level scope. It also defines the responsibilities and roles of all involved parties in the project (PMBOK 8th edition, pages 17-18).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Gouvernance', 'Gouvernance', 'Predictive', 'Predictive', true),
('L3Q6', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Avant d’annoncer l’achèvement de l’exécution du projet, le chef de projet d’un projet de construction examine les livrables et effectue une visite du site. Que réalise-t-il dans ce scénario ?', 'Before announcing the completion of the project execution, the project manager of a construction project reviews deliverables and performs a site walkthrough. What is the project manager performing in this scenario?', '["Une inspection", "Une remise des livrables", "Un audit", "Une validation du périmètre"]'::jsonb, '["An inspection", "A handing over", "An audit", "A scope validation"]'::jsonb, '[0]'::jsonb, 'Au cours d’une inspection, le chef de projet examine les livrables et effectue, le cas échéant, une visite du site (PMBOK, 8e édition, page 174). Options B et D : dans cette situation, le chef de projet ne valide pas le périmètre avec le client et ne lui remet pas non plus les livrables. Option C : les audits sont réalisés afin de déterminer si les activités du projet sont conformes aux politiques, processus et procédures de l’organisation et du projet (PMI, Process Groups: A Practice Guide, page 248). Autrement dit, les audits portent sur les processus, tandis que les inspections portent sur les produits.', 'During an inspection, the project manager reviews deliverables and performs a site walkthrough if applicable (PMBOK 8th Edition, page 174). Option B, D: The project manager here is neither validating the scope with the customer nor handing over deliverables to them. Option C: Audits are carried out to determine if project activities comply with organizational and project policies, processes, and procedures (PMI - Process groups guide, page 248). In other words, audits are performed on processes while inspections are performed on products.', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Scope', 'Scope', 'Predictive', 'Predictive', true),
('L3Q7', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Dans le contexte d’un projet, les lignes directrices et les politiques sont classées comme :', 'In a project context, guidelines and policies are classified as:', '["Réglementations", "Bonnes pratiques", "Hypothèses", "Contraintes"]'::jsonb, '["Regulations", "Best practices", "Assumptions", "Constraints"]'::jsonb, '[3]'::jsonb, 'Les contraintes du projet sont des restrictions qui limitent le projet d’une certaine manière. Une contrainte de coût, par exemple, signifie que le projet est limité par le budget ou les ressources qui lui sont alloués. Les autres contraintes comprennent les politiques, les normes, les lignes directrices, etc.', 'Project constraints are restrictions that limit the project in a certain way. A cost restriction, for instance, means that the project is limited by its allocated budget or resources. Other constraints include policies, standards, guidelines, etc.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Gouvernance', 'Gouvernance', 'Predictive', 'Predictive', true),
('L3Q8', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Pour comparer les différents fournisseurs et faire le meilleur choix, lequel des outils ou techniques suivants le chef de projet devrait-il utiliser ?', 'To compare the different suppliers and make the best choice, which of the following tools or techniques should the project manager use?', '["Revue de la performance des approvisionnements", "Critères de sélection", "Audit des approvisionnements", "Analyse « faire ou faire faire »"]'::jsonb, '["Procurement performance review", "Selection criteria", "Procurement audit", "Make or buy analysis"]'::jsonb, '[1]'::jsonb, 'Il est essentiel que le chef de projet et l’équipe projet élaborent des critères de sélection permettant d’évaluer et de noter les propositions des fournisseurs. Dans le cas d’un appel d’offres ou d’un devis, le prix proposé par le vendeur constitue le principal critère d’évaluation. Dans d’autres cas impliquant des propositions, les critères d’évaluation peuvent comprendre divers aspects tels que l’expérience du vendeur, ses références, ses certifications, etc. (PMBOK, 8e édition, page 21). Option D : dans ce scénario, le chef de projet a reçu des propositions ; une analyse « faire ou faire faire » devrait donc déjà avoir été réalisée à ce stade. Options A et C : un audit ou une revue de la performance devrait intervenir ultérieurement afin de vérifier que tous les processus d’approvisionnement ont été respectés et que les articles achetés sont conformes aux exigences (PMBOK, 8e édition, page 148).', 'It''s essential for both the project manager and the project team to create selection criteria to rate and score proposals from the suppliers. In the case of a bid or quote, the price offered by the seller represents the main evaluation criterion. In other cases involving proposals, the evaluation criteria can include various aspects such as the seller’s experience, references, certifications, etc. (PMBOK 8Th Edition, page 21). Option D: In this scenario, the project manager has received proposals, so a make-or-buy analysis should have been already carried out at this point. Option C & A: An audit or a performance review should take place at a later stage to verify that all procurement processes were respected and that the purchased items conform to requirements (PMBOK 8th Edition, page 148).', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Gouvernance', 'Gouvernance', 'Predictive', 'Predictive', true),
('L3Q9', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Laquelle des responsabilités suivantes incombe à un Business Analyst ?', 'Which of the following is a Business Analyst’s responsibility?', '["Recueillir, analyser et documenter les exigences des parties prenantes", "Effectuer les tests d’assurance qualité", "Gérer le projet", "Prioriser le backlog"]'::jsonb, '["Eliciting, analyzing, and documenting stakeholders requirements", "QA testing", "Managing the project", "Backlog prioritization"]'::jsonb, '[0]'::jsonb, 'Option A : recueillir, analyser et documenter les exigences des parties prenantes constitue une responsabilité essentielle du Business Analyst. Il recueille les exigences détaillées auprès des parties prenantes, les analyse pour comprendre leurs implications et les documente afin de garantir leur clarté et leur alignement (PMBOK, 8e édition, page 24). Option B : les tests d’assurance qualité relèvent de la responsabilité de l’équipe projet, qui doit identifier les défauts du produit et veiller à ce qu’il respecte les normes de qualité. Option C : la gestion du projet est la responsabilité principale du chef de projet. Option D : la priorisation du backlog est la responsabilité du Product Owner.', 'Eliciting, analyzing, and documenting stakeholders'' requirements is a core responsibility of a business analyst. They work to gather detailed requirements from stakeholders, analyze these requirements to understand their implications, and document them to ensure clarity and alignment (PMBOK 8th Edition, page 24). QA Testing is the responsibility of the project team in identifying defects in the product and ensuring it meets quality standards. Managing the project is the project manager’s primary responsibility. Backlog prioritization is the product owner’s responsibility.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Hybrid', 'Hybrid', true),
('L3Q10', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un projet implique des dizaines de parties prenantes. La plupart ont besoin d’informations de haut niveau et de mises à jour sur l’état du projet, tandis que les autres ont besoin d’informations plus détaillées et de mises à jour fréquentes. Le chef de projet décide donc d’établir un plan d’action pour répondre à ces différentes exigences. Que devrait-il créer ?', 'A project involves dozens of stakeholders. Most of them need high-level information and updates about the project status, while the rest need more detailed information and frequent updates. Therefore, the project manager decides to set up an action plan to respond to these different requirements. What should the project manager create?', '["Grille pouvoir/intérêt", "Registre des parties prenantes", "Plan d’engagement des parties prenantes", "Matrice d’évaluation de l’engagement des parties prenantes"]'::jsonb, '["Power/interest grid", "Stakeholder register", "Stakeholder engagement plan", "Stakeholder engagement assessment matrix"]'::jsonb, '[2]'::jsonb, 'Un plan d’engagement des parties prenantes établit des stratégies et des actions visant à assurer l’implication positive et efficace de toutes les parties prenantes dans le projet (PMBOK, 8e édition, page 141). Option B : le registre des parties prenantes répertorie les parties prenantes du projet et ne contient aucun plan d’action (PMBOK, 8e édition, pages 141-142). Options A et D : la grille pouvoir/intérêt et la matrice d’évaluation de l’engagement des parties prenantes sont des outils et techniques permettant d’analyser les parties prenantes et d’évaluer leur niveau d’engagement. Contrairement au plan d’engagement des parties prenantes, ces outils ne produisent ni ne comprennent d’informations pratiques sur la manière d’engager et de surveiller les parties prenantes, telles que la fréquence des réunions officielles, les destinataires des rapports d’état, les canaux de communication, etc. (PMBOK, 8e édition, page 200).', 'A stakeholder engagement plan sets up strategies and actions to ensure the positive and effective involvement of all stakeholders in the project (PMBOK 8th edition, page 141). Option B: The stakeholder register lists the project stakeholders and doesn’t include any action plan (PMBOK 8th Edition, pages 141-142). Option A & D: The power/interest grid and stakeholder engagement assessment matrix are tools and techniques to analyze stakeholders and assess their level of engagement. Unlike the stakeholder engagement plan, these tools do not generate or comprise practical information on how to engage and monitor stakeholders such as the frequency of official meetings, recipients of status reports, communication channels, etc. (PMBOK 8th Edition, page 200).', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Stakeholders', 'Stakeholders', 'Predictive', 'Predictive', true),
('L3Q11', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet a été affecté à un projet de clôture d’une ferme sur une longueur de 300 pieds. Quelle est la meilleure manière d’estimer le coût du projet ?', 'A project manager has been assigned to a 300 ft farm fencing project. What is the best way to estimate the project cost?', '["Estimation à trois points", "Estimation paramétrique", "Estimation ascendante", "Estimation par analogie"]'::jsonb, '["Three-point estimation", "Parametric estimating", "Bottom-up estimating", "Analogous estimating"]'::jsonb, '[1]'::jsonb, 'Puisqu’il s’agit d’un projet de clôture d’une ferme sur une longueur de 300 pieds, le travail est linéaire, répétitif et standardisé. Le chef de projet peut estimer le coût à partir d’un coût par pied et le multiplier par 300, ce qui correspond exactement à l’usage prévu de l’estimation paramétrique (PMBOK, 8e édition, page 184).', 'Because this is a 300 ft farm fencing project, the work is linear, repetitive, and standardized. The project manager can estimate the cost based on a cost per foot and multiply by 300 ft, which is exactly what parametric estimating is designed for (PMBOK 8th Edition, page 184).', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Finance', 'Finance', 'Predictive', 'Predictive', true),
('L3Q12', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'À quelle fin la technique des Six chapeaux de la réflexion® est-elle utilisée ?', 'For what purpose is the Six Thinking Hats® technique used?', '["Identification des risques", "Résolution des conflits", "Prise de décision", "Analyse des parties prenantes"]'::jsonb, '["Risk identification", "Conflict resolution", "Decision-making", "Stakeholder analysis"]'::jsonb, '[2]'::jsonb, 'La technique des Six chapeaux de la réflexion® sert à soutenir une prise de décision structurée en guidant les personnes ou les équipes dans l’évaluation d’une situation selon plusieurs perspectives : faits, émotions, risques, avantages, créativité et processus. Cela améliore la qualité des discussions et conduit à de meilleures décisions (PMBOK, 8e édition, page 198).', 'The Six Thinking Hats® technique is used to support structured decision making by guiding individuals or teams to evaluate a situation from multiple perspectives (facts, emotions, risks, benefits, creativity, and process). This helps improve the quality of discussions and leads to better decision-making (PMBOK 8th Edition, page 198).', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Gouvernance', 'Gouvernance', 'Hybrid', 'Hybrid', true),
('L3Q13', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet a été affecté à un grand projet dont les exigences et les livrables étaient imprécis. Après avoir choisi une approche Agile pour faire face à cette situation, que devrait-il faire ensuite ?', 'A project manager was assigned to a large project that had unclear requirements and deliverables. After choosing an agile approach to deal with the situation, what should the project manager do next? Acquire an agile coach to clarify the project scope.', '["Faire appel à un coach Agile pour clarifier le périmètre du projet.", "Faciliter l’identification et la priorisation des éléments de travail actuels, puis veiller à leur exécution de manière itérative et incrémentale.", "Mettre en place une équipe pluridisciplinaire pour aider à définir toutes les itérations nécessaires à l’achèvement du projet.", "Organiser une réunion avec le Product Owner ou le sponsor pour discuter des références de base du projet."]'::jsonb, '["Acquire an agile coach to clarify the project scope.", "Facilitate the identification and prioritization of current work items, then ensure their execution in an iterative and incremental way.", "Set up a cross-functional team to help define all the needed iterations for completing the project.", "Have a meeting with the product owner or sponsor to discuss project baselines."]'::jsonb, '[1]'::jsonb, 'Option A : puisque le projet est de grande taille et que les livrables sont vagues, il pourrait être impossible de clarifier le périmètre du projet et de lever l’ambiguïté avant de commencer la mise en œuvre. Dans ce cas, l’approche prédictive serait plus appropriée qu’Agile. Il va sans dire que le rôle du coach Agile ne consiste pas à clarifier le périmètre du travail, mais plutôt à aider l’équipe projet à adopter un état d’esprit Agile. Option B : le chef de projet devrait commencer par faciliter l’identification et la priorisation des exigences évidentes, contribuant ainsi à l’élaboration du Product Backlog. Ensuite, puisque le projet suit une approche Agile, il devrait faire exécuter le travail de manière itérative et incrémentale. Option C : définir toutes les itérations nécessaires à l’achèvement du projet relève d’une planification prédictive. Option D : les références de base du projet ne sont définies que dans les projets prédictifs.', 'Since the project is large and deliverables are vague, it might not be possible to make the project scope clearer and remove ambiguity before starting implementation. In that case, the predictive approach would be more suitable than agile. Needless to say the agile coach’s role does not involve clarifying the scope of work, it rather entails helping the project team embrace an agile mindset. The project manager should start by facilitating the identification and prioritization of evident requirements, hence helping with the elaboration of the product backlog. Next, and since the project is following an agile approach, the project manager should execute work iteratively and incrementally. Defining all of the iterations needed for completing the project refers to predictive planning. Project baselines are only specified in predictive projects.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Scope', 'Scope', 'Agile', 'Agile', true),
('L3Q14', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet qui adopte un style de leadership serviteur intègre un nouveau membre de l’équipe. Il lui remet une copie de la charte de projet et s’engage à lui envoyer une copie de ________________, qui couvre les valeurs de l’équipe, les règles de base et les accords de travail.', 'A project manager who adopts a servant leadership style is onboarding a new team member. The project manager gives the team member a copy of the project charter and commits to sending them a copy of ________________, which covers team values, ground rules, and working agreements.', '["Contrat de travail", "Plan de management des ressources", "Plan de management des communications", "Charte d’équipe"]'::jsonb, '["The employment contract", "The resource management plan", "The communication management plan", "The team charter"]'::jsonb, '[3]'::jsonb, 'Une charte d’équipe est un document élaboré collectivement afin de clarifier l’orientation de l’équipe tout en établissant ses limites. Elle est créée lors de la phase de formation de l’équipe afin de favoriser la compréhension et l’adhésion. Elle aligne l’équipe sur les règles de base, les valeurs de l’équipe, les modalités des réunions, les accords de travail ainsi que d’autres normes du groupe (PMBOK, 8e édition, page 142).', 'A team charter is a document that is developed in a group setting to clarify team direction while also establishing boundaries. It is created at the team’s forming phase in order to encourage understanding and buy-in. A team charter aligns the team with ground rules, team values, meeting guidelines, working agreements, as well as other group norms (PMBOK 8th edition, page 142).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Hybrid', 'Hybrid', true),
('L3Q15', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un projet a été entravé par de nombreux problèmes de qualité, ce qui le met en danger. Quelle réunion le chef de projet devrait-il organiser avec l’équipe afin de déterminer comment éviter ou traiter de tels problèmes à l’avenir ?', 'A project has been hampered by many quality issues, putting the project at risk. Which meeting should the project manager conduct with the team to figure out how to avoid or deal with such problems in the future? Kick-off', '["Lancement", "Leçons apprises", "Revue des risques", "Team building"]'::jsonb, '["Kick-off", "Lessons learned", "Risk review", "Team building"]'::jsonb, '[1]'::jsonb, 'Option A : les réunions de lancement servent à communiquer les objectifs du projet et à garantir l’engagement des parties prenantes envers le projet. Option B : les réunions sur les leçons apprises sont des séances rétrospectives collaboratives destinées à discuter des réussites et des erreurs du projet, à les documenter et à recueillir des retours à leur sujet. Elles sont indispensables pour permettre à l’équipe projet de tirer les enseignements des erreurs précédentes et d’améliorer les processus et projets futurs. Elles devraient être organisées chaque fois que nécessaire afin d’examiner la progression du projet, de consigner les enseignements importants et de définir de nouvelles pistes d’amélioration (PMBOK, 8e édition, page 194). Option C : les réunions de revue des risques servent à vérifier l’état des risques existants et à en identifier de nouveaux. Toutefois, la consignation des leçons apprises à partir des risques actuels ou clos intervient généralement au cours des réunions sur les leçons apprises. Option D : les activités de team building visent à accroître la collaboration entre les membres de l’équipe (PMBOK, 8e édition, page 205).', 'Kick-off meetings are meant for communicating the objectives of the project and ensuring the stakeholders’ commitment to the project. Lessons learned meetings are collaborative retrospective sessions for discussing, documenting, and soliciting feedback about the project''s successes and missteps. These meetings are a must for the project team to learn from previous mistakes and improve future processes and projects. Lessons learned meetings should be held whenever needed, to review the way a project has been progressing, note important learnings, and set new ways for amelioration (PMBOK 8th Edition, page 194). Risk review meetings are used to verify the status of existing risks and identify new ones. However, capturing lessons learned from current or closed risks commonly happens in the lessons learned meetings. Team building activities aim to increase collaboration among team members (PMBOK 8th Edition, page 205).', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'resources and Risks', 'Resources and Risks', 'Hybrid', 'Hybrid', true),
('L3Q16', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Pendant la phase de planification du projet, les parties prenantes ont insisté pour que leurs exigences contradictoires soient toutes prises en compte et consolidées. Il est alors devenu difficile pour le chef de projet d’élaborer un plan satisfaisant toutes les parties prenantes. Que devrait-il faire pour établir un terrain d’entente ?', 'During the project planning phase, stakeholders insisted that their conflicting requirements should all be considered and consolidated. That made it hard for the project manager to create a plan that satisfied all stakeholders. What should the project manager do to establish a common ground?', '["Constituer des groupes de discussion réunissant les parties prenantes concernées afin de discuter des intérêts contradictoires et de les résoudre.", "Créer un document expliquant son point de vue personnel et demander aux parties prenantes en désaccord de l’examiner.", "Donner à chaque partie prenante l’occasion de rédiger un énoncé des travaux, puis fusionner tous les documents pour créer l’énoncé du périmètre du projet.", "Utiliser son autorité et sa position de chef de projet pour décider quelles exigences devraient être priorisées."]'::jsonb, '["Build focus groups involving concerned stakeholders to discuss and resolve conflicting interests.", "Create a document explaining their personal point of view and ask conflicting stakeholders to review it.", "Give each stakeholder the opportunity to write a statement of work, and then merge all documents to create the project scope statement.", "Use their authorization and position as the project manager to decide which requirements should be prioritized."]'::jsonb, '[0]'::jsonb, 'Les groupes de discussion réunissent les parties prenantes et les experts en la matière afin qu’ils échangent de manière interactive et recueillent des informations sur leurs attentes et leurs attitudes à l’égard d’un service, d’un produit ou d’un résultat proposé (PMBOK, 8e édition, page 171).', 'Focus groups bring together stakeholders and subject matter experts to interactively discuss and learn about their expectations and attitudes towards a proposed service, product, or result (PMBOK 8th edition, page 171).', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Stakeholders', 'Stakeholders', 'Predictive', 'Predictive', true),
('L3Q17', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Quel que soit le type d’approche de développement qu’un chef de projet adopte pour son projet, sa priorité absolue devrait toujours être :', 'Regardless of the type of development approach that a project manager adopts for their project, their top priority should always be:', '["Une documentation à jour", "Une collaboration efficace et de solides relations avec toutes les parties prenantes du projet", "Satisfaire les clients en répondant aux exigences du projet", "Élaborer un plan robuste et répondre aux demandes de changement"]'::jsonb, '["Up-to-date documentation", "Efficient collaboration and strong relationships with all project stakeholders", "Satisfying customers by fulfilling project requirements", "Elaborating a robust plan and responding to change requests"]'::jsonb, '[2]'::jsonb, 'Dans toute activité, les clients ou les sponsors doivent constituer la priorité absolue lors de la livraison d’un produit. Il ne suffit pas de livrer un produit fonctionnel ; celui-ci doit répondre aux besoins du client ou du sponsor.', 'In any business, customers or sponsors have to be the highest priority when delivering a product. It’s not enough to deliver a functioning product; the product must work for the customer or the sponsor’s needs.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Stakeholders', 'Stakeholders', 'Hybrid', 'Hybrid', true),
('L3Q18', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Après un an de management d’un projet prédictif, et au cours du processus de clôture du projet, le chef de projet fait face au refus d’une partie prenante clé de valider les livrables en raison d’allégations de non-conformité. Que peut-il faire pour obtenir l’acceptation de cette partie prenante ?', 'One year into managing a predictive project, and during the close project process, the project manager faces a key stakeholder’s refusal to sign off the deliverables due to non-compliance claims. What can the project manager do to ensure stakeholder acceptance?', '["Émettre une demande de changement", "Organiser une rétrospective de sprint", "Modifier l’énoncé des travaux (SOW)", "Effectuer une analyse des écarts"]'::jsonb, '["Issue a change request", "Conduct a sprint retrospective", "Change the SOW", "Conduct a variance analysis"]'::jsonb, '[3]'::jsonb, 'L’analyse des écarts est une technique utilisée à la fin d’un projet ou d’une phase afin d’identifier tout écart dans les livrables ou toute différence entre les comportements réels et planifiés. Cette méthode permet de déterminer la cause et l’ampleur de la différence entre la référence de base et la performance réelle, ainsi que de conserver la maîtrise du projet (PMBOK, 8e édition, page 211, et PMI Guide to Business Analysis, page 278).', 'Variance analysis is a technique used at the end of a project or phase in order to identify any deviation in deliverables or difference between actual and planned behaviors. This method is used to determine the cause and magnitude of the difference between baseline and actual performance, as well as retain control over the project (PMBOK 8th edition, page 211 & PMI Guide to Business Analysis, page 278).', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Predictive', 'Predictive', true),
('L3Q19', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Dans une structure organisationnelle par projets, après avoir obtenu l’approbation des livrables par le client et officiellement clôturé le projet, quelle devrait être l’étape suivante pour le chef de projet ?', 'In a projectized organization structure, after getting the client’s approval of deliverables and officially closing the project, what should be the project manager''s next step? Perform a final quality inspection.', '["Effectuer une inspection finale de la qualité.", "Informer le responsable fonctionnel afin qu’il affecte l’équipe à un autre projet.", "Vérifier s’il reste des tâches en attente ou inachevées.", "Libérer l’équipe projet."]'::jsonb, '["Perform a final quality inspection.", "Inform the functional manager so they can assign the team to another project.", "Check for any pending or incomplete tasks.", "Release the project team."]'::jsonb, '[3]'::jsonb, 'Option A : les inspections de la qualité sont effectuées avant d’obtenir l’approbation du client. Option B : contrairement aux organisations fonctionnelles, les organisations par projets ne comportent pas de responsables fonctionnels ou, si elles en ont, leur rôle et leur autorité sont assez limités. Option C : la vérification de l’achèvement de toutes les tâches du projet devrait également être effectuée avant la livraison du produit final au client, puisqu’elle fait partie de l’audit qualité. Option D : dans les organisations par projets ou orientées projet, toutes les activités sont gérées au moyen de projets. Une fois le projet achevé, le chef de projet libère les membres de l’équipe afin qu’ils puissent passer au projet suivant (PMBOK, 8e édition, page 22).', 'Quality inspections are performed before getting the client’s approval. Unlike functional organizations, projectized organizations have no functional managers, and if they do, their role and authority are quite limited. Checking whether all project tasks are completed should be also carried out before delivering the final product to the client since it’s part of the quality audit. In projectized or project-oriented organizations, all activities are managed through projects. Upon completion of the project, the project manager releases the team members to move on to the next project (PMBOK 8th Edition, page 22).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Predictive', 'Predictive', true),
('L3Q20', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet reçoit constamment des retours négatifs concernant l’un des fournisseurs du projet. Les conflits entre l’équipe projet et l’équipe du fournisseur se sont récemment aggravés et commencent à avoir une incidence négative sur le projet. Que devrait faire le chef de projet ensuite ?', 'A project manager keeps receiving negative feedback concerning one of the project suppliers. The conflicts between the project team and the supplier’s team are getting worse recently and are starting to have a negative impact on the project. What should the project manager do next?', '["Envoyer un e-mail au responsable de l’équipe du fournisseur pour lui expliquer la situation alarmante.", "Rencontrer le responsable de l’équipe du fournisseur afin de discuter du problème.", "Appeler le responsable de l’équipe du fournisseur et l’exhorter à respecter l’accord d’approvisionnement.", "Recourir à un mode alternatif de règlement des différends (ADR)."]'::jsonb, '["Send an email to the supplier’s team manager explaining the alarming situation.", "Meet with the supplier’s team manager to discuss the issue.", "Call the supplier’s team manager and urge them to commit to the procurement agreement.", "Proceed with Alternative Dispute Resolution (ADR)."]'::jsonb, '[1]'::jsonb, 'Lorsqu’on souhaite résoudre un conflit, une réunion en face à face constitue toujours la meilleure première étape. Le chef de projet devrait donc rencontrer le responsable de l’équipe du fournisseur afin de discuter du problème et de tenter de trouver une solution. Options A et C : les autres moyens de communication, tels que l’envoi d’un e-mail ou un appel téléphonique, sont moins efficaces qu’une réunion en personne. Option D : si la négociation directe échoue, le chef de projet devrait alors recourir à un mode alternatif de règlement des différends (ADR), tel que la médiation ou l’arbitrage (PMBOK, 8e édition, page 253).', 'When you want to resolve a conflict, a face-to-face meeting is always the best first step. Hence, the project manager should meet with the manager of the supplier’s team to discuss the issue and try to find a solution. Option A: Other communication methods, such as sending an email or having a phone call, are less effective than an in-person meeting. Option D: If direct negotiation fails, then the project manager should proceed with Alternative Dispute Resolution (ADR), such as mediation or arbitration (PMBOK 8th Edition, page 253).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Predictive', 'Predictive', true),
('L3Q21', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Pour la prochaine release, le Product Owner a sélectionné plusieurs user stories totalisant 110 points. Sachant que la vélocité de l’équipe est de 20 story points, quelle est la durée estimée nécessaire pour achever cette release ?', 'For the next release, the product owner has selected a number of user stories totaling 110 points. Given that the team’s velocity is 20 story points, what’s the estimated duration to complete this release?', '["5 sprints", "5,5 sprints", "6 sprints", "Il n’est pas possible de calculer le nombre estimé de sprints nécessaires pour achever une release en Agile."]'::jsonb, '["5 sprints", "5.5 sprints", "6 sprints", "It’s not possible to calculate the estimated number of sprints to complete a release in Agile."]'::jsonb, '[2]'::jsonb, 'Une release de 110 story points nécessitera 6 sprints pour être achevée par une équipe dont la vélocité est de 20 story points. Même si la division de 110 par 20 donne 5,5 sprints, le nombre d’itérations doit être un nombre entier, car la timebox prédéterminée d’un sprint ne doit pas être modifiée. En Scrum, il est possible de calculer le nombre estimé de sprints dès lors que la vélocité de l’équipe et l’estimation de la charge de travail sont connues. Il faut toutefois garder à l’esprit qu’il s’agit d’une estimation et non d’un engagement, puisque des changements peuvent survenir en cours de route.', 'A release of 110 story points takes 6 sprints to be completed by a team that has 20 story points’ velocity. Even though dividing 110 by 20 equals 5.5 sprints, the number of iterations should be an integer since the predetermined timebox of a sprint should not be changed. In Scrum, it’s possible to calculate the estimated number of sprints as long as the velocity of the team and the estimation of the workload are known. But, you need to keep in mind that this is an estimation rather than a commitment since changes could happen along the way.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Schedule', 'Schedule', 'Agile', 'Agile', true),
('L3Q22', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Le périmètre de l’analyse business est :', 'The scope of business analysis is:', '["Orienté projet", "Orienté produit", "Orienté produit et projet", "Aucune des réponses ci-dessus"]'::jsonb, '["Project-oriented", "Product-oriented", "Product and project-oriented", "None of the above"]'::jsonb, '[1]'::jsonb, 'L’analyse business se concentre principalement sur les caractéristiques et les fonctions qui définissent une solution ; son périmètre est donc orienté produit. Option C : le management de projet est l’application des connaissances, compétences, outils et techniques aux activités du projet afin d’atteindre ou de dépasser la valeur visée ; son périmètre est donc à la fois orienté produit et projet (PMBOK, 8e édition, page 271).', 'Business analysis primarily concentrates on the features and functions that define a solution, making its scope product-oriented. Option C: Project management is the application of knowledge, skills, tools, and techniques to project activities to meet or exceed the intended value, making its scope both product-oriented and project-oriented (PMBOK 8th Edition, page 271).', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Hybrid', 'Hybrid', true),
('L3Q23', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'multiple', 'Laquelle des affirmations ci-dessous représente la définition la plus exacte du backlog refinement ? (Choisissez trois réponses.)', 'Which of the below statements represents the most accurate definition of backlog refinement? (Select three)', '["Le processus de création de la liste initiale des exigences du produit, autrefois appelé backlog grooming.", "Le moment où le Product Owner ou les membres de l’équipe examinent le backlog afin de s’assurer qu’il contient les éléments appropriés.", "L’élaboration continue des exigences du projet afin de satisfaire les besoins des parties prenantes.", "L’activité continue consistant à rédiger, mettre à jour et prioriser les exigences."]'::jsonb, '["The process of creating the initial list of product requirements, formerly known as backlog grooming.", "When the product owner or team members review the backlog to make sure it has the proper items.", "The continuous elaboration of project requirements to satisfy the stakeholders’ needs.", "The continuous activity of writing, updating, and prioritizing requirements."]'::jsonb, '[1, 2, 3]'::jsonb, 'Le backlog refinement (anciennement appelé backlog grooming) a lieu lorsque le Product Owner, avec certains membres de l’équipe ou l’ensemble de celle-ci, vérifie que le backlog contient les éléments appropriés, que ces éléments sont priorisés et que ceux placés en tête sont prêts à être livrés (PMBOK, 8e édition, page 149). Cette activité est menée régulièrement et peut prendre la forme d’une réunion officiellement planifiée ou d’une activité continue. Option A : le processus d’élaboration de la liste initiale des exigences du produit correspond à l’élaboration ou à la création du backlog.', 'Backlog refinement (formerly referred to as backlog grooming) occurs when the product owner along with some, or all of the team members checks the backlog to make sure it contains the proper items, that these items are prioritized, and that the ones at the top are ready to be delivered (PMBOK 8th edition, page 149). This activity is carried out regularly and can be either an officially scheduled meeting or an ongoing activity. Option A: The process of developing the initial list of product requirements represents backlog elaboration or creation.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Scope', 'Scope', 'Agile', 'Agile', true),
('L3Q24', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Une entreprise doit sélectionner l’un de deux projets disposant du même budget, mais présentant des rendements et des niveaux de risque différents. Quel outil ou quelle technique devrait-elle utiliser pour prendre la bonne décision ?', 'A company must select one of two projects that have the same budget, but different returns and risk levels. Which tool or technique should be used in order to make the right decision?', '["Arbre de décision", "Diagramme de tornade", "Analyse SWOT", "Analyse de sensibilité"]'::jsonb, '["Decision tree", "Tornado diagram", "SWOT Analysis", "Sensitivity analysis"]'::jsonb, '[0]'::jsonb, 'L’analyse par arbre de décision sert à soutenir l’identification et la sélection du meilleur plan d’action parmi plusieurs options. Chacune de ces branches peut être associée à des coûts et à des risques, comprenant aussi bien des menaces que des opportunités. L’arbre de décision révèle la valeur monétaire attendue de chaque branche, ce qui permet de déterminer et de sélectionner la voie optimale (PMBOK, 8e édition, page 163).', 'The decision tree analysis is used to support the identification and selection of the best course of action among several alternatives. Each of these alternative paths can have associated costs and risks, including both threats and opportunities. The decision tree reveals the expected monetary value of each branch, allowing the determination and selection of the optimal path (PMBOK 8th edition, page 163).', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Finance', 'Finance', 'Predictive', 'Predictive', true),
('L3Q25', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Que signifie « cycle time » ?', 'What does “cycle time” mean?', '["La durée des itérations du projet", "Le temps nécessaire pour examiner une tâche", "Le temps écoulé entre le moment où l’équipe commence à travailler sur une tâche et celui où elle l’achève", "Le temps écoulé entre le moment où une tâche est créée et celui où elle est achevée"]'::jsonb, '["The duration of the project iterations", "The time required to review a task", "The time from the moment the team starts working on a task to the moment they complete it", "The time from the moment a task is created to the moment it’s completed"]'::jsonb, '[2]'::jsonb, 'Le cycle time correspond au temps nécessaire à l’équipe pour achever une tâche. Il est mesuré à partir du moment où l’équipe commence à travailler sur celle-ci (PMBOK, 8e édition, page 213). Option D : le lead time commence au moment où la tâche est ajoutée au tableau et se termine lorsqu’elle est livrée (PMBOK, 8e édition, page 213, et Agile Practice Guide, page 64).', 'The cycle time is how long it takes for the team to complete a task. It’s measured from the time they start working on the task (PMBOK 8th Edition, page 213). Option D: Lead time starts from the moment the task is added to the board until it is delivered (PMBOK 8th Edition, page 213 & the Agile Practice Guide, page 64).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Schedule', 'Schedule', 'Agile', 'Agile', true),
('L3Q26', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Laquelle des affirmations suivantes est vraie au sujet du graphique ci-dessous ?', 'Which statement is true about the following chart? The figure represents a burnup chart of the remaining story points', '["La figure représente un burnup chart des story points restants.", "Tout au long de l’itération, le nombre de story points achevés est toujours supérieur aux prévisions.", "L’équipe avait planifié 14 story points pour l’itération et les a tous achevés.", "À la fin de l’itération, 3 story points ne sont pas achevés."]'::jsonb, '["The figure represents a burnup chart of the remaining story points", "Throughout the iteration, the completed story points are always more than projected", "The team planned 14 story points for the iteration which they completed", "3 story points are unfinished at the end of the iteration"]'::jsonb, '[3]'::jsonb, 'Option A : la figure représente un burndown chart et non un burnup chart. Option B : lorsque la ligne de progression réelle du graphique se situe au-dessus de la progression prévue, cela indique que l’équipe termine moins de story points que ce à quoi elle s’était initialement engagée. Option C : l’équipe avait planifié 14 story points, mais elle n’a pu en achever que 11. Option D : à la fin de l’itération de sept jours, 3 story points restent inachevés.', 'The figure represents a burndown chart and not a burnup chart. When the actual progress line of the chart is above the projected progress, it indicates that the team is finishing fewer story points than what they initially committed to. The team planned 14 story points, but they were only able to finish 11. At the end of the seven-day iteration, 3 story points are left undone.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Schedule', 'Schedule', 'Agile', 'Agile', true),
('L3Q27', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Dans le cadre d’une approche prédictive, laquelle des affirmations suivantes est la plus exacte ?', 'Working with the predictive approach, which of the following is most true?', '["Le décalage peut être déterminé en effectuant un calcul au plus tôt.", "Le décalage est la durée maximale pendant laquelle une tâche peut être retardée sans retarder le début au plus tôt de son successeur.", "Le décalage est un temps d’attente.", "Le décalage est la durée maximale pendant laquelle une tâche peut être retardée sans retarder l’ensemble du projet."]'::jsonb, '["Lag can be determined by making a forward pass.", "Lag is the maximum amount of time a task can be delayed without delaying the early start of its successor.", "Lag is waiting time.", "Lag is the maximum amount of time a task can be delayed without delaying the whole project."]'::jsonb, '[2]'::jsonb, 'Dans une approche prédictive, le décalage correspond à une situation où une activité est achevée, mais où un délai s’écoule avant le début de l’activité suivante (PMBOK, 8e édition, pages 179-180). Par exemple, pour peindre une pièce, il faut d’abord appliquer une couche d’apprêt, puis la laisser sécher pendant deux jours avant d’appliquer la couche finale. Ces deux jours d’attente nécessaires au séchage de l’apprêt constituent le délai de décalage.', 'In a predictive approach, Lag is when an activity is complete and there is a delay before the subsequent activity starts (PMBOK 8th edition, pages 179-180). For example, in order to paint a room, you need to first apply the primer coating, then you have to let it dry for two days before applying the final coat of paint. These two days of waiting for the primer coat to dry are referred to as Lag Time.', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Schedule', 'Schedule', 'Predictive', 'Predictive', true),
('L3Q28', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Avant le démarrage du projet, le Business Analyst classe les parties prenantes selon leur niveau de pouvoir, d’intérêt et d’influence. Cette étape est appelée :', 'Before starting the project, the business analyst is classifying stakeholders according to their level of power, interest, and influence. This step is referred to as:', '["Analyse des parties prenantes", "Identification des parties prenantes", "Surveillance des parties prenantes", "Engagement des parties prenantes"]'::jsonb, '["Stakeholder analysis", "Stakeholder identification", "Stakeholder monitoring", "Stakeholder engagement"]'::jsonb, '[0]'::jsonb, 'Puisque la question précise que les parties prenantes ont déjà été identifiées et que le projet n’a pas encore démarré, l’analyse des parties prenantes est la bonne réponse. Elle consiste à classer toutes les parties prenantes du projet afin d’assurer ultérieurement un engagement efficace. Option D : l’engagement des parties prenantes intervient dans le domaine d’intérêt de l’exécution et comprend la communication et la collaboration avec les parties prenantes afin de répondre à leurs attentes, de traiter les problèmes et de favoriser leur participation appropriée. Option C : la surveillance de l’engagement des parties prenantes consiste à évaluer l’efficacité des efforts d’engagement, à identifier les ajustements nécessaires pour améliorer les relations et à affiner les stratégies ou les plans afin de mieux répondre aux besoins de participation des parties prenantes (PMBOK, 8e édition, page 73).', 'Since the question states that stakeholders were already identified and that the project hasn''t started yet, stakeholder analysis is the right answer. Stakeholder analysis refers to the classification of all project stakeholders in order to ensure efficient engagement later on. Option D: Stakeholder engagement takes place in the execution focus area and it involves: communicating and collaborating with stakeholders to meet their expectations, addressing issues, and fostering appropriate stakeholder involvement. Option C: Stakeholder engagement monitoring involves assessing the effectiveness of stakeholder engagement efforts, identifying necessary adjustments to improve relationships, and refining strategies or plans to better meet stakeholder participation needs (PMBOK 8th edition, page 73).', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Stakeholders', 'Stakeholders', 'Predictive', 'Predictive', true),
('L3Q29', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Laquelle des propositions suivantes décrit le mieux l’analyse business ?', 'Which of the following best describes business analysis? An organizational structure that aims to standardize project-related governance processes.', '["Une structure organisationnelle visant à normaliser les processus de gouvernance liés aux projets.", "Un ensemble de programmes regroupés afin d’atteindre des objectifs business stratégiques.", "L’application des connaissances, compétences, outils et techniques aux activités du projet afin de livrer les solutions du projet.", "Les activités réalisées pour soutenir l’identification et l’analyse des exigences ainsi que l’identification de solutions pertinentes pour un ou plusieurs projets."]'::jsonb, '["An organizational structure that aims to standardize project-related governance processes.", "The collection of programs that have been grouped to achieve strategic business goals.", "The application of knowledge, skills, tools, and techniques to project activities to deliver the project solutions.", "Activities performed to support the identification and analysis of requirements and the identification of solutions relevant to one or many projects."]'::jsonb, '[3]'::jsonb, 'Option A : « une structure organisationnelle visant à normaliser les processus de gouvernance liés aux projets » décrit le Project Management Office (PMO). Le PMO est chargé de normaliser et de superviser les pratiques de management de projet au sein d’une organisation, et non d’effectuer spécifiquement l’analyse business (PMBOK, 8e édition, page 5). Option B : « un ensemble de programmes regroupés afin d’atteindre des objectifs business stratégiques » décrit un portefeuille (PMBOK, 8e édition, page 270). Option C : « l’application des connaissances, compétences, outils et techniques aux activités du projet afin de livrer les solutions du projet » décrit le management de projet (PMBOK, 8e édition, page 271). Le management de projet implique l’application de diverses compétences, de divers outils et techniques afin d’accomplir les tâches du projet et de livrer des solutions. Bien que l’analyse business soutienne le management de projet en définissant les exigences et les solutions, elle ne consiste pas à gérer l’ensemble du projet, responsabilité qui incombe au chef de projet. Option D : l’analyse business comprend les activités qui soutiennent la livraison de solutions alignées sur les objectifs business, garantissant une valeur continue pour l’organisation (PMI Guide to Business Analysis, page 389).', '“An organizational structure that aims to standardize project-related governance processes” describes the Project Management Office (PMO). The PMO is responsible for standardizing and overseeing project management practices within an organization, not specifically for performing business analysis (PMBOK 8th Edition, page 5). “The collection of programs that have been grouped to achieve strategic business goals” describes a portfolio (PMBOK 8th Edition, page 270). “The application of knowledge, skills, tools, and techniques to project activities to deliver the project solutions for a project” describes project management (PMBOK 8th Edition, page 271). Project management involves applying various skills, tools, and techniques to complete project tasks and deliver solutions. While business analysis supports project management by defining requirements and solutions, it is not the same as managing the entire project, which is the role of a project manager. Business analysis involves activities that support the delivery of solutions aligned with business objectives, ensuring continuous value for the organization (PMI Guide to Business Analysis, page 389).', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Hybrid', 'Hybrid', true),
('L3Q30', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Dans une organisation matricielle faible, un chef de projet constate que l’équipe affectée ne possède pas les compétences nécessaires au projet. Que devrait-il faire ensuite ?', 'In a weak matrix organization, a project manager discovers that the assigned team lacks the necessary skills for the project. What should the project manager do next?', '["Émettre une demande de changement afin d’obtenir une équipe plus qualifiée.", "Négocier avec le responsable fonctionnel afin d’obtenir les membres d’équipe requis.", "Soumettre le problème au sponsor du projet.", "Exercer son pouvoir légitime en informant l’organisation qu’il ne réalisera pas le projet sans les ressources nécessaires."]'::jsonb, '["Issue a change request to get a more qualified team.", "Negotiate with the functional manager in order to obtain the required team members.", "Take the matter to the project sponsor.", "Use their legitimate power by informing the organization that they will not perform the project without the needed resources."]'::jsonb, '[1]'::jsonb, 'Dans une organisation matricielle faible, le pouvoir du chef de projet est considérablement limité. Il est plutôt considéré comme un coordinateur ou un facilitateur (PMBOK, 8e édition, page 22). Dans ce type d’organisation, il appartient au responsable fonctionnel d’affecter les ressources. Par conséquent, la seule solution permettant d’obtenir les ressources nécessaires dans cette situation consiste à négocier les besoins avec le responsable fonctionnel.', 'A project manager''s power is considerably low in a weak matrix organization. In fact, they are rather considered a coordinator or an expediter (PMBOK 8th Edition, page 22). It’s up to the functional manager to assign resources in such organizations. Therefore, the only solution to obtain the needed resources in this situation is by negotiating your requirements with the functional manager.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Predictive', 'Predictive', true),
('L3Q31', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un Product Owner qui découvre l’approche Agile a rédigé la user story suivante : « En tant que client, je souhaite une nouvelle fonctionnalité afin d’augmenter mes ventes de 50 %. » Le chef de projet estime que cette user story est insuffisante et explique au Product Owner que :', 'A product owner who’s new to the agile approach wrote the following user story: “As a customer, I want a new functionality so that I can achieve a 50% increase in sales”. The project manager found the user story to be deficient, explaining to the product owner that: The user story should follow a common structure', '["La user story devrait suivre une structure courante.", "La user story devrait être spécifique et testable.", "La user story ne devrait pas contenir de valeurs financières.", "La user story devrait être limitée dans le temps."]'::jsonb, '["The user story should follow a common structure", "The user story should be specific and testable", "The user story should not include financial values", "The user story should be time-bounded"]'::jsonb, '[1]'::jsonb, 'Option A : même si elle respecte le format courant d’une user story, celle rédigée par le Product Owner est vague et imprécise. Le Product Owner doit préciser la nouvelle fonctionnalité qu’il souhaite développer. Option B : la user story rédigée par le Product Owner n’est pas spécifique et ne peut pas être testée. Une bonne user story doit être : « I » Independent (indépendante de toutes les autres), « N » Negotiable (négociable), « V » Valuable (porteuse de valeur), « E » Estimable (estimable avec une approximation acceptable), « S » Small (suffisamment petite pour tenir dans une itération) et « T » Testable (testable) (PMI Guide to Business Analysis, page 223). Option C : il est possible d’inclure des valeurs financières dans une user story dès lors qu’elles contribuent à la rendre plus claire et plus compréhensible. Option D : un objectif peut être limité dans le temps, comme un objectif SMART, mais une user story n’est pas limitée dans le temps.', 'Even if it follows the common format of a user story, the user story written by the product owner is vague and unclear. The product owner must specify what new functionality they are looking to develop. The user story written by the product owner is not specific and cannot be tested. A good user story should be: “I” Independent (of all others) “N” Negotiable “V” Valuable “E” Estimable (to an acceptable approximation) “S” Small (to fit within an iteration) “T” Testable (PMI Guide to Business Analysis, page 223) It’s possible to include financial values in a user story as long as they contribute to making it more clear and more understandable. A goal can be time-bound, i.e., a SMART goal, but a user story is not bounded by time.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Agile', 'Agile', true),
('L3Q32', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'multiple', 'Un Product Owner élabore un plan de release sur la base d’une vélocité prévisionnelle de l’équipe de 50 story points. Cependant, au cours des deux premiers sprints, l’équipe a achevé 37 points au sprint 1 et 35 story points au sprint 2. Que devrait faire le chef de projet Agile dans cette situation ? (Choisissez deux réponses.)', 'A product owner creates a release plan based on a projected team velocity of 50 story points. However, during the first two sprints, the team completed 37 points in sprint 1 and 35 story points in sprint 2. What should the agile project manager do in this situation? (Select two)', '["Informer le Product Owner que, sur la base des données empiriques disponibles, le plan de release ne pourra pas être respecté.", "Utiliser ses compétences en leadership pour motiver l’équipe à atteindre la vélocité estimée.", "Prolonger la durée du sprint jusqu’à l’achèvement des 50 story points.", "Étudier avec le Product Owner la possibilité d’ajouter davantage de ressources à l’équipe."]'::jsonb, '["Inform the product owner that, based on available empirical data, the release plan could not be achieved.", "Use their leadership skills to motivate their team to reach the estimated velocity.", "Extend the duration of the sprint until the 50 story points are completed.", "Study with the product owner the possibility of adding more resources to the team."]'::jsonb, '[0, 3]'::jsonb, 'Scrum utilise des données empiriques pour mesurer la progression du travail ; le chef de projet devrait donc informer le Product Owner que, compte tenu de la performance actuelle, le plan de release n’est pas réalisable. Le Product Owner peut mettre à jour le plan de release ou étudier avec le chef de projet la possibilité d’ajouter davantage de ressources à l’équipe. Option B : la capacité de l’équipe est d’environ 36 story points ; il ne serait donc pas possible de la motiver à atteindre systématiquement 50 points à chaque sprint. Option C : un sprint a une durée limitée par une timebox qui ne doit être prolongée sous aucun prétexte.', 'Scrum uses empirical data to measure work progress, therefore the project manager should let the product owner know that, based on current performance, the release plan is not feasible. The product manager can update the release plan or study with the project manager the possibility of adding more resources to the team. Option B: The capacity of the team is around 36 story points, and it wouldn’t be possible to motivate the team to consistently reach 50 points on each sprint. Option C: A sprint has a timeboxed duration which should not be extended for any reason.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'resources and Risks', 'Resources and Risks', 'Agile', 'Agile', true),
('L3Q33', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'multiple', 'Un membre de l’équipe projet constate que certaines exigences sont absentes de la documentation du projet. Le chef de projet lui demande de résoudre le problème. Quels artefacts le membre de l’équipe peut-il ajouter afin de représenter correctement l’énoncé des exigences ? (Choisissez trois réponses.)', 'A project team member notices that some requirements are missing from the project documentations. The project manager asks the team member to resolve the issue. What artifacts can the team member add to properly reflect the requirements statement? (Select three)', '["Registre des risques", "Cas d’utilisation", "User stories", "Diagramme de Gantt", "Modèles visuels"]'::jsonb, '["Risk register", "Use cases", "User stories", "Gantt chart", "Visual models"]'::jsonb, '[1, 2, 4]'::jsonb, 'L’énoncé des exigences peut être exprimé au moyen d’artefacts tels que les cas d’utilisation, les user stories, les éléments du backlog et les modèles visuels. Option A : le registre des risques est un outil servant à identifier, évaluer et gérer les risques tout au long du projet. Il ne recueille pas les exigences, mais se concentre sur les risques potentiels susceptibles d’affecter le projet. Option D : le diagramme de Gantt est un outil utilisé pour visualiser l’échéancier du projet ; il n’exprime aucune exigence (PMBOK, 8e édition, page 268).', 'Requirements statement can be expressed in artifacts, such as use cases, user stories, backlog items, and visual models. Option A: The risk register is a tool to identify, assess, and manage risks throughout the project. It does not capture requirements but focuses on potential risks that could affect the project. Option D: Gantt chart is a tool used to visualize the project schedule, it does not express any requirements (PMBOK 8th Edition, page 268).', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Hybrid', 'Hybrid', true),
('L3Q34', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Trois lignes de production fabriquent des barres cylindriques en acier de 5 mm de diamètre. Afin de réaliser une inspection qualité, le chef de projet prélève au hasard 10 barres sur chaque ligne. Les résultats de l’inspection, exprimés en millimètres, figurent ci-dessous. Les résultats de la ligne 1 peuvent être décrits comme :', 'Three manufacturing lines are producing 5 mm diameter cylindrical steel bars. In order to perform a quality inspection, the project manager takes 10 random bars from each line. The following are the inspection results in mm measurements. The results of Line 1 can be described as:', '["Exacts", "Précis", "À la fois exacts et précis", "Ni exacts ni précis"]'::jsonb, '["Accurate", "Precise", "Both accurate and precise", "Neither accurate nor precise"]'::jsonb, '[1]'::jsonb, 'Les résultats sont précis, car toutes les mesures sont proches de 4,45 mm (± 0,05 mm). La précision consiste à produire des produits finis dont les dimensions sont similaires, qu’elles soient ou non proches des dimensions requises. Des mesures précises ne sont pas nécessairement proches de la valeur cible ; elles sont simplement proches les unes des autres. Option A : l’exactitude implique de créer des produits dont les dimensions sont proches des exigences.', 'The results are precise because all measurements are close to 4.45mm (+ or - 5mm). Precision entails delivering end-products with similar dimensions, which may or may not be close to the required dimensions. Precise measurements are not necessarily close to the target value; they’re just close to one another. Option A: Accuracy implies creating products with close dimensions to requirements.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Predictive', 'Predictive', true),
('L3Q35', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Une cheffe de projet évalue un projet industriel potentiel. Afin de déterminer si les gains financiers attendus dépasseront l’investissement réalisé aujourd’hui, elle utilise la valeur actuelle nette (VAN) comme outil efficace pour déterminer si le projet sera rentable. Par exemple, une VAN > 0 signifie que :', 'A project manager is evaluating a potential industrial project. To determine whether its anticipated financial gains will outweigh its present-day investment, the project manager uses the Net Present Value (NPV) as an effective tool to help her determine whether the project will be profitable or not. For instance, NPV > 0 means:', '["Le projet perdra de l’argent", "Le projet atteindra le seuil de rentabilité", "Le projet est rentable", "Il est impossible de le savoir tant que le ROI n’a pas été calculé"]'::jsonb, '["The project will lose money", "The project will break even", "The project is profitable", "We can’t know until the ROI is calculated"]'::jsonb, '[2]'::jsonb, 'Plus la valeur actuelle nette (VAN) est élevée, plus le projet sera rentable pour l’organisation. Une VAN positive indique que l’investissement en vaut la peine.', 'The larger the Net Present Value (NPV), the more profitable the project will be for the organization. A positive NPV indicates that the investment is worthwhile.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Finance', 'Finance', 'Predictive', 'Predictive', true),
('L3Q36', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Toutes les propositions suivantes correspondent à des caractéristiques du leadership serviteur, sauf :', 'All of the following imply servant leadership characteristics, except:', '["Favoriser le développement professionnel des membres de l’équipe", "Faire passer les besoins de l’équipe avant toute autre considération", "Planifier la succession en développant de futurs leaders serviteurs", "Recevoir des instructions de l’équipe concernant le travail du projet"]'::jsonb, '["Promoting team members'' professional growth", "Prioritizing the team needs ahead of everything else", "Succession planning by developing future servant leaders", "Taking instructions from the team concerning project work"]'::jsonb, '[3]'::jsonb, 'Un leader serviteur favorise le développement de l’équipe, accorde la priorité à ses besoins et prépare sa succession en développant de futurs leaders serviteurs. Toutefois, ce style de leadership ne signifie pas que le chef de projet doit recevoir des instructions de son équipe (PMBOK, 8e édition, page 197).', 'A servant leader promotes team growth, prioritizes their needs, and plans for successors by developing future servant leaders. This leadership style, however, does not entail that the project manager has to take instructions from their team (PMBOK 8th Edition, page 197).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Hybrid', 'Hybrid', true),
('L3Q37', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Les mesures de performance d’un projet sont calculées à partir des informations suivantes : VA = 2 000 $ et CR = 1 000 $. Quel est l’état du projet ?', 'A project’s performance measurements are calculated based on the following information: EV = $2,000 and AC = $1,000. What is the status of the project?', '["Le projet est en avance sur l’échéancier", "Le projet est en retard sur l’échéancier", "Le projet est en dessous du budget", "Le projet dépasse le budget"]'::jsonb, '["The project is ahead of schedule", "The project is behind schedule", "The project is under budget", "The project is over budget"]'::jsonb, '[2]'::jsonb, 'L’indice de performance des coûts (IPC) mesure la conformité entre le travail réellement accompli, c’est-à-dire la valeur acquise (VA), et le coût réel engagé (CR) : IPC = VA / CR = 2 000 $ / 1 000 $ = 2, ce qui signifie que le projet est en dessous du budget (PMBOK, 8e édition, page 208). Options A et B : l’indice de performance de l’échéancier (IPE) mesure la conformité de la progression réelle à la progression planifiée (IPE = VA / VP). Puisque la VP est inconnue, il est impossible de déterminer si le projet est en retard ou en avance sur l’échéancier (PMBOK, 8e édition, page 209).', 'The CPI (Cost Performance Index) is a measure of the conformance of the actual work completed (EV, Earned Value) with the incurred Actual Cost (AC): CPI = EV / AC = $2,000 / $1,000 = 2 which means that the project is under budget (PMBOK 8th Edition, page 208). Options A & B: The Schedule Performance Index (SPI) measures the conformance of actual progress to the planned progress (SPI = EV / PV). Since the PV is unknown, we can’t find out if the project is behind or ahead of schedule (PMBOK 8th Edition, page 209).', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Finance', 'Finance', 'Predictive', 'Predictive', true),
('L3Q38', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet élabore le business case d’un projet de transport écologique. Pour ce faire, il décide d’utiliser la technique SWOT. Comment devrait-il appliquer cette technique ?', 'A project manager is developing the business case of a green transportation project. To do so, they decide to use the SWOT technique. How should the project manager apply this technique?', '["Suivre un cycle Plan-Do-Check-Act (cycle PDCA)", "Évaluer le modèle business en recourant au jugement d’expert", "Identifier les forces et les faiblesses du projet", "Réaliser une analyse coûts-avantages"]'::jsonb, '["Follow a Plan-Do-Check-Act cycle (PDCA Cycle)", "Assess the business model using expert judgment", "Identify the project''s strengths and weaknesses", "Conduct a benefit/cost analysis"]'::jsonb, '[2]'::jsonb, 'SWOT signifie Strengths, Weaknesses, Opportunities and Threats, soit forces, faiblesses, opportunités et menaces. Il s’agit d’un outil utilisé par les chefs de projet pour évaluer les opportunités et les menaces auxquelles ils pourraient être confrontés, ainsi que les forces et les faiblesses de leurs projets (PMBOK, 8e édition, page 204). Option A : le cycle PDCA est une technique de management de la qualité utilisée pour maîtriser et améliorer continuellement les processus et les produits (PMBOK, 8e édition, page 158). Options B et D : l’évaluation du modèle business du projet ou la réalisation d’une analyse coûts-avantages peuvent faire partie de l’élaboration du business case, mais ces deux méthodes ont un objectif différent de celui de la technique SWOT.', 'SWOT stands for Strengths, Weaknesses, Opportunities, and Threats. It’s a tool that project managers use to assess the opportunities and threats they might face, as well as their projects’ strengths and weaknesses (PMBOK 8th edition, page 204). Option A: The PDCA cycle is a quality management technique to control and continuously improve processes and products (PMBOK 8th Edition, page 158). Options B & D: Assessing the project’s business model or conducting a benefit/cost analysis could be part of developing the business case, but both methods have a different purpose from the SWOT technique.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'resources and Risks', 'Resources and Risks', 'Predictive', 'Predictive', true),
('L3Q39', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Le Product Owner devrait trier les éléments du Product Backlog en plaçant :', 'The product owner should sort the product backlog items by placing:', '["Les éléments les plus faciles en haut", "Les éléments ayant le moins de valeur en bas", "Les éléments les plus récents en haut", "Les éléments les moins clairs en haut"]'::jsonb, '["The easiest items at the top", "The less valuable items at the bottom", "The most recent items at the top", "The less clear items at the top"]'::jsonb, '[1]'::jsonb, 'Le Product Owner est chargé de placer les éléments les plus clairs et ayant le plus de valeur en haut du Product Backlog. Par conséquent, les éléments ayant le moins de valeur sont déplacés vers le bas (Agile Project Management for Dummies, page 178). Options A et C : les éléments du Product Backlog ne doivent pas être organisés chronologiquement ni selon leur niveau de difficulté.', 'The product owner is responsible for placing the clearest and most valuable items at the top of the product backlog. Consequently, less valuable items will be dragged to the bottom (Agile Project Management for Dummies, Page 178). Options A & C: Product backlog items should not be organized chronologically or according to their difficulty level.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Scope', 'Scope', 'Agile', 'Agile', true),
('L3Q40', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet dirige un projet complexe avec un sponsor très exigeant qui souhaite recevoir des mises à jour fréquentes sur l’avancement du projet et les plans futurs. Quelle est la meilleure manière pour le chef de projet de communiquer avec le sponsor ?', 'A project manager is leading a complex project with a very demanding sponsor who wants frequent updates on project progress and future plans. What’s the best way for the project manager to communicate with the sponsor?', '["Envoyer un rapport mensuel complet détaillant tous les aspects de l’avancement du projet concernant le périmètre, l’échéancier, les coûts, les risques, etc.", "Planifier une réunion mensuelle en face à face afin de discuter de l’état du projet.", "Organiser des réunions hebdomadaires ou bimensuelles et informer le sponsor qu’il est invité à participer aux daily standups.", "Organiser une réunion toutes les deux semaines et donner au sponsor l’accès au logiciel de management de projet afin qu’il obtienne des mises à jour en temps réel sur l’état du projet."]'::jsonb, '["Send a comprehensive monthly report detailing all project progress aspects regarding scope, schedule, cost, risks, etc.", "Schedule a monthly face-to-face meeting to discuss the project status.", "Set up weekly or bi-weekly meetings and inform the sponsor that they are welcome to attend daily standups.", "Hold a bi-weekly meeting and give the sponsor access to the project management software for real-time updates on the project status."]'::jsonb, '[2]'::jsonb, 'Puisque le projet est complexe, une communication fréquente est nécessaire. La meilleure option consiste donc à planifier des réunions régulières une ou deux fois par semaine, avec la possibilité de participer aux standups afin d’obtenir des mises à jour quotidiennes. Option B : des réunions mensuelles, même en face à face, ne sont pas efficaces pour des projets complexes. Option D : donner accès au logiciel de management de projet constitue une communication de type pull, puisque le sponsor doit rechercher lui-même l’information. Une communication pull peut ne pas être suffisante pour les parties prenantes exigeantes disposant d’un pouvoir élevé.', 'Since the project is complex, frequent communication is required. Therefore, the best option is to schedule regular meetings once or twice a week, with the possibility of attending standup meetings to get daily updates. Option B: Monthly meetings, even if they’re face-to-face, are not efficient for complex projects. Option D: Giving access to the project management software is considered pull communication since the sponsor has to seek information themself. Pull communication might not be sufficient for high-power demanding stakeholders.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Stakeholders', 'Stakeholders', 'Hybrid', 'Hybrid', true),
('L3Q41', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Dans un contexte de communication classique, les éléments qui perturbent la transmission et la compréhension du message du chef de projet sont appelés :', 'In a typical communication context, elements interfering with the transmission and understanding of the project manager’s message are called:', '["Média", "Bruit", "Décodage", "Contrainte"]'::jsonb, '["Medium", "Noise", "Decode", "Constraint"]'::jsonb, '[1]'::jsonb, 'Dans un contexte de communication classique et selon le modèle émetteur-récepteur, tout ce qui entrave la transmission et la compréhension d’un message est appelé bruit (PMBOK, 8e édition, pages 153-154). Options A et C : les principaux éléments du processus de communication comprennent également l’encodage des pensées ou des idées, le message résultant de cet encodage, un média servant à transmettre le message et le décodage du message afin de le convertir de nouveau en information porteuse de sens.', 'In a typical communication context, and according to the sender-receiver model, anything that obstructs the transmission and comprehension of a message is called noise (PMBOK 8th Edition, pages 153-154). Option A & C: The key components of the communication process also include encoding thoughts or ideas, a message as the output of encoding, a medium to transmit the message, and decoding the message back into meaningful information.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Stakeholders', 'Stakeholders', 'Hybrid', 'Hybrid', true),
('L3Q42', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'multiple', 'Parmi les outils et techniques suivants, lesquels sont utilisés pour l’analyse des parties prenantes ? (Choisissez deux réponses.)', 'Which of the following tools and techniques are used for stakeholders analysis? (Select two)', '["Matrice RACI", "Arbre de décision", "Analyse des personas", "Groupes de discussion"]'::jsonb, '["RACI matrix", "Decision tree", "Persona analysis", "Focus groups"]'::jsonb, '[0, 2]'::jsonb, 'Afin d’analyser correctement les parties prenantes du projet, un Business Analyst peut utiliser un ou plusieurs des outils suivants (PMI Guide to Business Analysis, page 115) : Analyse des emplois : cette technique sert à déterminer les compétences, les qualifications et les aptitudes nécessaires pour un emploi ou un rôle donné. Analyse des personas : l’analyse des personas consiste à créer un personnage fictif, appelé persona, qui représente une personne ou un groupe de parties prenantes appartenant à une catégorie d’utilisateurs. Cartographies des parties prenantes : elles peuvent comprendre des matrices illustrant l’influence et l’impact de chaque partie prenante. Matrice RACI : cet outil vise à clarifier les responsabilités des parties prenantes en indiquant, pour chaque activité du projet, qui est Réalisateur, Approbateur, Consulté et Informé. Il contribue à assurer une communication efficace et une gestion appropriée des attentes des parties prenantes. Option B : un arbre de décision est un outil utilisé pour la prise de décision et l’analyse des différents résultats associés à divers choix. Option D : les groupes de discussion réunissent des parties prenantes présélectionnées et des experts en la matière afin de recueillir des informations sur leurs attentes et leurs attitudes à l’égard d’une solution proposée.', 'In order to properly analyze the project stakeholders, a business analyst can use one or more of these tools (PMI Guide to Business Analysis, page 115): Job analysis: This technique is employed to determine the skills, qualifications, and competencies needed for a particular job or role. Persona analysis: Persona analysis involves creating a fictional character, known as a persona, to represent an individual or a group of stakeholders within a user class. Stakeholders maps: Stakeholder maps can include matrices that illustrate the influence and impact of each stakeholder. RACI matrix: This a tool designed to clarify stakeholder responsibilities by mapping out who is Responsible, Accountable, Consulted, and Informed for each project activity. It helps ensure effective communication and management of stakeholder expectations throughout the project. Option B: A decision tree is a tool used for decision-making and analyzing different outcomes of various choices. Option D: Focus groups assemble prequalified stakeholders and subject matter experts (SMEs) to gather insights into their expectations and attitudes toward a proposed solution.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Stakeholders', 'Stakeholders', 'Hybrid', 'Hybrid', true),
('L3Q43', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet dirige un projet d’une durée d’un an. Cinq mois après le début de la phase d’exécution, 50 % du travail du projet est achevé. Quel est l’IPE du projet et quel est son état ?', 'A project manager is leading a one-year project. Five months into the execution phase, %50 of the project work is completed. What is the project’s SPI and status?', '["L’IPE est de 0,83 et le projet est en retard sur l’échéancier", "L’IPE est de 0,83 et le projet est en avance sur l’échéancier", "L’IPE est de 1,2 et le projet est en retard sur l’échéancier", "L’IPE est de 1,2 et le projet est en avance sur l’échéancier"]'::jsonb, '["The SPI is 0.83 and the project is behind schedule", "The SPI is 0.83 and the project is ahead of schedule", "The SPI is 1.2 and the project is behind schedule", "The SPI is 1.2 and the project is ahead of schedule"]'::jsonb, '[3]'::jsonb, 'VA = pourcentage du travail achevé × BAA (budget à l’achèvement) = (6/12) × BAA. Puisque le chef de projet en est au cinquième mois du projet, la VP = (5/12) × BAA. En effectuant le calcul, IPE = VA / VP = 6 / 5 = 1,2. Il est également possible de conclure, sans effectuer de calcul, que le projet est en avance sur l’échéancier puisque la moitié du travail est achevée avant que la moitié de la durée du projet ne soit écoulée. Puisque le projet est en avance sur l’échéancier, il suffit de choisir la réponse dans laquelle l’IPE est supérieur à 1 (PMBOK, 8e édition, page 209).', 'EV = % of completed work X BAC (Budget at Completion) = (6/12) X BAC. Since the project manager is 5 months into the project, then the PV = (5/12) X BAC. Doing the math, SPI = EV / PV = 6 / 5 = 1.2. You can also conclude that the project is ahead of schedule without doing any math since half of the work is done before reaching half of the project duration. Since the project is ahead of schedule, you should just select the answer where the SPI is greater than 1 (PMBOK 8th Edition, page 209).', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Schedule', 'Schedule', 'Predictive', 'Predictive', true),
('L3Q44', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Au cours d’un atelier consacré à l’approche Agile, le chef de projet affirme que les équipes Agile doivent être pluridisciplinaires et auto-organisées, en expliquant que :', 'During a workshop about the Agile approach, the project manager stated that Agile teams should be cross-functional and self-organizing, explaining that:', '["Chaque membre de l’équipe doit être pluridisciplinaire et auto-organisé.", "L’équipe Agile doit posséder toutes les compétences requises pour livrer elle-même le produit.", "L’équipe Agile doit posséder des compétences complémentaires et être en mesure d’organiser elle-même le backlog.", "L’équipe Agile doit s’auto-organiser afin d’acquérir les compétences nécessaires pour devenir pluridisciplinaire."]'::jsonb, '["Each member of the team should be cross-functional and self-organized.", "The Agile team should have all the required skills to deliver the product on their own.", "The Agile team should have complementary skill sets and be able to organize the backlog by themselves.", "The Agile team should self-organize to acquire the necessary skills to be cross-functional."]'::jsonb, '[1]'::jsonb, 'Une équipe pluridisciplinaire est un groupe de personnes qui possèdent différents ensembles de compétences substantielles, suffisantes pour atteindre efficacement leur objectif commun. Une équipe auto-organisée est autonome en ce sens qu’elle ne dépend d’aucune personne extérieure pour déterminer la meilleure manière d’accomplir son travail. Cela ne signifie pas que chaque membre de l’équipe possède toutes les compétences nécessaires à la livraison du produit ; chacun doit simplement être compétent dans son domaine d’expertise.', 'A cross-functional team is a group of individuals who acquire different substantial skill sets that are enough to accomplish their common goal proficiently. A self-organizing team is autonomous in the sense that it does not rely on any outsiders to figure out how to best accomplish its work. This does not mean that each team member possesses all of the necessary skills for delivering the product; rather, they just need to be competent in their area of expertise.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'resources and Risks', 'Resources and Risks', 'Agile', 'Agile', true),
('L3Q45', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Une cheffe de projet prévoit de discuter avec sa responsable de la nécessité d’obtenir des ressources supplémentaires pour réaliser des tâches complexes que son équipe ne peut pas exécuter. Ces ressources seront libérées du projet une fois les tâches achevées. Quelles compétences sont les plus essentielles pour la cheffe de projet dans cette situation ?', 'A project manager plans to discuss with her manager the need for additional resources to handle complex tasks her team cannot perform. These resources will be released from the project once the tasks are completed. Which skills are most crucial for the project manager in this situation?', '["Des compétences en planification pour déterminer les besoins en ressources", "Des compétences interpersonnelles pour convaincre sa responsable d’affecter des ressources supplémentaires", "Des compétences en conduite d’entretien pour recruter les ressources nécessaires", "Des compétences techniques pour traiter le risque lié à l’ajout de ressources"]'::jsonb, '["Planning skills to determine resource requirements", "Interpersonal skills to persuade her manager to allocate additional resources", "Interviewing skills to recruit the necessary resources", "Technical skills to address the risk associated with adding more resources"]'::jsonb, '[1]'::jsonb, 'Convaincre la direction nécessite le recours à des compétences interpersonnelles, souvent indispensables lors de l’acquisition des ressources. Option A : la cheffe de projet peut manquer de compétences en planification puisqu’elle n’a pas identifié le besoin en ressources dès le départ, mais cette situation ne porte ni sur cet aspect ni sur la nécessité de répondre au risque associé à l’ajout de ressources. Option C : si sa responsable accepte sa demande, la cheffe de projet peut ne pas avoir à engager un processus de recrutement si les ressources sont déjà disponibles au sein de l’organisation.', 'Trying to convince upper management requires the use of interpersonal skills, which are often needed when acquiring resources. Option A: The project manager may lack planning skills since she didn’t identify the resource requirement from the beginning, but this situation does not tackle this aspect or the need to respond to the risk associated with adding more resources. Option C: In case the manager accepts her request, the project manager may not need to go through the hiring process if resources are already available within the organization.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Hybrid', 'Hybrid', true),
('L3Q46', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Afin d’adopter un état d’esprit Agile, l’équipe projet peut se poser toutes les questions suivantes pendant le développement du produit, sauf :', 'To adopt an agile mindset, the project team can use all of the following questions while developing the product, except:', '["Quel travail peut être évité afin de se concentrer uniquement sur les tâches hautement prioritaires ?", "Comment l’équipe Agile peut-elle travailler de manière prédictible ?", "Quel travail devrait être priorisé afin d’obtenir un retour précoce ?", "Comment le leadership serviteur peut-il contribuer à l’atteinte des objectifs du projet ?"]'::jsonb, '["What work can be avoided to only focus on high-priority tasks?", "How can the Agile team work in a predictable manner?", "What work should be prioritized in order to obtain early feedback?", "How can servant leadership help the achievement of project goals?"]'::jsonb, '[1]'::jsonb, 'Les équipes Agile ne cherchent pas à prédire le travail du projet ; elles s’efforcent plutôt de se concentrer sur les tâches hautement prioritaires, d’obtenir un retour précoce et d’adopter une approche de leadership serviteur.', 'Agile teams don''t focus on how to predict the project work; instead, they try to focus on high-priority tasks, getting early feedback, and adopting the servant leadership approach.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Gouvernance', 'Gouvernance', 'Agile', 'Agile', true),
('L3Q47', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Le rôle d’un Business Analyst implique une planification initiale approfondie et un recueil détaillé des exigences, principalement au cours des premières phases d’un projet. Dans quelle approche de développement le Business Analyst travaille-t-il ?', 'A business analyst’s role involves extensive upfront planning and detailed requirements gathering primarily in the early stages of a project. In which development approach the business analyst is working?', '["Itérative", "Prédictive", "Incrémentale", "Adaptative"]'::jsonb, '["Iterative", "Predictive", "Incremental", "Adaptive"]'::jsonb, '[1]'::jsonb, 'L’approche prédictive repose sur un plan bien défini et vise à réduire au minimum les changements une fois le projet lancé (PMBOK, 8e édition, page 61). Option D : l’approche adaptative met l’accent sur la flexibilité et la capacité d’adaptation. Les exigences évoluent continuellement en fonction des retours des parties prenantes et des changements affectant les conditions du projet (PMBOK, 8e édition, page 63).', 'The predictive approach relies on a well-defined plan and aims to minimize changes once the project is underway (PMBOK 8th Edition, page 61). Option D: The adaptive approach emphasizes flexibility and adaptability. Requirements are continuously evolving based on stakeholder feedback and changes in project conditions (PMBOK 8th Edition, page 63).', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Predictive', 'Predictive', true),
('L3Q48', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Le chef de projet d’une plateforme d’apprentissage en ligne décide de rendre toutes les informations relatives aux nouvelles releases accessibles aux membres de la plateforme dans la rubrique « Actualités » du site web. Quel type de communication le chef de projet prévoit-il d’utiliser ?', 'A project manager, who manages an online e-learning platform, decided to make all new release information accessible to the platform members under the “News” section on the website. What type of communication is the project manager intends to use?', '["Communication push", "Communication interactive", "Communication pull", "Communication proactive"]'::jsonb, '["Push communication", "Interactive communication", "Pull communication", "Proactive communication"]'::jsonb, '[2]'::jsonb, 'La communication pull est un type de communication dans lequel l’accès à l’information est fourni, mais où le destinataire doit la rechercher et la récupérer de manière proactive. Lorsque la communication a uniquement une finalité informative, la communication pull devrait être utilisée. Si les destinataires ne consultent pas l’information, cela aura peu ou pas d’incidence sur le projet. La communication pull est utilisée pour de grands ensembles d’informations complexes ou pour de vastes publics ; elle exige que les destinataires accèdent au contenu à leur convenance, sous réserve des procédures de sécurité. Ces méthodes comprennent les portails web, les sites intranet, l’apprentissage en ligne, les bases de données de leçons apprises ou les référentiels de connaissances (PMBOK, 8e édition, page 152). Option D : le PMBOK définit trois types de communication : interactive, push et pull. La communication proactive est un terme inventé.', 'Pull communication is a communication type where access to the information is provided, however, the receiver must proactively seek out and retrieve this information. When the communication is solely for informative purposes, pull communication should be used. It will have little to no impact on the project if the recipients do not read it. Pull communication is used for large complex information sets, or for large audiences, and requires the recipients to access the content at their own discretion subject to security procedures. These methods include web portals, intranet sites, e-learning, lessons learned databases, or knowledge repositories (PMBOK 8th Edition, page 152). Option D: PMBOK defined three types of communication: interactive, push, and pull. Proactive communication is a made-up term.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Stakeholders', 'Stakeholders', 'Hybrid', 'Hybrid', true),
('L3Q49', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'multiple', 'Un chef de projet participe à un atelier de formation au leadership. Le formateur présente les caractéristiques des leaders serviteurs, puis cite quelques exemples de leurs comportements, tels que : (Choisissez deux réponses.)', 'A project manager attended a leadership training workshop. The trainer listed the characteristics of servant leaders, then mentioned some examples of a servant leader’s behavioral traits, such as: (Select two)', '["Aider un membre de l’équipe à rédiger un e-mail professionnel destiné à une partie prenante afin d’obtenir des informations essentielles.", "Récompenser les employés très performants afin de les motiver.", "Prendre des nouvelles d’un membre de l’équipe afin de comprendre pourquoi il est soudainement devenu introverti.", "Inspirer l’équipe avec des récits de réussite."]'::jsonb, '["Helping a team member write a professional email to a stakeholder in order to get key information.", "Rewarding high-performing employees in order to motivate them.", "Checking up on a team member to find out why they’ve suddenly become an introvert.", "Inspiring their team with success stories."]'::jsonb, '[0, 2]'::jsonb, 'Aider une personne à accomplir correctement une tâche et se soucier du bien-être des autres constituent les principaux comportements et caractéristiques des leaders serviteurs. En revanche, récompenser les employés très performants relève du leadership transactionnel, tandis qu’inspirer les personnes relève du style de leadership charismatique.', 'Helping someone do a task properly and focusing on people’s well-being are the main behavioral aspects and characteristics of servant leaders. However, rewarding high-performing employees is considered transactional leadership, whereas inspiring people falls under the charismatic leadership style.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Hybrid', 'Hybrid', true),
('L3Q50', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Pour connaître tous les fournisseurs impliqués dans un projet, le chef de projet devrait consulter :', 'To get to know all vendors involved in a project, the project manager should check out:', '["Les demandes de prix (RFQ)", "Le registre des parties prenantes", "Les propositions des fournisseurs", "Le plan d’engagement des parties prenantes"]'::jsonb, '["RFQs", "Stakeholder register", "Vendors’ proposals", "Stakeholder engagement plan"]'::jsonb, '[1]'::jsonb, 'Le registre des parties prenantes contient toutes les informations pertinentes concernant les parties prenantes du projet, notamment leur influence, leur intérêt, leur implication et leur incidence potentielle sur la réussite du projet. Les fournisseurs externes sont considérés comme des parties prenantes du projet et devraient donc figurer dans le registre des parties prenantes. Le chef de projet devrait consulter ce document chaque fois qu’il a besoin d’informations sur les parties prenantes internes ou externes (PMBOK, 8e édition, pages 141-142).', 'The stakeholder register document contains all relevant information concerning the project stakeholders including their influence, interest, involvement, and potential impact on the project’s success. External vendors are considered project stakeholders and therefore they should take part in the stakeholder register. The project manager should refer to this document whenever they need any information concerning both internal and external stakeholders (PMBOK 8th Edition, pages 141-142).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Stakeholders', 'Stakeholders', 'Predictive', 'Predictive', true),
('L3Q51', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'multiple', 'Quels sont les domaines de l’intelligence émotionnelle ? (Choisissez trois réponses.)', 'What are the areas of emotional intelligence? (Select three)', '["Conscience sociale", "Conscience de soi", "Maîtrise de soi", "Conscience culturelle", "Résolution de problèmes"]'::jsonb, '["Social-awareness", "Self-awareness", "Self-management", "Culture awareness", "Problem-solving"]'::jsonb, '[0, 1, 2]'::jsonb, 'La conscience sociale implique l’empathie et la compréhension des émotions des autres. Elle comprend la capacité à interpréter les signaux non verbaux et le langage corporel. La conscience de soi est la capacité à s’évaluer objectivement. Elle implique de comprendre ses propres émotions, objectifs, motivations, forces et faiblesses. La maîtrise de soi, également appelée autorégulation, est la capacité à contrôler et à réorienter les sentiments et impulsions perturbateurs. Elle consiste à réfléchir avant d’agir, en suspendant les jugements hâtifs et les décisions impulsives (PMBOK, 8e édition, pages 177-178).', 'Social awareness involves empathy and understanding the emotions of others. It encompasses the ability to interpret nonverbal cues and body language. Self-awareness is the capacity to objectively evaluate oneself. It involves an understanding of one’s emotions, goals, motivations, strengths, and weaknesses. Self-management, also known as self-regulation, is the ability to control and redirect disruptive feelings and impulses. It is the ability to think before acting, suspending snap judgments and impulsive decisions (PMBOK 8th Edition, pages 177-178).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Hybrid', 'Hybrid', true),
('L3Q52', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'multiple', 'Un chef de projet est chargé de diriger un mégaprojet nécessitant des experts et des ressources provenant de différents pays. Incapable de prévoir les épidémies mondiales, l’équipe projet craint de connaître un nouvel événement semblable au coronavirus, susceptible de provoquer des retards et des dépassements de coûts. Que devrait faire le chef de projet pendant la phase de planification des risques ? (Choisissez deux réponses.)', 'A project manager is assigned to lead a megaproject that requires experts and resources from different countries. Unable to predict worldwide epidemics, the project team is worried about facing another event like CoronaVirus that might cause delays and cost overruns. What should the project manager do during the risk planning phase? (Select two)', '["Ajouter le risque au registre des risques", "Effectuer une analyse qualitative des risques", "Ajouter le risque au registre des problèmes", "Surveiller l’évolution du risque"]'::jsonb, '["Add the risk to the risk register", "Perform a qualitative risk analysis", "Add the risk to the issue log", "Monitor the development of the risk"]'::jsonb, '[0, 1]'::jsonb, 'L’équipe projet devrait effectuer une analyse qualitative des risques. Si elle conclut que le risque doit être priorisé, une réponse détaillée au risque devrait ensuite être élaborée. Tous les risques identifiés devraient être ajoutés au registre des risques. Option C : pendant l’exécution du projet, tous les problèmes qui surviennent sont consignés dans le registre des problèmes. Option D : la surveillance de l’évolution du risque est également réalisée pendant la phase d’exécution, et non pendant la phase de planification.', 'The project team should perform a qualitative risk analysis. If they find that the risk must be prioritized, a detailed risk response should be then developed. All identified risks should be added to the risk register. Option C: During the project execution, all occurring issues are noted in the issue log. Option D: Monitoring the risk development is undertaken during the execution phase too, not the planning phase.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Predictive', 'Predictive', true),
('L3Q53', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Lequel de ces documents contient des descriptions détaillées des lots de travaux ?', 'Which of these documents comprises thorough descriptions of work packages?', '["WBS", "Dictionnaire de la WBS", "Liste des activités", "Plan de management du périmètre"]'::jsonb, '["WBS", "WBS Dictionary", "Activity List", "Scope management plan"]'::jsonb, '[1]'::jsonb, 'Le travail planifié figure au niveau le plus bas des composants de la WBS, appelés lots de travaux. Les informations détaillées sur les lots de travaux, telles que leur description, leurs responsables, leurs prérequis, leurs successeurs et leurs dates d’échéance, figurent dans le dictionnaire de la structure de découpage du projet (PMBOK, 8e édition, page 140).', 'The planned work is included in the lowest level of the WBS components, known as work packages. Detailed information on work packages, such as descriptions, owners, prerequisites, successors, due dates, etc. is included in the Work Breakdown Structure Dictionary (PMBOK 8th edition, page 140).', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Scope', 'Scope', 'Predictive', 'Predictive', true),
('L3Q54', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'multiple', 'Qui peut signer la charte de projet ? (Choisissez trois réponses.)', 'Who can sign the project charter? (Select three)', '["Sponsor du projet", "Comité de pilotage du projet", "Chef de projet", "Project Management Office (PMO)", "Équipe projet"]'::jsonb, '["Project Sponsor", "Project Steering Committee", "Project Manager", "Project Management Office (PMO)", "Project Team"]'::jsonb, '[0, 1, 3]'::jsonb, 'Les projets sont autorisés par une personne ou une entité extérieure au projet, telle que le sponsor, le PMO ou le comité de pilotage. Option C : le chef de projet ne peut pas signer la charte afin de s’autoriser lui-même à commencer l’exécution du projet. Option E : l’équipe projet ne dispose pas du pouvoir nécessaire pour signer la charte de projet.', 'Projects get authorized by someone external to the project such as the sponsor, PMO, or steering committee. Option C: The project manager cannot sign the charter to authorize himself to start executing the project. Option E: The project team doesn''t have the power to sign the project charter.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Gouvernance', 'Gouvernance', 'Hybrid', 'Hybrid', true),
('L3Q55', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Les connaissances acquises par l’expérience personnelle sont les plus difficiles à exprimer, à articuler ou à consigner par écrit. Ce type de connaissances est appelé :', 'Knowledge garnered through personal experience is the most difficult to express, articulate, or write down. This type of knowledge is known as:', '["Connaissances explicites", "Connaissances tacites", "Connaissances tangibles", "Connaissances formelles"]'::jsonb, '["Explicit knowledge", "Tacit knowledge", "Tangible knowledge", "Formal knowledge"]'::jsonb, '[1]'::jsonb, 'Les connaissances tacites, également appelées connaissances implicites, sont le type de connaissances qui ne peut pas être transmis à une autre personne par écrit ou verbalement. Les intuitions, les convictions, l’expérience et le savoir-faire en sont des exemples (PMBOK, 8e édition, pages 24-25). Option A : l’opposé des connaissances tacites correspond aux connaissances explicites, formelles ou codifiées.', 'Tacit knowledge, aka implicit knowledge, is the type of knowledge that can’t be transferred to another person by means of writing or verbalizing. Examples of tacit knowledge include insights, beliefs, experience, and know-how (PMBOK 8th Edition, pages 24-25). Option A: The opposite of tacit knowledge is explicit, formal, or codified knowledge.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Hybrid', 'Hybrid', true),
('L3Q56', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Quel type d’exigences est exprimé sous la forme d’un business case ?', 'What type of requirements are expressed in the form of a business case? Transition requirements', '["Exigences de transition", "Exigences des parties prenantes", "Exigences business", "Exigences de la solution"]'::jsonb, '["Transition requirements", "Stakeholders requirements", "Business requirements", "Solution requirements"]'::jsonb, '[2]'::jsonb, 'Les exigences de transition décrivent les procédures de déploiement et de mise en production d’une solution. Ces exigences sont propres à la phase de déploiement et sont temporaires ; elles n’auront plus à être exécutées une fois le projet achevé. Les exigences des parties prenantes décrivent les besoins et attentes spécifiques de chaque partie prenante ou groupe de parties prenantes. Les exigences business décrivent les besoins et objectifs de haut niveau de l’organisation, notamment les principaux problèmes ou opportunités que le projet vise à traiter. Elles justifient la réalisation du projet et sont généralement formulées dans un business case qui met en évidence les bénéfices attendus et la valeur stratégique (PMBOK, 8e édition, pages 130-131). Les exigences de la solution décrivent les attributs spécifiques d’une solution, notamment les caractéristiques et fonctionnalités d’un produit. Elles répondent à la fois aux besoins business et à ceux des parties prenantes et doivent être suffisamment détaillées pour guider efficacement la conception et le développement de la solution. Les exigences de la solution comprennent deux sous-catégories : les exigences fonctionnelles et non fonctionnelles.', 'Transition requirements describe the procedures for deploying and releasing a solution into production. These requirements are specific to the deployment phase and are temporary; they will not need to be executed again once the project is complete. Stakeholder requirements outline the specific needs and expectations of individual stakeholders or stakeholder groups. Business requirements outline the high-level needs and objectives of the organization, including key issues or opportunities that the project aims to address. They provide a rationale for undertaking the project, typically articulated through a business case that highlights the anticipated benefits and strategic value (PMBOK 8th Edition, pages 130-131). Solution requirements outline the specific attributes of a solution, including the features and functionalities of a product. These requirements address both business and stakeholder needs and must be detailed enough to guide the design and development of the solution effectively. Solution requirements have two subcategories: functional and non-functional requirements.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Hybrid', 'Hybrid', true),
('L3Q57', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Comment l’écart de coût est-il calculé ?', 'How is the cost variance measured?', '["VA / CR", "BAA / VA", "VA - CR", "BAA / CR", "BAA - CR"]'::jsonb, '["EV / AC", "BAC / EV", "EV - AC", "BAC / AC", "BAC - AC"]'::jsonb, '[2]'::jsonb, 'L’écart de coût correspond à la différence entre le coût estimé et le coût réel. Sa formule est VA - CR (PMBOK, 8e édition, page 207).', 'Cost variance is the difference between the estimated cost and the actual cost. Its formula is EV - AC (PMBOK 8th Edition, page 207).', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Finance', 'Finance', 'Predictive', 'Predictive', true),
('L3Q58', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'En raison d’un degré élevé d’incertitude, le chef de projet opte pour la méthode de planification par vagues pour planifier le projet. En quoi cette méthode est-elle utile dans ce cas ?', 'Due to high levels of uncertainty, the project manager opts for the rolling wave method for the project planning. How is this method useful in this case?', '["Elle aidera le chef de projet à déterminer quelles activités sont les plus importantes à prioriser.", "Elle aidera le chef de projet à organiser les activités et les tâches du projet.", "Elle aidera le chef de projet à déterminer l’enchaînement d’un grand nombre d’activités.", "Elle aidera le chef de projet à atteindre, au moment approprié, le niveau de détail adéquat pour chaque lot de travaux."]'::jsonb, '["It will help the project manager determine which activities are more important to prioritize", "It will help the project manager organize the project’s activities and tasks", "It will help the project manager determine the sequencing of a large number of activities", "It will help the project manager reach the proper level of detail in each work package at the right time"]'::jsonb, '[3]'::jsonb, 'La planification par vagues est une méthode de planification de projet qui consiste à élaborer progressivement, au fil du temps, les détails de la structure de découpage du projet (WBS). Les livrables à court terme sont décomposés en composants individuels, ou lots de travaux, eux-mêmes détaillés au niveau le plus fin. En revanche, les livrables à long terme sont définis de manière plus générale. Ainsi, la planification par vagues permet de poursuivre le travail sur les livrables actuels et à court terme pendant que se poursuit la planification des futurs lots de travaux possibles (PMBOK, 8e édition, page 196). Options A, B et C : la méthode de planification par vagues sert à traiter l’incertitude, et non à prioriser, organiser ou ordonnancer les activités.', 'Rolling wave is a project planning method that consists of a gradual elaboration of details to the Work Breakdown Structure (WBS) over time. Near-term deliverables are decomposed into individual components (work packages) that are broken down to the greatest degree of detail. Long-term deliverables, on the other hand, are identified more broadly. In this way, rolling wave planning allows work to progress on current and near-term deliverables while the planning for potential work packages continues (PMBOK 8th Edition, page 196). Options A & B & C: The Rolling wave method is used to address uncertainty rather than prioritizing, organizing, or sequencing activities.', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Scope', 'Scope', 'Predictive', 'Predictive', true),
('L3Q59', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un projet comporte cinq cycles d’itération. Lorsque le projet atteint la troisième itération, le nombre de user stories dans le backlog diminue considérablement. Quelle est la cause possible de cette diminution ?', 'A project has 5 iteration cycles, as the project advances to the 3rd iteration, the number of user stories in the backlog decreases significantly. What’s the potential cause of the decrease?', '["L’équipe a commencé un sprint technique.", "Un nouvel outil est utilisé pour calculer la vélocité.", "L’équipe a affiné le backlog et supprimé les stories de moindre priorité.", "L’équipe a ajouté davantage de fonctionnalités au Product Backlog."]'::jsonb, '["The team entered a technical sprint", "A new tool is used to calculate the velocity", "The team refined the backlog and removed lower-priority stories", "The team added more features to the product backlog"]'::jsonb, '[2]'::jsonb, 'À mesure que le projet progresse, l’équipe examine et met à jour le backlog. Pendant ce refinement, les user stories de moindre priorité ou de moindre valeur peuvent être supprimées ou dépriorisées afin que l’équipe se concentre sur les tâches les plus prioritaires.', 'As the project progresses, the team reviews and updates the backlog. During this refinement, lower-priority or less valuable user stories might be removed or deprioritized to focus on higher-priority tasks.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Scope', 'Scope', 'Agile', 'Agile', true),
('L3Q60', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'multiple', 'Un chef de projet Agile constate que plusieurs parties prenantes se sont désengagées : elles assistent rarement aux réunions et fournissent peu de feedback ou de contributions. Que peut faire le chef de projet pour remédier à ce problème ? (Choisissez deux réponses.)', 'An agile project manager observes that several stakeholders have become disengaged; they rarely attend meetings or provide feedback and input. What can the project manager do to address this issue? (Select two)', '["Envoyer un rappel avant chaque réunion.", "Informer les parties prenantes qu’elles peuvent transmettre leur feedback de manière anonyme.", "Valoriser les idées de chacun et témoigner de la reconnaissance à leur égard.", "Faire la démonstration des incréments fonctionnels."]'::jsonb, '["Send a reminder before each meeting", "Inform stakeholders that they can provide their feedback anonymously", "Value and show appreciation for everyone''s ideas", "Demonstrate the working increments"]'::jsonb, '[2, 3]'::jsonb, 'Il est fort probable que les parties prenantes se désintéressent du projet parce que leurs contributions ou leur feedback ne sont pas pris en compte, ou parce qu’elles ne constatent aucun progrès tangible. Le chef de projet doit engager les parties prenantes en tenant compte de leur feedback afin de leur montrer que leurs idées sont valorisées. Il devrait également faire la démonstration d’incréments fonctionnels aussi tôt que possible dans le cycle de vie du projet. Il s’agit de l’un des avantages de l’approche Agile que les parties prenantes attendent et apprécient. Options A et B : envoyer des rappels avant chaque réunion ou autoriser un feedback anonyme ne favorise pas davantage l’engagement, car aucune de ces options ne traite la cause profonde du problème.', 'Most probably, stakeholders are losing interest in the project because their input or feedback is being disregarded, or they are not seeing any tangible progress. The project manager has to engage stakeholders by taking their feedback into consideration to show them that their ideas are valued. The project manager should also demonstrate working increments as early in the project lifecycle as possible. This is considered one of the advantages of the agile approach that stakeholders expect and appreciate. Options A & B: Sending reminders before each meeting or allowing for anonymous feedback does not yield more engagement as both options don’t address the root cause of the problem.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Stakeholders', 'Stakeholders', 'Agile', 'Agile', true),
('L3Q61', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Après plusieurs séances de négociation, toutes les conditions et tous les détails ont été convenus, et le fournisseur a finalement obtenu le contrat du projet de construction d’une durée de 18 mois pour un montant de 715 500 $. Quel type de contrat est utilisé dans cette situation ?', 'After multiple negotiation sessions, all of the terms and details were agreed upon and the seller finally got the 18-month building project contract for $715,500. What type of contract is used in this scenario? Time and Material', '["Temps et matériaux", "Prix forfaitaire", "Remboursement des coûts", "Coût plus intéressement"]'::jsonb, '["Time and Material", "Fixed Price", "Cost Reimbursable", "Cost Plus Incentive"]'::jsonb, '[1]'::jsonb, 'Les contrats temps et matériaux (T&M) établissent un tarif horaire auquel s’ajoute le coût des matériaux, au lieu de fixer un prix global pour l’ensemble du projet. Les contrats à prix forfaitaire sont utilisés pour les projets dont les exigences sont clairement définies ; un prix est fixé en contrepartie des services et/ou produits fournis par le fournisseur (PMBOK, 8e édition, page 251). Les contrats à remboursement des coûts remboursent au contractant les coûts réels engagés pour fournir ses services et/ou son produit, auxquels s’ajoutent des honoraires. Un contrat à coûts remboursables avec intéressement est un contrat à remboursement des coûts qui incite le contractant à fournir sa meilleure performance en achevant le projet en dessous du budget ou avant les échéances.', 'Time and Material (T&M) contracts set a quote for an hourly rate plus the cost of materials instead of quoting a fixed price for the entire project. Fixed price contracts are used for projects with clear requirements where a price is fixed in return for the seller’s services and/or products (PMBOK 8th Edition, page 251). Cost-reimbursable contracts reimburse the contractor for the actual costs they incur to provide their services and/or product, plus an additional fee. A Cost Plus Incentive contract is a cost-reimbursable contract that incentivizes the contractor to bring their best performance by completing the project under budget or before deadlines.', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Finance', 'Finance', 'Predictive', 'Predictive', true),
('L3Q62', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet décide d’utiliser la méthode des cinq pourquoi afin d’analyser une fonctionnalité défaillante. Pourquoi le chef de projet a-t-il choisi cette technique particulière ?', 'A project manager decides to use the Five Whys method in order to investigate a dysfunctioning feature. Why did the project manager choose to use this specific technique?', '["Identifier les cinq principaux facteurs ayant causé le problème", "Identifier la cause racine du problème", "Identifier les cinq membres responsables du problème", "Identifier les cinq étapes à suivre pour résoudre le problème"]'::jsonb, '["To identify the five main factors that caused the issue", "To identify the root cause of the issue", "To identify the five members responsible for the issue", "To identify the five steps to take to resolve the issue"]'::jsonb, '[1]'::jsonb, 'En tant que technique de résolution de problèmes, les cinq pourquoi servent à explorer la cause sous-jacente d’un défaut ou d’un problème. En posant successivement la question « Pourquoi ? », l’équipe approfondit son analyse afin de déterminer ce qui s’est mal passé, puis de définir comment traiter correctement le problème et éviter que des problèmes similaires ne se reproduisent à l’avenir (PMBOK, 8e édition, page 150).', 'As a problem-solving technique, the Five whys is used to explore the underlying cause of a defect or an issue. By asking successive “Why?” questions, the team digs deep to figure out what went wrong and thus be able to determine how to properly address the problem and how to avoid similar issues in the future (PMBOK 8th Edition, page 150).', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'resources and Risks', 'Resources and Risks', 'Predictive', 'Predictive', true),
('L3Q63', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'multiple', 'Un chef de projet dirige un projet de construction. Tout au long de son exécution, le projet a été influencé par des actifs organisationnels. Parmi les affirmations suivantes, lesquelles sont considérées comme des actifs organisationnels ? (Choisissez deux réponses.)', 'A project manager is leading a construction project. Throughout its execution, the project was influenced by Organizational Process Assets (OPAs). Which of the following statements are considered as OPAs? (Select two)', '["Les travaux de construction nécessitent un permis de construire délivré par le conseil municipal.", "Les travailleurs qui ne respectent pas les règles de sécurité seront sanctionnés.", "Seul le personnel autorisé est admis sur le chantier.", "Les travailleurs possèdent une expertise en construction d’infrastructures."]'::jsonb, '["Construction work requires a building permit from City council", "Workers who don’t obey safety rules will be penalized", "Only authorized personnel are allowed on site", "Workers have expertise in infrastructure construction"]'::jsonb, '[1, 2]'::jsonb, '« Les travailleurs qui ne respectent pas les règles de sécurité seront sanctionnés » et « Seul le personnel autorisé est admis sur le chantier » sont considérés comme des actifs organisationnels, car ces affirmations représentent des procédures internes de l’organisation. « Les travailleurs possèdent une expertise en construction d’infrastructures » constitue un facteur environnemental interne de l’organisation, tandis que « Les travaux de construction nécessitent un permis de construire délivré par le conseil municipal » constitue un facteur environnemental externe de l’organisation (PMBOK, 8e édition, pages 19-21).', '“Workers who don’t obey safety rules will be penalized” and “Only authorized personnel are allowed on site” are considered Organizational Process Assets (OPAs) since they represent the organization’s internal procedures. “Workers have expertise in infrastructure construction” is an internal Enterprise Environmental Factor, while “Construction work requires a building permit from the City council” is an external Enterprise Environmental Factor (PMBOK 8th Edition, pages 19-21).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Gouvernance', 'Gouvernance', 'Hybrid', 'Hybrid', true),
('L3Q64', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un diagramme entité-association (DEA) est un modèle qui illustre les exigences relatives aux données business, notamment les différentes informations et leurs relations. Quel type de modèle le DEA représente-t-il ?', 'An Entity-Relationship Diagram (ERD) is a model that illustrates the business data requirements, including the various pieces of information and their interrelationships. What type of model does the ERD represent? Scope model', '["Modèle de périmètre", "Modèle de processus", "Modèle de règles", "Modèle de données", "Modèle d’interface"]'::jsonb, '["Scope model", "Process model", "Rule model", "Data model", "Interface model"]'::jsonb, '[3]'::jsonb, 'Les modèles de périmètre sont des cadres qui structurent et organisent systématiquement les caractéristiques, les fonctions et les limites du domaine business analysé. Ils comprennent les diagrammes de contexte, les diagrammes de cas d’utilisation et l’analyse SWOT. Les modèles de processus représentent et documentent les processus business et les caractéristiques du système. Ils comprennent les flux de processus, les user stories et les cas d’utilisation. Les modèles de règles décrivent les contraintes business, les règles et les procédures obligatoires qui établissent les critères définitifs de validation de toute solution proposée. Ils comprennent l’arbre de décision, la table de décision et le catalogue des règles business. Les modèles de données sont des représentations structurées qui documentent la manière dont les données sont stockées, organisées et circulent dans un système. Ils comprennent les diagrammes entité-association, les diagrammes de flux de données et les dictionnaires de données. Les modèles d’interface précisent la manière dont les systèmes interagissent et sont reliés entre eux au sein d’une solution. Ils comprennent le flux de l’interface utilisateur, les wireframes et les représentations affichage-action-réponse.', 'Scope models are frameworks that systematically structure and organize the features, functions, and boundaries of the business domain under analysis. They include context diagrams, use case diagrams, and SWOT. Process models represent and document business processes and system features. They include process flow, user story and use case. Rule models outline business constraints, rules, and mandatory procedures that establish the definitive criteria for validating any proposed solution. They include the decision tree, decision table, and business rules catalog. Data models are structured representations that document how data is stored, organized, and flows within a system. They include entity relationship diagrams, data flow diagrams, and data dictionaries. Interface models clarify how systems interact and relate to one another within a solution. They include user interface flow, wireframes, and display action response.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Hybrid', 'Hybrid', true),
('L3Q65', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Dans le cadre de l’analyse business, laquelle des affirmations suivantes décrit correctement la relation entre les cycles de vie du projet et les cycles de vie du produit ?', 'In business analysis, which of the following statements accurately reflects the relationship between project life cycles and product life cycles?', '["Un cycle de vie du projet comprend plusieurs cycles de vie du produit.", "Un cycle de vie du produit est composé d’un ou de plusieurs cycles de vie du projet.", "L’analyse business porte uniquement sur les projets individuels, et non sur l’ensemble du cycle de vie du produit.", "Une fois le projet achevé, le cycle de vie du produit prend fin."]'::jsonb, '["A project life cycle consists of multiple product life cycles.", "A product life cycle is composed of one or more project life cycles.", "Business analysis only focuses on individual projects, not the entire product life cycle.", "Once a project is completed, the product life cycle ends."]'::jsonb, '[1]'::jsonb, 'Au cours du cycle de vie du produit, une évaluation des besoins permet d’aligner et de justifier l’investissement dans un nouveau projet. Une fois le projet achevé, une évaluation du produit est réalisée dans le cadre du cycle de vie du produit afin de déterminer si un nouveau projet est nécessaire pour poursuivre le développement du produit. L’analyse business couvre l’ensemble du cycle de vie du produit, y compris les différents projets qui contribuent à son évolution (PMBOK, 8e édition, page 24).', 'During the product life cycle, a needs assessment helps align and justify the investment in a new project. Once the project is completed, a product evaluation is carried out within the product life cycle to assess whether a new project is necessary to further develop the product. Business analysis covers the entire product life cycle, including the various projects that contribute to the product''s advancement (PMBOK 8th Edition, page 24).', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Gouvernance', 'Gouvernance', 'Hybrid', 'Hybrid', true),
('L3Q66', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'multiple', 'Que devrait faire le chef de projet pendant la conférence des soumissionnaires ? (Choisissez deux réponses.)', 'What should the project manager do during the bidder conference? (Select two)', '["Attribuer le contrat", "Clarifier les points de doute", "Partager le dossier d’appel d’offres avec les participants", "Présélectionner les fournisseurs potentiels", "Expliquer les conditions de l’appel d’offres"]'::jsonb, '["Award the contract", "Clarify any doubts", "Share the bid document with participants", "Shortlist prospective sellers", "Explain the bid terms and conditions"]'::jsonb, '[1, 4]'::jsonb, 'La conférence des soumissionnaires, également appelée conférence des contractants ou conférence des fournisseurs, est organisée afin de s’assurer que les fournisseurs ont une compréhension commune des exigences d’approvisionnement du projet (PMBOK, 8e édition, page 265). Pendant la conférence, le chef de projet et les parties prenantes discutent de leurs besoins d’approvisionnement et répondent à toutes les questions que les fournisseurs pourraient poser. Options A et D : pendant une conférence des soumissionnaires, le chef de projet ne présélectionne pas les fournisseurs potentiels et n’attribue pas le contrat. Option C : le dossier d’appel d’offres doit être communiqué aux participants avant la conférence des soumissionnaires (PMBOK, 8e édition, page 248).', 'Bidder conference, aka contractor conference or vendor conference, is arranged to ensure that sellers have a common understanding of the project procurement requirements (PMBOK 8th edition, page 265). During the conference, the project manager and the stakeholders will discuss their procurement needs and answer any questions the sellers might have. Option A & D: In a bidder conference, the project manager does not shortlist prospective sellers or award the contract. Option C: The bid document has to be shared with participants before the bidder conference (PMBOK 8th Edition, page 248).', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Gouvernance', 'Gouvernance', 'Predictive', 'Predictive', true),
('L3Q67', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Après huit années d’expérience au même poste, un chef de projet est promu au rôle de responsable de portefeuille. Un portefeuille est :', 'After 8 years of experience in the same position, a project manager gets promoted to a Portfolio manager role. A portfolio is:', '["Un ensemble de projets, de programmes ou d’opérations gérés collectivement afin d’atteindre les objectifs stratégiques de l’organisation.", "L’analyse des exigences informatiques et la vérification du respect des exigences réglementaires.", "L’application de méthodes, de processus et d’outils afin de garantir que les projets sont gérés conformément à leur conception.", "Un dispositif qui crée une vision commune et aide la direction générale à percevoir les implications stratégiques potentielles des décisions de l’entreprise."]'::jsonb, '["A number of projects, programs, or operations that are all managed as a collection with the aim to achieve the organization’s strategic goals.", "Analyzing IT requirements and ensuring regulatory requirements are followed.", "Following methods, processes, and tools to ensure that projects are managed as designed.", "Creates a common vision and helps senior management to see the potential strategic implications of corporate decisions."]'::jsonb, '[0]'::jsonb, 'Un portefeuille est un regroupement de projets et de programmes. Son objectif est d’établir une gestion et une supervision centralisées de plusieurs projets et/ou programmes. Il contribue également à instaurer une gouvernance normalisée dans l’ensemble de l’organisation. La création et la gestion d’un portefeuille permettent de s’assurer que l’organisation sélectionne les bons projets, alignés sur ses valeurs, ses stratégies et ses objectifs (PMBOK, 8e édition, page 10).', 'A portfolio is a grouping of projects and programs. A portfolio’s purpose is to establish centralized management and oversight for a number of projects and/or programs. It also helps establish standardized governance across the organization. By creating and managing a portfolio, you’re ensuring that the organization is choosing the right projects that align with its values, strategies, and goals (PMBOK 8th edition, page 10).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Gouvernance', 'Gouvernance', 'Hybrid', 'Hybrid', true),
('L3Q68', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet annule une réunion de revue des leçons apprises en raison de contraintes de temps. Quelles pourraient être les conséquences de cette décision ?', 'A project manager canceled a lessons learned review meeting due to time constraints. What could be the potential consequences of this decision?', '["Les problèmes rencontrés au cours du projet pourraient se reproduire en raison de l’occasion manquée d’identifier des actions préventives.", "Le management de projet deviendra plus difficile.", "Le coût du projet sera plus élevé.", "Le projet pourrait ne pas être accepté par le Project Management Office (PMO)."]'::jsonb, '["Issues faced through the project could reoccur due to the missed opportunity to identify preventive actions", "Project management will get more difficult", "Project cost will be greater", "The project may not be accepted by the Project Management Office (PMO)"]'::jsonb, '[0]'::jsonb, 'Les connaissances acquises au cours de la réalisation d’un projet sont appelées « leçons apprises ». Elles couvrent à la fois les aspects positifs et négatifs. L’objectif est de reproduire les bonnes pratiques et d’éviter de répéter les erreurs (PMBOK, 8e édition, page 269). En omettant d’examiner les leçons apprises antérieures, le chef de projet risque de commettre les mêmes erreurs que lors de projets précédents. Par conséquent, plus les leçons sont identifiées et intégrées tôt dans le projet, plus elles apportent de valeur. Idéalement, le chef de projet devrait donc effectuer des revues en continu afin de permettre l’amélioration continue. Une telle revue recueille des contributions approfondies de l’équipe projet, des sponsors, des parties prenantes, etc. La collecte et l’examen réguliers des leçons apprises contribuent à maintenir le projet sur la bonne voie. À long terme, ils aident également les organisations à développer et à améliorer continuellement leur manière de mener les projets.', 'The knowledge acquired from the process of carrying out a project is referred to as "lessons learned." This covers both the positive and negative aspects. The aim is to replicate good practices and avoid repeating errors (PMBOK 8th Edition, page 269). By failing to examine or go over past lessons learned, the project manager risks making the same errors as in previous projects. Therefore, the earlier the lessons are identified and embedded into a project, the more value they will provide. So ideally, a project manager should conduct reviews on an ongoing basis to allow for continuous improvement. Such a review will capture in-depth inputs from the project team, sponsors, stakeholders, etc. Capturing and going over lessons learned on a regular basis helps keep the project on track. In the long term, it will also help organizations continuously develop and enhance the way they conduct projects.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Gouvernance', 'Gouvernance', 'Hybrid', 'Hybrid', true),
('L3Q69', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'La méthode du chemin critique est une technique d’analyse du diagramme de réseau de l’échéancier. Laquelle des affirmations suivantes concernant le chemin critique est correcte ?', 'The critical path method is a schedule network analysis technique. Which of the following statements is true regarding the critical path?', '["Toutes les tâches situées sur le chemin critique doivent être critiques en elles-mêmes.", "Si une tâche du chemin critique est retardée, la date d’achèvement de l’ensemble du projet sera retardée.", "Une demande de changement n’a aucune incidence sur le chemin critique.", "Le chemin critique peut être utilisé dans les cycles de vie prédictifs et adaptatifs."]'::jsonb, '["All of the tasks on the critical path should be critical themselves.", "If a task in the critical path is delayed, it will result in delaying the whole project completion date.", "A change request does not have any impact on the critical path.", "The critical path can be used in both predictive and adaptive life cycles."]'::jsonb, '[1]'::jsonb, 'Le chemin critique comprend les tâches qui doivent être achevées comme prévu afin que le projet soit terminé à temps. Si une tâche est retardée, elle peut entraîner un retard de la date d’achèvement du projet. Option A : certaines tâches du chemin critique peuvent ne pas être critiques en elles-mêmes, mais elles doivent être réalisées à temps afin que la ou les tâches critiques puissent être achevées. La méthode du chemin critique est utilisée dans les projets suivant un cycle de vie prédictif, dans lesquels les demandes de changement peuvent avoir une incidence directe sur le projet.', 'The critical path comprises tasks that must be completed as scheduled in order for the project to be finished on time. If a task is delayed, it may cause a delay in the project’s completion date. Option A: Some tasks on the critical path may not be critical themselves, but they need to be accomplished on time in order for the critical task(s) to be completed. The critical path method is used in projects following a predictive life cycle where change requests could have a direct impact on the project.', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Schedule', 'Schedule', 'Predictive', 'Predictive', true),
('L3Q70', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Qui le Business Analyst devrait-il consulter pour comprendre le résultat d’un processus donné et la manière dont celui-ci répond aux objectifs de l’organisation ?', 'Who should the business analyst consult to understand the outcome of a certain process and how it meets the organization’s objectives?', '["Responsable du processus", "Gestionnaire du processus", "Responsable produit", "Product Owner", "Chef de projet"]'::jsonb, '["Process owner", "Process manager", "Product manager", "Product owner", "Project manager"]'::jsonb, '[0]'::jsonb, 'Le responsable du processus veille à ce que le processus atteigne la cible fixée par l’organisation et assume la responsabilité de sa performance et de son efficacité globales. Le gestionnaire du processus supervise les opérations quotidiennes du processus. Le responsable produit est chargé de la stratégie et de la vision globales du produit. Le Product Owner, qui représente le client, est chargé de définir et de prioriser le Product Backlog. Le chef de projet est chargé de planifier, d’exécuter, de surveiller, de maîtriser et de clôturer le projet.', 'The process owner makes sure that the process meets the target laid down by the organization and is responsible for the overall performance and effectiveness of the process. The process manager oversees the day-to-day operations of the process. The product manager is responsible for the overall strategy and vision of the product. The product owner representing the customer, is responsible for defining and prioritizing the product backlog. The project manager is responsible for planning, executing, monitoring, controlling, and closing the project.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Stakeholders', 'Stakeholders', 'Hybrid', 'Hybrid', true),
('L3Q71', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Pendant l’exécution d’un projet de construction, le fournisseur informe le chef de projet que la livraison de la nouvelle commande de barres d’acier pourrait subir un retard de trois jours. Que devrait faire ensuite le chef de projet ?', 'During the execution of a construction project, the supplier informed the project manager that delivering the new order of steel bars may have a 3-day delay. What should the project manager do next?', '["Négocier le retard avec le fournisseur afin de le réduire", "Rechercher un autre fournisseur", "Évaluer l’incidence du retard", "Mettre à jour l’échéancier du projet"]'::jsonb, '["Negotiate the delay with the vendor to get it reduced", "Look for another vendor", "Evaluate the impact of the delay", "Update the project schedule"]'::jsonb, '[2]'::jsonb, 'Le chef de projet devrait évaluer l’incidence du retard avant de prendre une décision. Le retard d’une activité n’entraîne pas nécessairement celui de l’ensemble du projet. Par exemple, si l’activité ne se trouve pas sur le chemin critique et dispose d’une marge supérieure à trois jours, le retard n’aura probablement aucune incidence sur le projet.', 'The project manager should evaluate the impact of the delay before making any decision. A delayed activity doesn’t necessarily result in the whole project''s delay. For instance, if the activity is not on the critical path and it has a lag of more than three days, then the delay probably won’t have any impact on the project.', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Schedule', 'Schedule', 'Predictive', 'Predictive', true),
('L3Q72', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Pendant l’exécution du projet, l’équipe projet rencontre un problème avec un fournisseur peu fiable. Comme l’incident a une forte incidence sur le périmètre du projet, le chef de projet décide de résilier le contrat du fournisseur et de ne plus jamais travailler avec lui à l’avenir. Où le chef de projet devrait-il consigner ce problème ?', 'During project execution, the project team had an issue with an unreliable vendor. Since the incident had a high impact on the project scope, the project manager decided to terminate the vendor’s contract and never deal with them again in the future. Where should the project manager record this issue?', '["Registre des leçons apprises", "Journal des changements", "Registre des risques", "Registre des problèmes"]'::jsonb, '["Lessons learned register", "Change log", "Risk register", "Issue log"]'::jsonb, '[3]'::jsonb, 'Le registre des problèmes est un document du projet dans lequel toutes les informations relatives aux problèmes rencontrés sont consignées et suivies (PMBOK, 8e édition, page 123). Option A : bien que la situation décrite comporte une leçon apprise — ne plus travailler avec ce fournisseur peu fiable à l’avenir —, la question demande uniquement où consigner le problème.', 'The Issue Log is a project document where all information concerning faced issues is recorded and monitored (PMBOK 8th edition, page 123). Option A: Even though the described scenario involves lessons learned (never to deal with the unreliable vendor in the future), the question only inquires about where to record the issue.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Hybrid', 'Hybrid', true),
('L3Q73', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Dans un projet de construction, le béton est coulé après l’achèvement de la pose des armatures et du coffrage. Les ouvriers doivent ensuite attendre 14 jours avant de retirer le coffrage, car le béton doit être suffisamment résistant pour cette opération. Cette période de 14 jours est un exemple de :', 'For a construction project, concrete is poured after the completion of rebar and formwork. Now, workers must wait 14 days before removing the formwork, as the concrete must be strong enough for this operation. The 14-day period is an example of:', '["Avance", "Retard", "Compression des délais", "Exécution accélérée par chevauchement"]'::jsonb, '["A Lead", "A Lag", "Crashing", "Fast-tracking"]'::jsonb, '[1]'::jsonb, 'Un retard est une durée pendant laquelle un délai est délibérément introduit entre des activités (PMBOK, 8e édition, pages 179-180). Option A : une avance correspond au temps gagné en commençant une activité avant l’achèvement de son prédécesseur. Options C et D : la compression des délais et l’exécution accélérée par chevauchement sont deux techniques de compression de l’échéancier (PMBOK, 8e édition, pages 196-197).', 'Lag Time is when a delay is purposely made between activities (PMBOK 8th Edition, pages 179-180). Option A: Lead time is the time saved by starting an activity before its predecessor is completed. Option C & D: Crashing and fast-tracking are two schedule compression techniques (PMBOK 8th Edition, pages 196-197).', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Schedule', 'Schedule', 'Predictive', 'Predictive', true),
('L3Q74', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'multiple', 'Un nouveau Business Analyst est recruté pour un nouveau projet. Quelles compétences devrait-il posséder ? (Choisissez trois réponses.)', 'A new business analyst is getting hired for a new project, which competencies should the business analyst possess? (Select three)', '["Compétences analytiques", "Jugement d’expert", "Compétences personnelles", "Compétences managériales", "Compétences techniques"]'::jsonb, '["Analytical skills", "Expert judgment", "Personal skills", "Management skills", "Technical skills"]'::jsonb, '[0, 1, 2]'::jsonb, 'Selon le PMI Guide to Business Analysis, pages 53 et 54, les compétences du Business Analyst sont les suivantes : compétences analytiques, jugement d’expert, compétences en communication, compétences personnelles, compétences en leadership et connaissance des outils. Option D : les compétences managériales sont davantage requises pour les chefs de projet. Option E : les membres de l’équipe projet peuvent être tenus de posséder des compétences techniques.', 'The business analyst competencies as defined in the (PMI Guide to Business Analysis, pages 53 & 54) are Analytical skills, Expert judgment, Communication skills, Personal skills, Leadership skills, and Tool knowledge. Option D: Management skills are more required for project managers. Option E: The project team may be required to have technical skills.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'resources and Risks', 'Resources and Risks', 'Hybrid', 'Hybrid', true),
('L3Q75', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Au cours de laquelle des réunions suivantes l’équipe projet Agile devrait-elle présenter aux parties prenantes du projet un incrément de produit potentiellement livrable ?', 'During which of the following meetings should the Agile project team demonstrate a potentially shippable product increment to the project stakeholders?', '["Réunion de revue", "Réunion quotidienne", "Réunion de rétrospective", "Réunion des livrables"]'::jsonb, '["Review meeting", "Standup meeting", "Retrospective meeting", "Deliverables meeting"]'::jsonb, '[0]'::jsonb, 'À la fin de chaque itération, le chef de projet et l’équipe projet devraient présenter un incrément de produit potentiellement livrable aux parties prenantes concernées et au Product Owner afin d’obtenir leur feedback. Cette présentation a lieu lors d’une réunion de revue de l’itération ou du sprint. Le Product Owner et les parties prenantes utilisent cette réunion pour évaluer les priorités du produit et du backlog de release (PMBOK, 8e édition, page 199).', 'At the end of each iteration, the project manager and the project team should demonstrate a potentially shippable product increment to the concerned stakeholders along with the Product Owner to get their feedback. This occurs during an iteration or sprint review meeting. The product owner and stakeholders use this meeting to evaluate the product and release backlog priorities (PMBOK 8th edition, page 199).', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Stakeholders', 'Stakeholders', 'Agile', 'Agile', true),
('L3Q76', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Dans le management de la qualité, lequel des éléments suivants relève du coût de conformité ?', 'In quality management, which of the following falls under the cost of conformance?', '["Retouche", "Rebut", "Travaux sous garantie", "Perte liée aux essais destructifs"]'::jsonb, '["Rework", "Scrap", "Warranty work", "Destructive testing loss"]'::jsonb, '[3]'::jsonb, 'La perte liée aux essais destructifs est un exemple de coût de conformité ; les autres options relèvent du coût de non-conformité. Le coût de non-conformité comprend les dépenses résultant du non-respect des exigences de qualité. Le coût de non-conformité peut être divisé en deux catégories : Les coûts de défaillance interne sont engagés lorsque les défauts sont détectés en interne, c’est-à-dire avant la présentation des livrables aux clients ; ils comprennent la réparation des défauts et les retouches. Les coûts de défaillance externe sont engagés lorsque les défauts sont découverts après la livraison des livrables aux clients. Il s’agit du pire type de coût de la qualité. Ils comprennent les travaux sous garantie, les responsabilités et la perte de réputation de l’entreprise. Référence : PMBOK, 8e édition, pages 158-159.', 'Destructive testing loss is an example of the cost of conformance, the rest fall under the cost of non-conformance. Cost of Non-Conformance includes the expenses arising due to non-conformance to quality requirements. Cost of Non-Conformance can be divided into two categories: Internal Failure Costs are incurred when defects are detected internally (i.e. not yet presented to the customers) which include defect repair and rework. External Failure Costs are incurred when defects are discovered after the deliverables have been shipped to customers (this is the worst type of quality cost) These include warranty work, liabilities, and loss of business goodwill. Reference: PMBOK 8th edition, pages 158-159.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Predictive', 'Predictive', true),
('L3Q77', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un nouveau membre de l’équipe demande en quoi consiste le management de projet. Le chef de projet répond : « Le management de projet est ________________________ »', 'A new team member asks about what project management involves. The project manager answers: “Project Management is ________________________”', '["Une initiative temporaire entreprise pour créer un service, un produit ou un résultat unique.", "L’application d’un ensemble de connaissances, de compétences, d’outils et de techniques aux activités du projet afin de satisfaire aux exigences du projet.", "L’ensemble de programmes regroupés afin d’atteindre des objectifs business stratégiques.", "Une structure organisationnelle visant à normaliser les processus de gouvernance liés aux projets."]'::jsonb, '["An undertaken temporary endeavor to create a unique service, product, or result", "The application of a set of knowledge, skills, tools, and techniques to project activities to meet the project requirements", "The collection of programs that have been grouped to achieve strategic business goals", "An organizational structure that aims to standardize project-related governance processes"]'::jsonb, '[1]'::jsonb, 'Le management de projet consiste à appliquer un ensemble de processus, de compétences, de connaissances, d’expériences et de méthodes afin d’atteindre plusieurs objectifs et exigences prédéfinis du projet, conformément à des critères d’acceptation établis à l’avance (PMBOK, 8e édition, page 271).', 'Project management involves applying a set of processes, skills, knowledge, experience, and methods, to attain a number of predefined project objectives and requirements according to predetermined acceptance criteria (PMBOK 8th edition, page 271).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Gouvernance', 'Gouvernance', 'Hybrid', 'Hybrid', true),
('L3Q78', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'multiple', 'Quelle valeur ajoutée les prototypes apportent-ils ? (Choisissez deux réponses.)', 'What added value do prototypes provide? (Select two)', '["Permettre d’obtenir un feedback précoce sur les exigences", "Réduire le coût du projet", "Permettre d’achever le projet plus rapidement", "Aider à lever les ambiguïtés"]'::jsonb, '["Allow for early feedback on the requirements", "Reduce project cost", "Allow the project to be completed faster", "Help to address ambiguities"]'::jsonb, '[0, 3]'::jsonb, 'Le prototypage est une technique utilisée pour recueillir un feedback précoce sur les exigences afin de poursuivre leur affinement et leur clarification, ainsi que pour lever les ambiguïtés (PMBOK, 8e édition, page 272). Options B et C : selon ses résultats, le développement d’un prototype peut soit augmenter, soit réduire le coût et la durée du projet.', 'Prototyping is a technique used to collect early feedback on the requirements for further refinement and clarification, along with clarifying ambiguities (PMBOK 8th edition, page 272). Options B & C: The development of a prototype can either increase the project cost and duration or reduce them depending on its results.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Hybrid', 'Hybrid', true),
('L3Q79', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Quelle est la technique de prise de décision la plus simple et la plus efficace en matière de temps ?', 'Which is the most simple and time-efficient decision-making technique?', '["Analyse des alternatives", "Négociation", "Escalade", "Vote"]'::jsonb, '["Alternative analysis", "Negotiation", "Escalation", "Voting"]'::jsonb, '[3]'::jsonb, 'Le vote permet d’aboutir à une décision consensuelle en sélectionnant l’option qui recueille le plus de voix parmi les membres de l’équipe. Cette technique est simple, intuitive et efficace en matière de temps et de coût (PMBOK, 8e édition, page 163).', 'Voting is used to reach a consensus decision by selecting the option that gets more votes from the team members. This technique is simple, intuitive, and both time and cost-efficient (PMBOK 8th Edition, page 163).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Gouvernance', 'Gouvernance', 'Hybrid', 'Hybrid', true),
('L3Q80', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Au cours des trois dernières réunions quotidiennes avec l’équipe, le chef de projet constate qu’un nouveau membre de l’équipe éprouve des difficultés avec l’une des tâches qui lui ont été affectées, car il semble ne faire aucun progrès vers son achèvement. Que devrait faire le chef de projet ?', 'During the last three daily standup meetings with the team, the project manager notices that a new team member is struggling with one of their assigned tasks as they seem to be making no progress towards completing it. What should the project manager do? Ask an experienced team member to take over the task.', '["Demander à un membre expérimenté de l’équipe de reprendre la tâche.", "Vérifier si d’autres membres de l’équipe peuvent aider leur nouveau collègue à réaliser la tâche après la réunion quotidienne.", "Exprimer sa déception au nouveau membre de l’équipe et l’encourager à fournir davantage d’efforts.", "Demander au nouveau membre de consulter les règles de fonctionnement de l’équipe."]'::jsonb, '["Ask an experienced team member to take over the task.", "Check whether other team members can help their new colleague with the task after the standup meeting.", "Express their disappointment to the new team member and encourage them to make more effort.", "Ask the new team member to check the team ground rules."]'::jsonb, '[1]'::jsonb, 'Demander à une autre personne d’accomplir la tâche aurait une incidence négative sur l’estime de soi et la motivation du nouveau membre, tout en lui faisant manquer une occasion d’apprentissage. Demander à un autre membre de l’équipe de jouer le rôle de mentor auprès du nouveau membre et de l’accompagner dans l’achèvement de sa tâche et la résolution des aspects difficiles de sa mission constitue la bonne démarche. Comme ce membre est nouveau et peut manquer de certaines compétences ou d’expérience dans le traitement de certains types de tâches, il aura l’occasion d’apprendre et de surmonter les obstacles en collaborant avec des membres plus expérimentés. De même, exprimer sa déception concernant la performance du nouveau membre causerait davantage de tort que cela ne contribuerait à résoudre le problème. La consultation des règles de fonctionnement de l’équipe n’est pas pertinente dans cette situation.', 'Assigning someone else to get the task done will only have a bad impact on their self-esteem and motivation and make them miss out on a learning opportunity. Asking another team member to help mentor the new member and guide them through getting their task completed and overcoming the challenging aspects of their assignment is the right course of action. Since the member is new and might lack certain skills or experience dealing with certain types of tasks, they will get the chance to learn and overcome any impediments by collaborating with more experienced team members. Similarly, expressing their disappointment at the new member’s performance will do more harm than actually resolving the issue. Checking the team ground rules is irrelevant to this situation.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Agile', 'Agile', true),
('L3Q81', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Après l’établissement de la référence de base du périmètre et pendant l’exécution du projet, une partie prenante clé, qui est membre du comité de maîtrise des changements (CCB), demande un nouveau service. Sachant que le chef de projet est convaincu que ce nouveau service peut apporter de la valeur au projet, que devrait-il faire ?', 'After baselining the scope and during project execution, a key stakeholder, who is a member of the Change Control Board (CCB), requested a new service. Taking into consideration that the project manager is convinced that this new service can add value to the project, what should they do? Implement the change request since the key stakeholder is a member of the CCB.', '["Mettre en œuvre la demande de changement puisque la partie prenante clé est membre du CCB.", "Mettre en œuvre la demande de changement puisqu’elle apportera de la valeur au projet.", "Soumettre une demande de changement conformément au système de maîtrise des changements.", "Consigner la demande de changement dans le journal des changements."]'::jsonb, '["Implement the change request since the key stakeholder is a member of the CCB.", "Implement the change request since it will add value to the project.", "Submit a change request according to the change control system.", "Record the change request in the change log."]'::jsonb, '[2]'::jsonb, 'Option A : le chef de projet ne devrait pas mettre en œuvre le changement sans obtenir l’approbation formelle du CCB. Option B : être convaincu de la valeur du changement ou avoir l’accord d’un seul membre du CCB ne suffit pas pour procéder à sa mise en œuvre. Option C : indépendamment du fait que le changement a été demandé par un membre du CCB, le chef de projet devrait soumettre une demande de changement conformément aux procédures définies dans le système de maîtrise des changements. Ce système décrit la manière dont les modifications des livrables du projet doivent être entreprises (PMBOK, 8e édition, pages 29-30). Option D : la demande de changement n’a pas encore été soumise au CCB ; elle ne devrait donc pas encore être consignée dans le journal des changements. Après sa soumission, le journal des changements devrait être mis à jour afin d’assurer le suivi de l’état du changement.', 'The project manager should not implement the change without getting the CCB’s formal approval. Being convinced of the change’s value or having the consent of one member of the CCB is not sufficient to move forward with the implementation. Regardless of the fact that the change was requested by a member of the CCB, the project manager should submit a change request according to the procedures defined in the change control system. This system describes how modifications to project deliverables should be undertaken (PMBOK 8th edition, pages 29-30). The change request has not been submitted yet to the CCB, so it should not be recorded in the change log. After submitting it, the change log should be updated to track the status of the change.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Scope', 'Scope', 'Predictive', 'Predictive', true),
('L3Q82', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Au cours du processus d’identification des risques, le départ de ressources a été identifié comme un risque majeur. En réponse, le chef de projet décide d’opter pour des incitations financières afin de motiver les membres de son équipe. Quel type de réponse au risque met-il en œuvre ?', 'During the risk identification process, attrition of resources was identified as a major risk. As a response, the project manager decided to opt for financial incentives to motivate their team members. What type of risk response are they following?', '["Acceptation", "Atténuation", "Transfert", "Évitement"]'::jsonb, '["Acceptance", "Mitigation", "Transference", "Avoidance"]'::jsonb, '[1]'::jsonb, 'Le chef de projet atténue le risque de départ des ressources. Ce type de réponse au risque vise à réduire la probabilité et/ou l’impact d’une menace (PMBOK, 8e édition, page 204).', 'The project manager is mitigating the risk of resource attrition. This type of risk response aims to diminish the probability and/or impact of a threat (PMBOK 8th edition, page 204).', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'resources and Risks', 'Resources and Risks', 'Predictive', 'Predictive', true),
('L3Q83', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'multiple', 'Une tâche du projet est achevée à 90 %. Elle ne peut toutefois pas être terminée avant qu’une autre tâche ne soit achevée. De quel type de dépendance s’agit-il ? (Choisissez deux réponses.)', 'A project task is 90% complete. It cannot, however, be finished until another task is completed. What type of dependency is this? (Select two)', '["Fin-début (FD)", "Fin-fin (FF)", "Dépendance obligatoire", "Dépendance préférentielle"]'::jsonb, '["Finish-to-start (FS)", "Finish-to-finish (FF)", "Mandatory dependency", "Discretionary dependency"]'::jsonb, '[1, 2]'::jsonb, 'Il s’agit d’un exemple de dépendance obligatoire de type fin-fin. Dans le cas d’une dépendance fin-fin, deux tâches peuvent effectivement être exécutées simultanément. Toutefois, la seconde tâche ne peut être entièrement achevée qu’après l’achèvement à 100 % de la première tâche (PMBOK, 8e édition, pages 185-186). Les dépendances obligatoires sont celles qui sont exigées par la loi ou par contrat, ou qui sont inhérentes à la nature du travail (PMBOK, 8e édition, page 167).', 'This is an example of finish-to-finish mandatory dependency. Two tasks may in fact run concurrently in the case of a finish-to-finish dependency. However, the second task can be entirely completed only after the first task is 100% done (PMBOK 8th Edition, pages 185-186). Mandatory dependencies are those that are legally or contractually required or inherent in the nature of the work (PMBOK 8th edition, page 167).', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Schedule', 'Schedule', 'Predictive', 'Predictive', true),
('L3Q84', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un nouveau Business Analyst est recruté pour un grand projet. En parcourant les documents, il éprouve des difficultés à comprendre l’objectif et les exigences du projet. Que devrait faire le Business Analyst ?', 'A new business analyst is hired for a large project. While going through the documents, the business analyst finds it difficult to understand the project’s goal and requirements. What should the business analyst do?', '["Ne pas chercher à comprendre l’objectif et les exigences du projet et commencer la planification.", "Demander à l’équipe projet de l’aider à analyser les exigences du projet.", "Demander des clarifications aux parties prenantes.", "Arrêter le projet."]'::jsonb, '["Ignore the understanding of the project’s goal and requirements and start planning.", "Ask the project team to help analyze the project requirements.", "Ask the stakeholders for clarification.", "Stop the project."]'::jsonb, '[2]'::jsonb, 'Le Business Analyst devrait demander des clarifications aux parties prenantes avant de prendre d’autres décisions. Option A : planifier sans comprendre clairement les objectifs et les exigences peut entraîner un désalignement et potentiellement conduire à l’échec du projet. Option B : bien que l’équipe projet puisse expliquer les exigences, les parties prenantes constituent la principale source pour leur recueil.', 'The Business Analyst should seek clarification from the stakeholders before making further decisions. Option A: Planning without a clear understanding of the goals and requirements can lead to misalignment and potentially result in project failure. Option B: While the project team can explain the requirements, stakeholders are the primary source of requirements elicitation.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Stakeholders', 'Stakeholders', 'Hybrid', 'Hybrid', true),
('L3Q85', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet est affecté à un projet de développement d’un logiciel de comptabilité. Dans sa version bêta, certains utilisateurs signalent que le logiciel se bloque une à trois fois par jour. Comme le chef de projet a besoin de davantage d’informations pour résoudre le problème, il demande aux utilisateurs de remplir une _______________ chaque fois que le problème survient, en y indiquant comment le blocage se produit et combien de temps il dure.', 'A project manager is assigned to an accounting software development project. In its beta version, some users reported that the software freezes one to three times a day. Since the project manager needs more information to fix the problem, they asked the users to fill in a _______________ whenever the issue occurs to include information about how the freezing happens and how long it lasts.', '["Feuille de relevé", "Aide-mémoire", "Liste de contrôle", "Enquête"]'::jsonb, '["Check sheet", "Cheat sheet", "Checklist", "Survey"]'::jsonb, '[0]'::jsonb, 'Les feuilles de relevé, également appelées feuilles de comptage, servent à recueillir des faits afin de faciliter la collecte de données supplémentaires concernant un problème potentiel de qualité. Option C : une liste de contrôle permet de vérifier si un ensemble d’étapes requises a été exécuté ou non.', 'Check sheets, aka tally sheets, are used to gather facts in order to facilitate the collection of more data concerning a potential quality issue. Option C: A checklist is used to verify whether a set of required steps has been performed or not.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'resources and Risks', 'Resources and Risks', 'Hybrid', 'Hybrid', true),
('L3Q86', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Faire passer l’organisation de l’état actuel à l’état futur et intégrer une nouvelle solution dans les opérations de l’organisation correspond à :', 'Moving the organization from the current state to the future state, and integrating a new solution into the organization’s operations is known as:', '["Évaluer la performance de l’analyse business", "Planifier l’analyse business", "Évaluer l’état actuel", "Préparer la transition vers l’état futur"]'::jsonb, '["Assessing business analysis performance", "Business analysis planning", "Assessing current state", "Transiting to future state"]'::jsonb, '[3]'::jsonb, 'Pour faire passer l’organisation de son état actuel à un état futur et intégrer efficacement la nouvelle solution dans les opérations, une évaluation de l’état de préparation et un plan de transition doivent être établis (PMBOK, 8e édition, pages 8-7). Il s’agit des résultats du processus « Préparer la transition vers l’état futur ». Option C : l’évaluation de l’état actuel est le processus qui consiste à examiner l’environnement actuellement analysé afin de comprendre les facteurs importants, internes ou externes à l’organisation, susceptibles d’être la cause ou la raison d’un problème ou d’une opportunité.', 'To transition the organization from its current state to a future state and effectively integrate the new solution into operations, a readiness assessment and a transition plan must be established (PMBOK 8th Edition, pages 8-7). These are the outcomes of the "Prepare for Transition to Future State" process. Option C: Assessing current state is the process of examining the current environment under analysis to understand important factors that are internal or external to the organization, which may be the cause or reason for a problem or opportunity.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Gouvernance', 'Gouvernance', 'Hybrid', 'Hybrid', true),
('L3Q87', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Dans une organisation matricielle faible, les employés travaillent sur plusieurs projets et avec différents services de l’entreprise afin d’accroître les interactions entre employés et de favoriser l’esprit d’équipe. Lorsque des employés supplémentaires sont nécessaires, qui est responsable du processus de recrutement dans cette structure matricielle ?', 'In a weak matrix organization, employees work across multiple projects and with various departments within the company to increase employee interaction and promote teamwork spirit. In the event that additional employees are needed, who is in charge of the hiring process under this matrix?', '["Le chef de projet", "Le sponsor", "L’équipe projet", "Le responsable fonctionnel"]'::jsonb, '["The project manager", "The sponsor", "The project team", "The functional manager"]'::jsonb, '[3]'::jsonb, 'Dans une structure matricielle faible, le responsable fonctionnel est chargé de gérer les ressources. Cette forme de structure ressemble fortement à une hiérarchie traditionnelle. Le responsable fonctionnel est le principal décideur du projet, puisqu’il en supervise tous les aspects. Bien que le chef de projet constitue également un point d’autorité, il rend principalement compte au responsable fonctionnel (PMBOK, 8e édition, page 22).', 'The functional manager is the one in charge of managing resources under a weak matrix. This matrix form has a huge resemblance to a traditional workplace hierarchy. A functional manager is a project’s main decision-maker as they supervise all of its aspects. Although the project manager also serves as a point of authority, they primarily report back to the functional manager (PMBOK 8th Edition, page 22).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Predictive', 'Predictive', true),
('L3Q88', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Dans quelle approche de développement les exigences sont-elles souvent communiquées au moyen de communications internes moins formelles et peuvent-elles prendre la forme d’un prototype ?', 'In which development approach are requirements often communicated through less formal internal communications and can take the form of a prototype?', '["Prédictive", "Incrémentale", "Adaptative", "Cascade"]'::jsonb, '["Predictive", "Incremental", "Adaptive", "Waterfall"]'::jsonb, '[2]'::jsonb, 'Dans les méthodologies Agile, une approche adaptative privilégie la communication informelle, le feedback itératif et l’utilisation de prototypes afin d’explorer et d’affiner continuellement les exigences tout au long du développement, ce qui permet d’obtenir un feedback précoce et de procéder à des ajustements. Options A et D : dans les approches de développement prédictives, également appelées « en cascade », les exigences sont généralement bien définies et documentées dès le départ. La communication est plus formelle et structurée (PMBOK, 8e édition, page 61). Option B : le développement incrémental consiste à livrer des parties de la solution par petits incréments gérables (PMBOK, 8e édition, page 63). Le prototypage y est moins fréquemment utilisé qu’en Agile comme outil de communication permettant d’obtenir du feedback.', 'In Agile methodologies, an adaptive approach focuses on informal communication, iterative feedback, and the use of prototypes to continuously explore and refine requirements throughout the development process, allowing for early feedback and adjustments. Options A & D: In predictive development approaches, aka Waterfall, requirements are typically well-defined and documented upfront. Communication is more formal and structured (PMBOK 8th Edition, page 61). Option B: Incremental development involves delivering parts of the solution in small, manageable increments (PMBOK 8th Edition, page 63). Prototyping is used less frequently than Agile as a communication tool to get feedback.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Agile', 'Agile', true),
('L3Q89', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet senior rejoint un projet en cours à la suite de la démission de l’ancien chef de projet. Que devrait faire le nouveau chef de projet en premier ?', 'A senior project manager joins an ongoing project following the resignation of its former project manager. What should the new project manager do first?', '["Examiner le budget du projet afin de déterminer si un financement supplémentaire est nécessaire.", "Parcourir le registre des problèmes afin de vérifier les difficultés antérieures et actuelles auxquelles le projet est confronté.", "Examiner la charte de projet afin de comprendre les objectifs et les livrables du projet.", "Ajouter à l’échéancier du projet une nouvelle activité consacrée au transfert de connaissances."]'::jsonb, '["Review the project budget to determine if more funding is required.", "Go through the issue log to check the previous and current difficulties the project is facing.", "Examine the project charter to understand the project goals and deliverables.", "Add a new activity to the project schedule concerning knowledge transfer."]'::jsonb, '[2]'::jsonb, 'Pour diriger efficacement le projet, le chef de projet devrait connaître parfaitement sa finalité, ses priorités et ses livrables. Après avoir examiné les objectifs et les livrables figurant dans la charte de projet, le chef de projet devrait élaborer un plan de transition afin d’aider l’équipe projet à faire face au changement imprévu, consulter les registres et les rapports du projet, réévaluer ce qui a été accompli jusqu’à présent et maintenir l’engagement de l’équipe envers les objectifs et les priorités du projet.', 'In order to effectively lead the project, the project manager should be fully aware of the project''s purpose, priorities, and deliverables. After examining the goals and deliverables included in the project charter, the project manager should create a transition plan to help the project team cope with the unexpected change, check the project logs and reports, reassess what has been accomplished so far, and maintain the team’s commitment to the project goals and priorities.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Gouvernance', 'Gouvernance', 'Hybrid', 'Hybrid', true),
('L3Q90', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet dirige un projet au sein d’une organisation fonctionnelle. À mi-parcours de la mise en œuvre du projet, un membre de l’équipe quitte l’organisation. Que devrait faire le chef de projet en premier ?', 'A project manager is leading a project within a functional organization. Halfway through the project implementation, a team member left the organization. What should the project manager do first?', '["Collaborer avec le responsable fonctionnel afin d’obtenir un remplaçant.", "Mettre à jour la structure de découpage des ressources du projet.", "Réaffecter sa charge de travail aux membres de l’équipe projet.", "Évaluer l’incidence du départ du membre de l’équipe sur le projet."]'::jsonb, '["Collaborate with the functional manager to get a replacement", "Update the project’s resource breakdown structure", "Reassign their workload to the project team member", "Evaluate the impact of the team member’s departure on the project"]'::jsonb, '[3]'::jsonb, 'Le chef de projet devrait d’abord comprendre l’incidence du départ du membre de l’équipe sur le projet. Cette incidence peut être importante, auquel cas le membre partant doit être rapidement remplacé par une personne expérimentée. Toutefois, son départ peut avoir une incidence limitée et le projet peut se poursuivre sans sa contribution. Options A et C : en fonction des résultats de l’évaluation, une décision devrait être prise quant au remplacement du membre ou à la réaffectation de sa charge de travail. Option B : la structure de découpage des ressources du projet devrait être mise à jour ultérieurement afin de refléter les nouveaux changements.', 'First, the project manager should understand the impact of the team member''s departure on the project. It might have a big impact, therefore the leaving member needs to be promptly replaced with an experienced member. However, their departure might have a limited impact and the project can proceed without their contribution. Options A & C: Based on the evaluation findings, a decision should be taken on whether to get a replacement or reassign the workload. Option B: The project’s resource breakdown structure should be updated later on to reflect the new changes.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Predictive', 'Predictive', true),
('L3Q91', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Laquelle des activités suivantes n’est généralement pas associée à l’analyse business ?', 'Which of the following is not typically associated with business analysis?', '["Déterminer les problèmes et identifier les besoins business.", "Identifier et recommander des solutions viables.", "Définir le périmètre du projet et atteindre les objectifs du projet.", "Identifier et gérer les parties prenantes.", "S’assurer que le projet produit la valeur attendue."]'::jsonb, '["Determine problems and identify business needs", "Identify and recommend viable solutions", "Define project scope and achieve project objectives", "Identify and manage stakeholders", "Ensure that the project meets the intended value"]'::jsonb, '[2]'::jsonb, 'La définition du périmètre et des objectifs du projet relève principalement de la responsabilité du chef de projet. Bien que le Business Analyst puisse contribuer à ce processus, celui-ci ne constitue pas l’objectif principal de son rôle.', 'Defining the project scope and objectives is primarily the responsibility of the project manager. While the business analyst can contribute to this process, it is not the main focus of their role.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Hybrid', 'Hybrid', true),
('L3Q92', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Lequel des éléments suivants un chef de projet devrait-il utiliser pour prévenir d’éventuels problèmes futurs ?', 'Which of the following should a project manager use to prevent potential future problems?', '["Indicateurs retardés", "Indicateurs avancés", "Management de la valeur acquise (EVM)", "Objectifs et résultats clés (OKR)"]'::jsonb, '["Lagging indicators", "Leading indicators", "Earned Value Management (EVM)", "Objectives and Key Results (OKRs)"]'::jsonb, '[1]'::jsonb, 'Les indicateurs avancés servent à prévoir et à prévenir les problèmes futurs en fournissant des signaux précoces sur des difficultés potentielles. Ils permettent au chef de projet de prendre des mesures proactives avant que les problèmes ne surviennent réellement. Les indicateurs retardés mesurent la performance passée et sont donc réactifs. Le management de la valeur acquise (EVM) porte sur la performance des coûts et de l’échéancier, tandis que les objectifs et résultats clés (OKR) servent à définir les objectifs et à suivre les résultats ; ils ne sont pas spécifiquement destinés à la prévention.', 'Leading indicators are used to predict and prevent future problems by providing early signals about potential issues. They allow the project manager to take proactive actions before problems actually occur. Lagging indicators measure past performance, so they are reactive. Earned Value Management (EVM) focuses on cost and schedule performance, and OKRs are for goal setting and tracking outcomes; not specifically for prevention.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Hybrid', 'Hybrid', true),
('L3Q93', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un projet est planifié sur une durée de 10 mois et dispose d’un budget de 100 000 $. Un mois après le démarrage du projet, l’équipe a achevé 10 % du travail total. Quel est l’indice de performance de l’échéancier (IPE) actuel du projet ?', 'A project is scheduled to last 10 months with a budget of $100,000. One month into the project, the team completed 10% of the total work. What is the project’s current Schedule Performance Index (SPI)?', '["0,1", "1", "1,1", "10"]'::jsonb, '["0.1", "1", "1.1", "10"]'::jsonb, '[1]'::jsonb, 'L’indice de performance de l’échéancier (IPE) mesure la conformité entre la progression réelle, c’est-à-dire la valeur acquise, et la progression planifiée : IPE = VA / VP (PMBOK, 8e édition, page 209). Une valeur de 1,0 indique que la performance du projet est conforme aux prévisions. VA = 10 % × 100 000 $ = 10 000 $ ; VP = (1 mois / 10 mois) × 100 000 $ = 10 000 $ ; par conséquent, IPE = VA / VP = 1. Option A : un IPC ou un IPE inférieur à 1,0 indique une performance du projet inférieure aux prévisions (PMBOK, 8e édition, page 208). Options C et D : un IPC ou un IPE supérieur à 1,0 indique une performance du projet meilleure que prévu.', 'The Schedule Performance Index (SPI) is a measure of the conformance of actual progress (earned value) to the planned progress: SPI = EV / PV (PMBOK 8th edition, page 209). A value of 1.0 indicates that the project performance is on target. EV = 10% x $100,000 = $10,000, PV = (1 Month / 10 Months) x $100, 000 = $10,000 then SPI = EV / PV = 1. Option A: A CPI or SPI that is less than 1.0 indicates poorer-than-planned project performance (PMBOK 8th edition, page 208). Options C & D: When CPI or SPI is greater than 1.0, it indicates better-than-planned project performance.', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Finance', 'Finance', 'Predictive', 'Predictive', true),
('L3Q94', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'En Agile, à quoi sert la technique du Planning Poker ?', 'In agile, what is the planning poker technique used for?', '["Estimer l’effort nécessaire pour achever les tâches.", "Estimer la quantité de travail restante dans le sprint.", "Tester le projet et identifier les obstacles.", "Mesurer la vélocité du sprint."]'::jsonb, '["Estimating how much effort is needed to complete tasks", "Estimating how much work is left in the sprint", "Testing the project and identifying blockers", "Measuring the sprint velocity"]'::jsonb, '[0]'::jsonb, 'Le Planning Poker est une technique fondée sur des cartes, principalement utilisée pour estimer les activités du projet. Il s’agit d’une technique d’estimation fondée sur le consensus (PMBOK, 8e édition, page 52). Elle peut être utilisée avec des story points, des jours idéaux ou toute autre unité d’estimation. L’estimation est réalisée à l’aide de cartes de poker. Les membres de l’équipe discutent de la fonctionnalité et posent au Product Owner toutes les questions qu’ils peuvent avoir. Ensuite, chaque membre de l’équipe choisit en privé une carte représentant son estimation. Toutes les cartes doivent alors être révélées simultanément. Si tous les membres de l’équipe choisissent la même valeur, celle-ci devient l’estimation finale. Dans le cas contraire, une nouvelle discussion sur les différents avis et estimations a lieu avant de procéder à une nouvelle estimation de la fonctionnalité ou de la tâche.', 'Planning poker is a card-based technique that is mostly used for estimating project activities. It is a consensus-based estimating technique (PMBOK 8th edition, page 52). It can be used with story points, ideal days, or any other estimation unit. The estimation is done using poker cards. Team members discuss the feature, asking the product owner any questions they might have. Then, privately, each team member picks out one card that presents their estimate. All cards should be then revealed at once. If all team members select the same value, it’s set as the final estimate. Otherwise, a discussion of the different opinions and estimates will take place again before re-estimating the feature or task again.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Schedule', 'Schedule', 'Agile', 'Agile', true),
('L3Q95', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet dirige le projet de construction d’une résidence de luxe. Avant de procéder à l’excavation du site, une autorisation gouvernementale doit être délivrée. Quel type de dépendance cette situation décrit-elle ?', 'A project manager is leading the construction project of a luxury residency. Before proceeding with the site excavation process, a government clearance must be issued. What kind of dependency does this describe?', '["Logique souple", "Logique préférentielle", "Dépendance externe", "Dépendance préférentielle"]'::jsonb, '["Soft logic", "Preferential logic", "External dependency", "Discretionary dependency"]'::jsonb, '[2]'::jsonb, 'Une dépendance externe est une relation entre des activités du projet et des activités externes qui ne sont pas liées au projet. Même si elle échappe au contrôle de l’équipe projet, cette dépendance devrait être intégrée à l’échéancier du projet (PMBOK, 8e édition, page 168). Options A, B et D : les dépendances préférentielles, également appelées logique souple, logique privilégiée ou logique préférentielle, ne sont pas obligatoires (PMBOK, 8e édition, page 167).', 'External dependency is the relationship between project activities and external activities that are not related to the project. Even though it’s beyond the project team’s control, such a dependency should be reflected in the project schedule (PMBOK 8th edition, page 168). Option A & D: Discretionary dependencies, also referred to as soft logic, preferred logic, or preferential logic, are not mandatory (PMBOK 8th edition, page 167).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Schedule', 'Schedule', 'Predictive', 'Predictive', true),
('L3Q96', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Au cours d’une réunion réunissant 15 membres de l’équipe, le Product Owner discute des exigences du produit et recueille des idées à leur sujet. Toutefois, en raison du grand nombre d’idées proposées, les participants décident de voter. Après le vote, le Product Owner constate qu’une idée particulière a recueilli 9 voix et retient donc cette option. Quel type de prise de décision cette situation illustre-t-elle ?', 'During a meeting with 15 team members, the product owner was discussing and collecting ideas about the product requirements. However, since there were a lot of suggested ideas, participants decided to vote. After voting, the product owner finds that a particular idea received 9 votes, so they go with that option. What type of decision-making does this depict?', '["Unanimité", "Majorité", "Pluralité", "Dictature"]'::jsonb, '["Unanimity", "Majority", "Plurality", "Dictatorship"]'::jsonb, '[1]'::jsonb, 'Le vote est une technique de prise de décision collective qui peut être utilisée pour générer et prioriser les exigences du projet. L’unanimité, la pluralité et la majorité sont des exemples de techniques de vote. Une décision à la majorité nécessite le soutien de plus de 50 % des membres du groupe (PMBOK, 8e édition, page 163).', 'Voting is a technique for collective decision-making that can be used to generate and prioritize project requirements. Unanimity, plurality, and majority are examples of voting techniques. A majority decision requires support from more than 50% of the group members (PMBOK 8th Edition, page 163).', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Gouvernance', 'Gouvernance', 'Agile', 'Agile', true),
('L3Q97', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet est affecté à un nouveau projet Agile. Que devrait-il faire en premier ?', 'A project manager is assigned to a new Agile project. What should they do first?', '["Identifier tous les risques.", "Déterminer toutes les activités des sprints.", "Définir les critères de réussite du projet.", "Définir les métriques de qualité."]'::jsonb, '["Identify all risks", "Determine all of the sprints’ activities", "Define the project success criteria", "Define quality metrics"]'::jsonb, '[2]'::jsonb, 'Afin d’assurer la réussite de la livraison du projet, le chef de projet devrait d’abord définir les critères de réussite avec le sponsor. S’accorder sur les critères de réussite du projet réduira les possibilités d’échec et renforcera ses chances de réussite. Lors de la détermination des critères de réussite du projet, il convient d’éviter les termes vagues et généraux et de privilégier la précision et la clarté. Il est recommandé d’être précis en indiquant, par exemple : « le produit devrait être achevé au plus tard le 30 novembre », plutôt que : « le produit devrait être achevé dès que possible ».', 'To ensure the successful delivery of the project, the project manager should first define success criteria with the sponsor. Agreeing upon the project’s success criteria will reduce the possibilities of its failure and reinforce its success odds. When determining the project success criteria, you should avoid using unclear and general terms and focus on being precise and clear. It’s recommended to be specific by saying, for instance: “the product should be completed by November 30th” instead of saying “the product should be completed as soon as possible”.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Gouvernance', 'Gouvernance', 'Agile', 'Agile', true),
('L3Q98', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet est affecté à un projet qui suit une approche adaptative. Après avoir recueilli toutes les exigences, le chef de projet prévoit trois à cinq releases pour atteindre l’objectif du projet et envisage d’élaborer progressivement les détails sur la base du feedback des parties prenantes. Étant donné que le projet dispose d’un budget fixe qui ne peut pas être dépassé, que devrait faire le chef de projet ?', 'A project manager is assigned to a project that follows an adaptive approach. After gathering all requirements, the project manager previewed 3 to 5 releases to achieve the project goal and plans to progressively elaborate details based on stakeholder feedback. Given that the project has a fixed budget that cannot be exceeded, what should the project manager do?', '["Puisque le budget est fixe, le chef de projet devrait adopter une approche prédictive plutôt qu’une approche adaptative pour le projet.", "Puisque les risques de dérive du périmètre sont élevés, le chef de projet devrait s’assurer qu’un comité de maîtrise des changements (CCB) est mis en place avant le démarrage du projet.", "Avant le démarrage du projet, le chef de projet devrait fixer le nombre de releases et élaborer un budget détaillé pour chacune d’elles.", "Le chef de projet devrait collaborer avec les parties prenantes afin de prioriser le travail de chaque release jusqu’à épuisement du budget."]'::jsonb, '["Since the budget is fixed, the project manager should adopt a predictive approach for the project instead of an adaptive approach.", "Since chances of scope creep are high, the project manager should ensure that a Change Control Board (CCB) is established before the start of the project.", "Before the start of the project, the project manager should set a fixed number of releases and develop a detailed budget for each of them.", "The project manager should work with stakeholders to prioritize work for each release until running out of budget."]'::jsonb, '[3]'::jsonb, 'Dans une approche adaptative, le coût et l’échéancier du projet sont fixes, tandis que le périmètre peut être ajusté afin de respecter la contrainte de coût. Par conséquent, le chef de projet doit prioriser les fonctionnalités les plus importantes lors de la planification de chaque release, jusqu’à épuisement de la totalité du budget. Options A, B et C : toutes les autres options impliquent l’utilisation d’une approche prédictive, qui ne conviendrait pas à ce projet puisque son périmètre est imprévisible.', 'With an adaptive approach, the project’s cost and schedule are fixed, while the scope can be adjusted to stay within the cost constraint. Consequently, the project manager needs to prioritize the most important features when planning each release until they exhaust the whole budget. Options A & B & C: All other options imply using the predictive approach, which won’t work for this project since its scope is unpredictable.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Finance', 'Finance', 'Agile', 'Agile', true),
('L3Q99', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet s’appuie sur le timeboxing afin d’aider les membres de l’équipe à éviter de perdre du temps sur un travail superficiel et à rester concentrés sur les principaux livrables. Laquelle des affirmations suivantes décrit le mieux le timeboxing ?', 'A project manager depends on time-boxing to help team members avoid wasting time on shallow work and stay focused on the main deliverables. Which of the following statements best describes time-boxing?', '["Une durée d’activité intense au sein d’une release donnée.", "Un intervalle de temps réservé à l’exécution d’activités précises.", "Une planification serrée visant à réduire le temps nécessaire à l’achèvement d’une activité.", "La fixation d’une date limite pour la livraison du produit."]'::jsonb, '["Duration of intense activity within a specific release", "A time frame for executing specific activities", "Tight planning to reduce the time required for an activity completion", "Setting a deadline for product delivery"]'::jsonb, '[1]'::jsonb, 'Une timebox est une période de temps fixe pendant laquelle le travail doit être achevé (PMBOK, 8e édition, page 275). La durée de la timebox peut être de quelques heures, de quelques jours ou de quelques semaines, selon la complexité ou l’ampleur du travail.', 'A timebox is a fixed period of time in which work has to be completed (PMBOK 8th edition, page 275). The timebox duration could be a few hours, days, or weeks depending on the work complexity or size.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Schedule', 'Schedule', 'Agile', 'Agile', true),
('L3Q100', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Laquelle des options suivantes relève des responsabilités du chef de projet en Agile ?', 'Which of the following options falls under the project manager’s responsibilities in Agile?', '["Fournir l’orientation stratégique globale.", "Maîtriser le budget du projet.", "Définir les user stories et prioriser le backlog.", "S’assurer que l’équipe livre le projet conformément aux exigences définies."]'::jsonb, '["Providing the overall strategic direction", "Controlling the project budget", "Defining user stories and prioritizing the backlog", "Ensuring that the team delivers the project according to the defined requirements"]'::jsonb, '[3]'::jsonb, 'En Agile, le chef de projet — également appelé Scrum Master, responsable de l’équipe projet ou coach d’équipe — est chargé d’éliminer les obstacles et de veiller à ce que l’équipe pluridisciplinaire soit performante et livre le produit tel qu’il a été initialement défini par le Product Owner (Agile Practice Guide, pages 40-41).', 'In Agile, a project manager (also known as scrum master, project team lead, or team coach) is responsible for removing impediments and ensuring that the cross-functional team performs and delivers the product as initially defined by the product owner (Agile Practice Guide, pages 40-41).', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'resources and Risks', 'Resources and Risks', 'Agile', 'Agile', true),
('L3Q101', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet achève un projet d’une durée d’un an. Laquelle des activités suivantes devrait être prioritaire ?', 'A project manager is wrapping up a one-year project. Which of the following activities should be prioritized?', '["Mettre à jour le journal des changements.", "Libérer les ressources du projet.", "Achever les activités de transfert des connaissances.", "Célébrer l’achèvement du projet."]'::jsonb, '["Updating the change log", "Releasing the project resources", "Completing the knowledge transfer activities", "Celebrating the project’s completion"]'::jsonb, '[2]'::jsonb, 'Comme les projets sont des initiatives temporaires, une grande partie des connaissances acquises est perdue une fois le projet achevé. Le chef de projet devrait accorder une attention particulière à la documentation et au transfert des connaissances afin de permettre à l’organisation d’acquérir et de conserver les connaissances et l’expérience obtenues grâce à la réalisation des projets. Options A, B et D : une fois cette activité achevée, une célébration peut avoir lieu et les ressources peuvent être libérées. Par ailleurs, le journal des changements devrait être mis à jour afin de suivre l’état des demandes de changement.', 'Because projects are temporary endeavors, most of the acquired knowledge is lost once the project is completed. The project manager should be attentive to knowledge documentation and transfer to allow the organization to gain and retain the knowledge and experience obtained through running projects. Options A, B, D: Once this activity is completed, a celebration could take place and resources can be released. On the other hand, the change log should be updated to monitor the change requests’ status.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Predictive', 'Predictive', true),
('L3Q102', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Que signifie le leadership distribué ?', 'What does distributed leadership mean?', '["La direction générale est encouragée à adopter des comportements de leadership.", "Le chef de projet et le Product Owner sont encouragés à adopter des comportements de leadership.", "Les membres de l’équipe projet sont encouragés à adopter des comportements de leadership.", "Toutes les parties prenantes sont encouragées à adopter des comportements de leadership."]'::jsonb, '["Top management is encouraged to adopt leadership behaviors.", "The project manager and the product owner are encouraged to adopt leadership behaviors.", "Project team members are encouraged to adopt leadership behaviors.", "All stakeholders are encouraged to adopt leadership behaviors."]'::jsonb, '[2]'::jsonb, 'Le leadership distribué signifie que le leadership est partagé au sein de l’équipe et ne se limite pas aux rôles officiels. Les membres de l’équipe projet sont encouragés à prendre des initiatives, à contribuer aux décisions et à adopter des comportements de leadership. Il ne désigne pas spécifiquement la direction générale, certains rôles seulement ou l’ensemble des parties prenantes.', 'Distributed leadership means that leadership is shared across the team, not limited to formal roles. Project team members are encouraged to take initiative, contribute to decisions, and demonstrate leadership behaviors. It does not specifically refer to top management, only certain roles, or all stakeholders.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'resources and Risks', 'Resources and Risks', 'Agile', 'Agile', true),
('L3Q103', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Dans une approche de développement adaptative, quel outil ou quelle technique met l’accent sur l’identification et l’analyse des fonctionnalités capables de fournir une valeur immédiate ?', 'In an adaptive development approach, which tool or technique focuses on identifying and analyzing features that can deliver immediate value?', '["Feature injection", "Story map", "Management de la valeur acquise", "Cartographie de la chaîne de valeur"]'::jsonb, '["Feature injection", "Story map", "Earned value management", "Value stream mapping"]'::jsonb, '[0]'::jsonb, 'La feature injection est un cadre et un ensemble de principes conçus pour améliorer et accélérer le développement et l’analyse des exigences produit. Cette approche est particulièrement privilégiée par les équipes qui utilisent des méthodes de développement adaptatives. Son concept central consiste à orienter les discussions et l’analyse vers les fonctionnalités susceptibles de fournir une valeur immédiate (PMI Guide to Business Analysis, pages 88 et 89). Option B : une story map est un modèle visuel de l’ensemble des fonctionnalités, créé pour donner à l’équipe une vue globale de ce qu’elle construit. Option C : le management de la valeur acquise sert à déterminer la performance des coûts et de l’échéancier d’un projet prédictif. Option D : la cartographie de la chaîne de valeur est une technique de collecte de données utilisée pour documenter, analyser et améliorer le flux d’informations ou de matières (PMBOK, 8e édition, page 211).', 'Feature injection is a framework and set of principles designed to enhance and accelerate the development and analysis of product requirements. This approach is particularly favored by teams employing adaptive development methods. Its core concept is to direct discussions and analysis towards features that offer the potential for immediate value (PMI Guide to Business Analysis, pages 88 & 89). Story map is a visual model of all the features and functionality, created to give the team a global view of what they are building. Earned value management is used to determine the cost and schedule performance of a predictive project. Value stream mapping is a data gathering technique used to document, analyze, and improve the flow of information or materials (PMBOK 8th Edition, Page 211).', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Agile', 'Agile', true),
('L3Q104', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Quelle est la différence entre une action corrective et une action préventive ?', 'What is the difference between a corrective and a preventive action?', '["Les actions correctives traitent ce qui se produira à l’avenir, tandis que les actions préventives traitent ce qui s’est déjà produit.", "Les actions correctives traitent ce qui s’est déjà produit, tandis que les actions préventives traitent ce qui pourrait se produire à l’avenir.", "Les actions correctives font partie du domaine d’intervention de l’exécution, tandis que les actions préventives font partie du domaine d’intervention de la maîtrise et du suivi.", "Les actions préventives font partie du domaine d’intervention de l’exécution, tandis que les actions correctives font partie du domaine d’intervention de la maîtrise et du suivi."]'::jsonb, '["Corrective actions address what will occur in the future, while preventive actions address what already occurred in the past.", "Corrective actions address what already occurred in the past, while preventive actions address what will occur in the future.", "Corrective actions are part of the executing focus area whereas preventive actions are part of the controlling and monitoring focus area.", "Preventive actions are part of the executing focus area whereas corrective actions are part of the controlling and monitoring focus area."]'::jsonb, '[1]'::jsonb, 'Les actions correctives sont réactives, car elles sont mises en œuvre pour corriger des problèmes qui se sont produits et ramener le projet en conformité avec les références de base. Les actions préventives, en revanche, sont proactives, car elles sont prises afin d’éviter que le projet ne s’écarte du plan. Options C et D : les actions correctives et préventives peuvent toutes deux relever aussi bien du domaine d’intervention de l’exécution que de celui du suivi.', 'Corrective actions are reactive as they’re performed to fix issues that have occurred to bring the project back into alignment with the baselines. Preventive actions, on the other hand, are proactive as they’re taken to ensure that the project doesn''t deviate from the plan. Options C & D: Both corrective and preventive actions can be part of the executing focus area as well as the monitoring focus area.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Hybrid', 'Hybrid', true),
('L3Q105', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'La connaissance est parfois représentée comme un iceberg, car elle comprend deux catégories :', 'Knowledge is sometimes depicted as an iceberg since it involves two categories:', '["Explicite et tacite", "Connue et inconnue", "Directe et indirecte", "Profonde et superficielle"]'::jsonb, '["Explicit and tacit", "Known and unknown", "Direct and indirect", "Deep and superficial"]'::jsonb, '[0]'::jsonb, 'La connaissance peut être explicite ou tacite. La connaissance explicite peut être exprimée et consignée à l’aide d’images, de mots et de nombres. La connaissance tacite, comme les expériences et les croyances, est plus difficile à exprimer ou à consigner (PMBOK, 8e édition, pages 24 à 26).', 'Knowledge can be either explicit or tacit knowledge. Explicit knowledge can be expressed and captured using pictures, words, and numbers. Tacit knowledge, such as experiences and beliefs, is more difficult to express or capture (PMBOK 8th edition, pages 24-26).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Hybrid', 'Hybrid', true),
('L3Q106', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un Product Owner développe un nouveau produit et examine les outils qui seront mis en œuvre. Quel est, dans ce contexte, l’objectif principal de l’utilisation des techniques de vision produit ?', 'A Product Owner is developing a new product and is considering the tools that will be implemented. What is the primary purpose of using product visioning techniques in this context?', '["Établir l’échéancier détaillé du projet.", "Élaborer la roadmap produit.", "Identifier les rôles et responsabilités de l’équipe projet.", "Créer le plan de management des risques."]'::jsonb, '["Detailed project schedule establishment", "Product roadmap development", "Project team roles and responsibilities identification", "Risk management plan creation"]'::jsonb, '[1]'::jsonb, 'La vision produit est un outil et une technique du processus « Faciliter l’élaboration de la roadmap produit ». Elle sert à définir l’orientation de haut niveau d’un produit ou d’une release de produit (PMI Guide to Business Analysis, page 95).', 'Product visioning is a tool and technique for the “facilitate product roadmap development” process. It’s used to set the high-level direction for a product or a product release (PMI Guide to Business Analysis, page 95).', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Agile', 'Agile', true),
('L3Q107', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Afin de s’assurer que le projet est réalisé conformément aux exigences de l’organisation, le chef de projet effectue un processus d’adaptation. Dans ce contexte, l’adaptation consiste en :', 'In order to ensure that the project is performed in accordance with the organization’s requirements, the project manager carries out a tailoring process. Under this context, Tailoring is:', '["Les connaissances et pratiques applicables à la plupart des projets dans la plupart des cas.", "L’application d’un ensemble de connaissances, de compétences, d’outils et de techniques aux activités du projet afin d’en satisfaire les exigences.", "La sélection des processus, entrées, outils, techniques et phases du cycle de vie appropriés pour manager un projet.", "L’application des connaissances, compétences, outils et techniques nécessaires pour satisfaire les exigences d’un programme."]'::jsonb, '["The knowledge and practices which are applicable to most projects in most cases.", "The application of a set of knowledge, skills, tools, and techniques to the project activities in order to meet its requirements.", "The selection of the appropriate processes, inputs, tools, techniques, and life cycle phases for managing a project.", "The application of knowledge, skills, tools, and techniques needed for meeting a program’s requirements."]'::jsonb, '[2]'::jsonb, 'L’adaptation consiste à sélectionner les processus appropriés, leurs entrées et sorties associées, les techniques ainsi que les phases du cycle de vie afin de manager un projet. Option B : le management de programme est l’application de connaissances, de compétences, d’outils et de techniques afin de satisfaire les exigences du programme (PMBOK, 8e édition, page 271). Option D : le management de projet est l’application d’un ensemble de connaissances, de compétences, d’outils et de techniques aux activités du projet afin d’en satisfaire les exigences (PMBOK, 8e édition, page 271).', 'Tailoring involves the selection of the appropriate processes, related inputs and outputs, techniques, and life cycle phases in order to manage a project. Option B: Program management is the application of knowledge, skills, tools, and techniques to meet the program requirements (PMBOK 8th Edition, page 271). Option D: Project management is the application of a set of knowledge, skills, tools, and techniques to project activities to meet the project requirements (PMBOK 8th Edition, page 271).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Gouvernance', 'Gouvernance', 'Hybrid', 'Hybrid', true),
('L3Q108', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'À mesure que la roadmap est élaborée, le périmètre de chaque release peut inclure des fonctionnalités, des fonctions, des epics et des user stories. Ce processus de décomposition est similaire à quel outil de management de projet ?', 'As the roadmap is elaborated, the scope of each release may include features, functions, epics, and user stories. This decomposition process is similar to which project management tool?', '["Product Backlog", "Structure de découpage du projet (WBS)", "Diagramme de Gantt", "Tableau Kanban"]'::jsonb, '["Product Backlog", "Work Breakdown Structure (WBS)", "Gantt Chart", "Kanban Board"]'::jsonb, '[1]'::jsonb, 'La structure de découpage du projet (WBS) est un outil de management de projet qui décompose un projet en segments plus petits et plus faciles à gérer, souvent appelés lots de travaux. Elle aide à organiser et à définir l’ensemble du périmètre du projet en créant une décomposition hiérarchique du travail à exécuter (PMBOK, 8e édition, page 38). Option A : le Product Backlog est principalement une liste priorisée de fonctionnalités, de user stories et de tâches pour un produit. Il met l’accent sur ce qui doit être réalisé et sur les priorités, mais ne fournit pas une décomposition structurée du travail en segments plus petits et gérables comme le fait la structure de découpage du projet (WBS) (PMBOK, 8e édition, pages 38-39).', 'The Work Breakdown Structure (WBS) is a project management tool that breaks down a project into smaller, more manageable segments, often referred to as work packages. It helps in organizing and defining the total scope of the project by creating a hierarchical decomposition of the work to be executed (PMBOK 8th Edition, page 38). Option A: The Product Backlog is primarily a prioritized list of features, user stories, and tasks for a product. It focuses on what needs to be done and their priority but does not provide a structured breakdown of work into smaller, manageable segments like the Work Breakdown Structure (WBS) does (PMBOK 8th Edition, pages 38-39).', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Hybrid', 'Hybrid', true),
('L3Q109', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Trois mois après le début de l’exécution du projet, le sponsor traverse une crise financière et demande au chef de projet d’arrêter immédiatement le projet. Que devrait faire ensuite le chef de projet ?', '3 months into project execution, the sponsor gets into a financial crisis and asks the project manager to immediately end the project. What should the project manager do next?', '["Essayer de persuader le client d’achever le projet.", "Discuter de la situation avec sa direction.", "Démarrer le processus de clôture des approvisionnements.", "Démarrer le processus de clôture du projet."]'::jsonb, '["Try to persuade the client to complete the project", "Talk to their management about the situation", "Start the close procurement process", "Start the close project process"]'::jsonb, '[3]'::jsonb, 'Lorsque le projet est clôturé ou arrêté pour quelque raison que ce soit, le chef de projet devrait démarrer le processus de clôture. La clôture des approvisionnements fait partie du processus « Clore le projet » (PMBOK, 8e édition, page 32). La situation décrite dans la question exige l’arrêt du projet ; la réponse correcte consiste donc à exécuter le processus qui traite cette situation, à savoir le processus Clore le projet. En outre, rien dans la question n’indique que le projet comporte des approvisionnements.', 'When the project is closed or terminated for any reason, the project manager should start the close process. Procurement closure is part of the "Close project" process (PMBOK 8th Edition, page 32). The situation in the question requires project termination, so the Correct Answer implies executing the process that addresses the situation, i.e. the Close Project process. Plus, there is no indication in the question that the project has procurements.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Gouvernance', 'Gouvernance', 'Predictive', 'Predictive', true),
('L3Q110', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet dirige une équipe dont les membres sont répartis dans différents pays. Outre les barrières culturelles, l’équipe semble déconnectée, ce qui entraîne plusieurs cas de reprise du travail. Que pourrait faire le chef de projet pour améliorer la communication au sein de l’équipe ?', 'A project manager is leading a team with distributed members across different countries. Apart from cultural barriers, the team seems disconnected, leading to multiple rework cases. What could the project manager do to improve communication within the team?', '["Collaborer avec la direction générale afin de regrouper l’équipe sur un même site.", "Demander à l’équipe d’utiliser uniquement les e-mails pour communiquer afin d’éviter tout malentendu ou toute interprétation erronée.", "Tenir de courtes réunions quotidiennes avec tous les membres de l’équipe afin de synchroniser le travail de chacun.", "Proposer aux membres de l’équipe une formation sur la manière de surmonter les barrières culturelles."]'::jsonb, '["Collaborate with senior management to co-locate the team.", "Request from the team to only use emails for communication to avoid any misunderstanding or misinterpretation.", "Hold short daily meetings with all team members to sync on what everyone is doing.", "Offer team members training about overcoming cultural barriers."]'::jsonb, '[2]'::jsonb, 'Les courtes réunions quotidiennes sont appelées réunions daily standup. Elles constituent un cadre permettant à chaque membre de partager ce qu’il a accompli, ce qu’il fera ensuite et les obstacles auxquels il est confronté. Ce type de réunion aide à créer des liens entre les membres de l’équipe, améliore la communication et réduit ainsi les reprises du travail (PMBOK, 8e édition, page 162). Le regroupement sur un même site peut également résoudre ce problème. Toutefois, les membres de l’équipe sont dispersés dans différents pays, ce qui rend difficile leur rassemblement en un seul lieu. Option B : une communication écrite et asynchrone, comme les e-mails, ne favorise pas autant les liens et les relations que des canaux verbaux synchrones, comme les réunions virtuelles. Option D : proposer aux membres de l’équipe une formation sur les différences culturelles pourrait seulement les aider à surmonter les barrières culturelles ; cela ne leur permettrait pas de synchroniser leur travail afin d’éviter les reprises.', 'Short daily meetings are referred to as daily standup meetings which represent a framework for sharing what each member has accomplished, what they will be doing next, and what blockers they’re facing. This type of meeting helps build a connection between team members, improves communication, and as a result reduces rework (PMBOK 8th Edition, page 162). Co-location can resolve this issue too. However, team members are dispersed in different countries, making it difficult to assemble them in one location. Option B: Written, asynchronous communication such as emails does not promote bonding or building connections in comparison to verbal synchronous channels such as virtual meetings Option D: Offering team members training about cultural differences could only help them overcome cultural barriers, but it can’t help them sync their work to avoid rework.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Agile', 'Agile', true),
('L3Q111', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Une organisation demande au chef de projet de lui transmettre un rapport sur le coût de la qualité. Le rapport indique un coût total de 30 000 $, détaillé comme suit : D’après le tableau ci-dessus, à combien s’élèvent les coûts d’évaluation du projet ?', 'An organization asked the project manager to send a report on the cost of quality. The report stated that the total cost was $30,000, detailed as follows: According to the table above, how much is the project''s appraisal cost?', '["2 000 $", "3 000 $", "5 000 $", "10 000 $"]'::jsonb, '["$2,000", "$3,000", "$5,000", "$10,000"]'::jsonb, '[2]'::jsonb, 'Les coûts d’évaluation, également appelés coûts d’inspection, font partie des coûts de conformité, car ils représentent les coûts engagés pour identifier les produits défectueux avant leur livraison aux clients. Ils comprennent les essais, les inspections, les audits, les évaluations et les mesures des livrables, produits ou services réalisés par le projet. Les coûts d’évaluation sont établis pour mettre en œuvre une série d’activités visant à déterminer le degré de conformité des résultats du travail aux exigences de qualité. Ainsi, les coûts d’évaluation du projet correspondent aux coûts d’inspection, soit 5 000 $. La formation relève des activités de prévention. Les coûts de reprise et de rebut font partie des coûts de défaillance interne, tandis que les frais de garantie relèvent des coûts de défaillance externe (PMBOK, 8e édition, page 159).', 'Appraisal costs, also known as inspection costs, are part of the Cost of Conformance as they represent the costs of identifying defective products before they are delivered to clients. This comprises testing, inspecting, auditing, evaluating, and measuring the deliverables, products, or services the project is producing. Appraisal costs are set up to implement a series of activities to determine work results’ degree of conformance to quality requirements. This means that the project appraisal cost involves inspection costs which are $5,000. Training falls under prevention activities. Rework and scrap costs, on the other hand, are part of the Internal Failure Costs, whereas Warranty charges fall under External Failure Costs (PMBOK 8th Edition, page 159).', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Finance', 'Finance', 'Predictive', 'Predictive', true),
('L3Q112', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Tous les éléments suivants sont des cadres Agile ou Lean, sauf :', 'All of the following are either Agile or Lean frameworks except:', '["Scrumban", "eXtreme Programming", "Cascade", "Méthodes Crystal"]'::jsonb, '["Scrumban", "eXtreme Programming", "Waterfall", "Crystal Methods"]'::jsonb, '[2]'::jsonb, 'La cascade est une méthodologie prédictive considérée comme trop rigide pour gérer les exigences changeantes générées par les nouvelles technologies ou par un client exigeant. Bien qu’il existe de nombreux cadres Agile et Lean, l’Agile Practice Guide ne traite que de Scrum, Scrum of Scrums, SAFe, la méthode Kanban, Scrumban, eXtreme Programming (XP), les méthodes Crystal, la méthode de développement des systèmes dynamiques (DSDM), le développement piloté par les fonctionnalités (FDD) et l’Agile Unified Process.', 'Waterfall is a predictive methodology that was deemed too rigid to handle the changing requirements brought on by new technology or a demanding client. Even though there are numerous Agile and Lean frameworks, the Agile Practice Guide only addresses Scrum, Scrum of scrums, SAFe, Kanban Method, Scrumban, eXtreme Programming (XP), Crystal Methods, Dynamic Systems Development Method (DSDM), Feature-Driven Development (FDD), and Agile Unified Process.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Gouvernance', 'Gouvernance', 'Agile', 'Agile', true),
('L3Q113', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet dirige un projet de construction. Les travaux sur les points lumineux sont en attente, car les dalles de plafond sont encore en cours de pose, ce qui pourrait entraîner des retards dans le projet. À quoi le chef de projet devrait-il se référer afin de vérifier la disponibilité de l’équipe d’électricité au cours des deux prochaines semaines pour résoudre cette dépendance ?', 'A project manager is leading a construction project. Work on light spots is pending since ceiling tiles are still being installed, which may cause some delays within the project. What should the project manager refer to in order to check the electricity team’s availability in the next two weeks to resolve this dependency?', '["Calendriers des ressources", "Matrice d’affectation des responsabilités (RAM)", "Matrice RACI", "Organigramme"]'::jsonb, '["Resource Calendars", "Responsibility Assignment Matrix (RAM)", "RACI Matrix", "Organigram"]'::jsonb, '[0]'::jsonb, 'Un calendrier des ressources est un calendrier servant à planifier, manager et suivre les ressources, notamment les employés et les équipements. Il donne au chef de projet une vue d’ensemble de l’utilisation des ressources, des ressources disponibles et des périodes de disponibilité (PMBOK, 8e édition, page 132). Option B : la matrice d’affectation des responsabilités (RAM) décrit la participation des différentes parties ainsi que leurs rôles dans l’achèvement des tâches ou des livrables d’un projet. Elle sert à clarifier les rôles et responsabilités au sein d’une équipe, d’un projet ou d’un processus (PMBOK, 8e édition, pages 131-132). Option C : RACI est l’acronyme de Responsible, Accountable, Consulted et Informed. Cette matrice sert à attribuer les rôles et responsabilités pour chaque tâche d’un processus donné (PMBOK, 8e édition, page 194). Option D : un organigramme, également appelé structure de découpage organisationnelle (OBS), est un diagramme qui représente la structure de l’organisation ainsi que les relations et les niveaux hiérarchiques de ses différents postes (PMBOK, 8e édition, pages 171-172).', 'A resource calendar is a calendar for planning, managing, and monitoring resources, including both employees and equipment. It gives project managers an overview of how resources are being utilized, which resources are available, and when (PMBOK 8th Edition, page 132). The Responsibility Assignment Matrix (RAM) describes the involvement of different parties and their roles in completing tasks or deliverables in a project. It''s used to clarify roles and responsibilities within a team, project, or process (PMBOK 8th Edition, pages 131-132). RACI is an acronym for Responsible, Accountable, Consulted, and Informed, and it’s used to assign roles and responsibilities for each task in a given process (PMBOK 8th Edition, page 194). An organigram, also called an organizational chart, organogram, or Organizational Breakdown Structure (OBS), is a diagram that depicts the organization’s structure and the relationships and ranks of its different positions (PMBOK 8th Edition, pages 171-172).', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'resources and Risks', 'Resources and Risks', 'Predictive', 'Predictive', true),
('L3Q114', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Alors que le management de projet traditionnel suit des phases prédéfinies et respecte le périmètre fixé à l’avance, les approches Agile de management de projet :', 'While traditional project management follows predefined phases and sticks to the predetermined scope, Agile project management approaches:', '["Regroupent l’analyse, la conception, la mise en œuvre et les essais au sein d’une itération.", "Impliquent de documenter, d’estimer et de séquencer en détail chaque activité planifiée.", "Utilisent des diagrammes de Gantt ainsi que des activités, responsabilités et calendriers clairement définis.", "Transposent l’iteration backlog dans une structure de découpage du projet (WBS)."]'::jsonb, '["Encapsulate analysis, design, implementation, and testing within an iteration.", "Involve documenting, estimating, and sequencing each planned activity in detail.", "Use Gantt charts along with well-defined activities, responsibilities, and time frames.", "Map the iteration backlog into a Work Breakdown Structure (WBS)."]'::jsonb, '[0]'::jsonb, 'La méthode itérative est au cœur du processus de développement Agile. Chaque itération génère une partie du produit jusqu’à ce que le produit final soit entièrement achevé et livré. Le déroulement type d’une itération comprend : Analyse : définir les exigences de l’itération à partir du Product Backlog, du sprint backlog et du feedback des clients et des parties prenantes. Développement : réaliser la conception et la mise en œuvre sur la base des exigences définies. Essais : réaliser les essais d’assurance qualité. Livraison : intégrer l’incrément fonctionnel en production. Feedback : recueillir le feedback des clients et des parties prenantes afin de définir les exigences de l’itération suivante.', 'The iterative method is the heart of the Agile development process. Each iteration generates a piece of the product until the final product is fully completed and delivered. A typical iteration process flow involves: Analysis: to define the iteration requirements based on the product backlog, sprint backlog, and feedback from customers and stakeholders. Development: includes design and implementation based on the defined requirements. Testing: involves Quality Assurance testing. Delivery: integrating the working iteration into production, Feedback: receiving customer and stakeholder feedback to define the requirements of the next iteration.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Scope', 'Scope', 'Agile', 'Agile', true),
('L3Q115', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Quelle affirmation décrit correctement la classe et la qualité d’un produit ou service livré ?', 'Which statement correctly describes grade and quality for a delivered product or service?', '["Une faible qualité est acceptable, mais une classe inférieure ne l’est pas.", "Une classe inférieure est acceptable, mais une faible qualité ne l’est pas.", "Une classe inférieure et une faible qualité sont toutes deux inacceptables.", "La qualité et la classe sont identiques."]'::jsonb, '["Low quality is acceptable, but a low grade is not", "A low grade is acceptable, but a low quality is not", "Low grade and low quality are both unacceptable", "Quality and grade are the same"]'::jsonb, '[1]'::jsonb, 'La classe désigne une catégorie ou un rang attribué à des entités ayant le même usage fonctionnel, mais des caractéristiques techniques différentes. Un produit peut être de classe supérieure ou de classe inférieure. Un produit de classe inférieure est parfaitement acceptable dès lors qu’il satisfait aux exigences. Options A et C : un produit de faible qualité constitue toujours un problème et n’est jamais acceptable. Tout élément produit doit être de qualité élevée, quelle que soit sa classe ; personne ne souhaite un produit de faible qualité. Exemple : vous achetez un téléphone portable de modèle basique, donc de classe inférieure, dépourvu de fonctionnalités avancées, mais qui fonctionne correctement. Il s’agit donc d’un produit de haute qualité. Bien qu’il soit de classe inférieure, il vous donne satisfaction.', 'Grade refers to a category or rank given to entities having the same functional use but different technical characteristics. A product can be of a high-grade (high-end) or low-grade (low-end). A low-grade product is perfectly acceptable, as long as it fulfills requirements. Option A & C: A low-quality product is always a problem and is never acceptable. Every produced item must have high quality regardless of its grade; no one wants a low-quality product. Example: You buy a basic model (low-grade) cell phone with no advanced features, but it works well. Thus, we’re talking about a high-quality product. Although it is low-grade, it keeps you satisfied.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Scope', 'Scope', 'Hybrid', 'Hybrid', true),
('L3Q116', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Quel type de radiateur d’information indique la quantité de travail restante dans un sprint ?', 'Which type of information radiator shows the amount of remaining work in a sprint? Velocity chart', '["Graphique de vélocité", "Burndown chart", "Diagramme de flux cumulatif", "Burnup chart"]'::jsonb, '["Velocity chart", "Burndown chart", "Cumulative flow diagram", "Burnup chart"]'::jsonb, '[1]'::jsonb, 'Option A : le graphique de vélocité suit le rythme auquel les livrables sont produits, validés et acceptés au cours d’un intervalle prédéfini. Option B : un burndown chart représente visuellement les story points restants ou la réduction de l’exposition au risque au fil du temps (PMBOK, 8e édition, page 150). Option C : un diagramme de flux cumulatif indique les fonctionnalités achevées au fil du temps, celles qui se trouvent dans d’autres états de développement et celles qui figurent dans le backlog (PMBOK, 8e édition, page 267). Option D : un burnup chart permet de suivre le travail réellement achevé par rapport au travail total prévu (PMBOK, 8e édition, page 150).', 'Velocity chart tracks the rate at which the deliverables are produced, validated, and accepted within a predefined interval. A burndown chart visually represents the remaining story points or the reduction in risk exposure over time (PMBOK 8th Edition, page 150). A Cumulative flow diagram is a chart indicating features completed over time, features in other states of development, and those in the backlog (PMBOK 8th Edition, page 267). A burnup chart can track the actual work completed in relation to the total work expected to be done (PMBOK 8th Edition, page 150).', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Schedule', 'Schedule', 'Agile', 'Agile', true),
('L3Q117', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Après une séance de brainstorming, quelle technique est utilisée pour organiser et classer les idées élaborées en groupes ?', 'After a brainstorming session, what technique is used to organize and categorize the elaborated ideas into groups? SWOT analysis', '["Analyse SWOT", "Mind mapping", "Diagramme d’affinité", "Diagramme en arêtes de poisson"]'::jsonb, '["SWOT analysis", "Mind mapping", "Affinity diagram", "Fishbone diagram"]'::jsonb, '[2]'::jsonb, 'Option A : l’analyse SWOT — forces, faiblesses, opportunités et menaces — est un outil de planification stratégique utilisé pour identifier et évaluer les facteurs internes et externes susceptibles d’affecter un projet ou une entreprise. Elle ne sert pas à organiser ou à classer les idées issues d’une séance de brainstorming, mais à analyser des aspects précis d’une situation (PMBOK, 8e édition, page 204). Option B : le mind mapping est une technique utilisée pour organiser visuellement des informations autour d’un concept central, souvent au moyen d’une structure hiérarchique ou ramifiée. Bien qu’il puisse servir à explorer des idées, il n’est pas spécialement conçu pour les classer et les regrouper par thèmes connexes, contrairement au diagramme d’affinité (PMBOK, 8e édition, page 181). Option C : un diagramme d’affinité est un outil utilisé pour organiser et classer les idées ou informations générées lors d’une séance de brainstorming en groupes ou thèmes connexes. Il aide à structurer un grand volume de données en regroupant les idées similaires, ce qui facilite l’identification des tendances et des relations. Cette technique est particulièrement utile pour traiter des problèmes complexes ou lorsqu’une séance de brainstorming produit de nombreuses idées qui doivent être triées et priorisées (Business Analysis for Practitioners, page 105). Option D : un diagramme en arêtes de poisson, également appelé diagramme causes-effets ou diagramme d’Ishikawa, sert à identifier les causes racines d’un problème. Il classe les causes potentielles des problèmes de manière structurée, mais n’a pas pour fonction principale d’organiser en groupes les idées produites lors d’une séance de brainstorming (PMBOK, 8e édition, page 150).', 'SWOT Analysis (Strengths, Weaknesses, Opportunities, and Threats) is a strategic planning tool used to identify and evaluate the internal and external factors that can affect a project or business. It’s not used for organizing or categorizing ideas from a brainstorming session, but rather for analyzing specific aspects of a situation (PMBOK 8th Edition, page 204). Mind Mapping is a technique used to visually organize information around a central concept, often involving a hierarchical or branching structure. While it can be used to explore ideas, it is not specifically designed for categorizing and grouping them into related themes, which is what an Affinity Diagram does (PMBOK 8th Edition, page 181). An Affinity Diagram is a tool used to organize and categorize ideas or information generated during a brainstorming session into related groups or themes. It helps to bring order to a large volume of data by grouping similar ideas together, making it easier to see patterns and relationships. This technique is especially useful when dealing with complex issues or when the brainstorming session produces a lot of ideas that need to be sorted and prioritized (Business analysis for practitioners, page 105). A Fishbone Diagram, also known as a Cause-and-Effect Diagram or Ishikawa Diagram, is used to identify the root causes of a problem. It categorizes potential causes of problems in a structured manner but is not primarily intended for organizing ideas generated in a brainstorming session into groups (PMBOK 8th Edition, page 150).', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Hybrid', 'Hybrid', true),
('L3Q118', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'À mi-parcours de l’itération, le chef de projet constate que certaines user stories subissent des retards inattendus. Tout en identifiant les obstacles potentiels, le chef de projet aide son équipe à ______________ le travail en cours (WIP).', 'Halfway through the iteration, the project manager realizes that some user stories are unexpectedly delayed. Along with identifying any potential impediments, the project manager works on helping their team ______________ Work In Progress (WIP).', '["Augmenter", "Limiter", "Compresser", "Ignorer"]'::jsonb, '["Increase", "Limit", "Compress", "Skip"]'::jsonb, '[1]'::jsonb, 'Pour améliorer sa productivité et son efficacité, une équipe Agile doit limiter le travail en cours (WIP). La limitation du travail en cours est une technique qui permet de remédier aux retards inattendus ou imprévus (Agile Practice Guide, page 59).', 'To improve productivity and efficiency, an agile team needs to limit Work In Progress (WIP). Limiting work in progress is a technique to troubleshoot unexpected or unforeseen delays (Agile Practice Guide, page 59).', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Schedule', 'Schedule', 'Agile', 'Agile', true),
('L3Q119', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un Scrum Master participe aux différents événements Scrum ou les facilite, notamment le sprint, la planification du sprint, le daily standup, la revue de sprint et la rétrospective du sprint. Laquelle des options suivantes décrit la réunion de rétrospective du sprint ?', 'A Scrum Master attends or facilitates the different Scrum events including the Sprint, Sprint planning, Daily standup, Sprint review, and Sprint retrospective. Which of the following options describes the sprint retrospective meeting?', '["Une réunion destinée à affiner les éléments du Product Backlog.", "Une réunion destinée à discuter des aspects négatifs et positifs d’un sprint ainsi que des améliorations possibles.", "Une réunion destinée à définir et à évaluer le travail du sprint suivant.", "Une réunion tenue à la fin du dernier sprint du projet."]'::jsonb, '["A meeting for refining product backlog items.", "A meeting for discussing the negative and positive aspects of a sprint as well as any possible improvements.", "A meeting for defining and evaluating the work of the next sprint.", "A meeting held at the end of the project’s last sprint."]'::jsonb, '[1]'::jsonb, 'Au cours de la réunion de rétrospective du sprint, tous les aspects positifs et négatifs du sprint sont examinés. La réunion de rétrospective est considérée comme une réunion d’amélioration, car elle vise principalement à trouver les moyens appropriés d’identifier les écueils potentiels et les erreurs passées, ainsi qu’à rechercher de nouvelles façons d’éviter ces erreurs. Cette réunion n’est pas tenue à la fin du dernier sprint du projet ; elle a lieu de manière récurrente après la revue de sprint et avant la planification du sprint suivant (PMBOK, 8e édition, page 194). Option A : une réunion de backlog refinement sert à affiner les éléments du Product Backlog. Option C : la réunion de planification du sprint sert à définir et à évaluer le travail du sprint suivant.', 'During the sprint retrospective meeting, all the good and bad aspects of the sprint are discussed. The retrospective meeting is considered a meeting for improvements, as it is mainly held to find the proper ways and means of identifying potential pitfalls and past errors, and to seek out new ways to avoid those mistakes. This meeting isn''t held at the end of the project’s last sprint; it recurrently takes place after the Sprint Review and before the following Sprint Planning (PMBOK 8th Edition, page 194). Option A: A backlog refinement meeting is used to refine product backlog items. Option C: The sprint planning meeting is used to define and evaluate the work of the next sprint.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'resources and Risks', 'Resources and Risks', 'Agile', 'Agile', true),
('L3Q120', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'multiple', 'Une organisation effectue une transition progressive de l’approche prédictive vers l’approche adaptative. Que peut faire le chef de projet pour préparer son équipe à cette transition ? (Choisissez deux réponses.)', 'An organization is making a progressive transition from the predictive to the adaptive approach. What can the project manager do to prepare their team for the transition? (Select two)', '["Former l’équipe aux valeurs et pratiques Agile.", "Appliquer la philosophie « apprendre par la pratique » en passant immédiatement aux approches Agile.", "Planifier une transition progressive en introduisant quelques techniques itératives ou incrémentales dans le projet actuel.", "Proposer une transition complète, car les pratiques Agile ne peuvent pas être combinées avec les pratiques prédictives."]'::jsonb, '["Provide training for the team on agile values and practices.", "Apply the “learning-by-doing” philosophy by immediately switching to agile approaches.", "Plan a gradual transition by introducing a few iterative or incremental techniques to their current project.", "Suggest a full transition since agile practices cannot be combined with predictive ones."]'::jsonb, '[0, 2]'::jsonb, 'Le chef de projet devrait dispenser à son équipe une formation pertinente afin de lui permettre d’adopter les nouvelles pratiques Agile avec davantage de confiance. Il devrait également introduire progressivement certaines techniques itératives ou incrémentales afin de fluidifier la transition. Cela améliorera le processus d’apprentissage de l’équipe et accélérera la livraison de valeur aux sponsors. De nombreuses équipes ne peuvent pas passer immédiatement et complètement à l’approche Agile. Il est préférable, et même recommandé, d’effectuer une transition progressive en combinant des pratiques adaptatives et prédictives, ce que l’on appelle une approche hybride (Agile Practice Guide, page 30).', 'The project manager should provide their team with relevant training in order to enable them to adopt the new agile practices with more confidence. They should also gradually introduce certain iterative or incremental techniques to make the transition smoother. This will improve the team learning process and accelerate delivering value to sponsors. Many teams can’t make a full immediate switch to the agile approach. It is preferable and even recommended to make a gradual transition by combining adaptive and predictive practices, which is known as a hybrid approach (Agile Practice Guide, page 30).', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'resources and Risks', 'Resources and Risks', 'Hybrid', 'Hybrid', true),
('L3Q121', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Laquelle des entités suivantes est chargée d’établir des processus normalisés de gouvernance des projets dans l’ensemble d’une organisation en définissant des cadres et des modèles de management de projet ?', 'Which of the following entities is responsible for establishing standardized project governance processes across an organization by defining project management frameworks and templates?', '["Bureau de management de projet", "Bureau de livraison de valeur", "Comité de pilotage", "Unité de test"]'::jsonb, '["Project management office", "Value delivery office", "Steering committee", "Testing unit"]'::jsonb, '[0]'::jsonb, 'Le bureau de management de projet (PMO) est une structure de management qui normalise les processus de gouvernance des projets et favorise le partage des ressources, des méthodologies, des outils et des techniques. Option B : le bureau de livraison de valeur veille principalement à ce que les projets fournissent de la valeur à l’organisation. Il n’est pas chargé d’établir des cadres et des modèles normalisés de management de projet. Option C : un comité de pilotage fournit une orientation stratégique et assure la supervision des projets et des programmes (PMBOK, 8e édition, page 274). Il définit les priorités et approuve les décisions importantes, mais il ne crée ni ne définit les processus ou modèles normalisés de management de projet. Option D : l’unité de test est chargée de tester les produits ou systèmes afin de s’assurer qu’ils respectent les normes de qualité. Elle se concentre sur l’assurance qualité plutôt que sur la définition de cadres et de modèles de management de projet.', 'The Project Management Office (PMO) is a management structure that standardizes project governance processes and promotes the sharing of resources, methodologies, tools, and techniques. The value delivery office focuses on ensuring that projects deliver value to the organization. It is not responsible for establishing standardized project management frameworks and templates. A steering committee provides strategic direction and oversight for projects and programs (PMBOK 8th Edition, page 274). It sets priorities and approves significant decisions, but it does not create or define standardized project management processes or templates. The testing unit is responsible for testing products or systems to ensure they meet quality standards. Its focus is on quality assurance rather than defining project management frameworks and templates.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Gouvernance', 'Gouvernance', 'Hybrid', 'Hybrid', true),
('L3Q122', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Qu’implique le leadership serviteur ?', 'What does servant leadership imply?', '["Une personne chargée de diriger et de guider l’équipe", "La réalisation du travail par itérations, avec un leader prééminent", "La désignation d’un chef d’équipe, tandis que les membres de l’équipe jouent le rôle de suiveurs", "La compréhension et la prise en compte des besoins des membres de l’équipe"]'::jsonb, '["One individual in charge of directing and guiding the team", "Carrying out work through iterations, with one prominent leader", "Naming a team leader, while team members serve as followers", "Understanding and addressing the needs of team members"]'::jsonb, '[3]'::jsonb, 'Le leadership serviteur consiste à diriger l’équipe en s’attachant à comprendre et à satisfaire les besoins de ses membres afin d’obtenir la meilleure performance possible (PMBOK, 8e édition, page 197).', 'Servant leadership implies leading your team by focusing on understanding and addressing their needs to yield the best performance possible (PMBOK 8th edition, page 197).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Agile', 'Agile', true),
('L3Q123', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet a créé la liste hiérarchique de haut niveau suivante des ressources humaines et physiques d’un projet consistant à créer une plateforme d’envoi groupé de SMS pour des campagnes marketing. Que représente cette illustration visuelle ?', 'A project manager created the following high-level hierarchical list of human and physical resources of a project that consists in creating a bulk SMS platform for marketing campaigns. What does this visual illustration represent? Resource calendar', '["Calendrier des ressources", "Structure de découpage organisationnelle (OBS)", "Structure de découpage des ressources (RBS)", "Matrice RACI"]'::jsonb, '["Resource calendar", "Organization breakdown structure", "Resource breakdown structure", "RACI chart"]'::jsonb, '[2]'::jsonb, 'Option A : un calendrier des ressources est un calendrier servant à planifier, manager et suivre les ressources (PMBOK, 8e édition, page 132). Option B : la structure de découpage organisationnelle (OBS), également appelée organigramme, sert à représenter l’organisation du projet (PMBOK, 8e édition, pages 171-172). Option C : une structure de découpage des ressources est une représentation hiérarchique des ressources par catégorie et par type. Les catégories de ressources comprennent notamment la main-d’œuvre, les matériaux, les équipements et les fournitures. Les types de ressources peuvent inclure le niveau de compétence, la classification, les certifications requises ou toute autre information appropriée au projet (PMBOK, 8e édition, page 132). Option D : RACI est l’acronyme de Responsible, Accountable, Consulted et Informed. Cette matrice sert à attribuer les rôles et responsabilités des personnes impliquées dans un projet ou un processus (PMBOK, 8e édition, pages 194-195).', 'A resource calendar is a calendar for planning, managing, and monitoring resources (PMBOK 8th edition, page 132). Organizational Breakdown Structure (OBS), also known as Organization Chart, is used for representing the project organization (PMBOK 8th edition, pages 171-172). A resource breakdown structure is a hierarchical representation of resources by category and type. Examples of resource categories include but are not limited to labor, materials, equipment, and supplies. Resource types may include the skill level, grade level, required certifications, or other information as appropriate to the project (PMBOK 8th edition, page 132). RACI is an acronym for Responsible Accountable Consult and Inform and it’s used to assign the roles and responsibilities of the individuals involved in a project or a process (PMBOK 8th edition, pages 194-195).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Predictive', 'Predictive', true),
('L3Q124', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Quel outil est utilisé pour identifier les écarts de compétences au sein de l’équipe projet ?', 'Which tool is used to identify skill gaps in the project team? Post-training assessment', '["Évaluation post-formation", "Matrice des compétences", "Évaluation de la performance de l’équipe", "Affectation selon la performance de l’équipe"]'::jsonb, '["Post-training assessment", "Skill matrix", "Team performance assessment", "Team performance assignment"]'::jsonb, '[1]'::jsonb, 'Option A : l’évaluation post-formation mesure l’efficacité de la formation après son achèvement, plutôt que d’identifier les écarts initiaux. Option B : une matrice des compétences sert à comparer les compétences requises pour le projet aux compétences réellement disponibles au sein de l’équipe. Option C : l’évaluation de la performance de l’équipe sert à évaluer l’efficacité globale de l’équipe après des activités de développement, telles qu’une formation ou une activité de cohésion d’équipe. Option D : l’affectation selon la performance de l’équipe consiste à attribuer les tâches et responsabilités en fonction des compétences et des rôles existants afin d’assurer une exécution efficace.', 'Post-training assessment measures the effectiveness of training after it is completed, rather than identifying initial gaps. A skill matrix is used to compare the required skills for the project with the actual skills available within the team. Team performance assessment is used to evaluate the team’s overall effectiveness after development activities (e.g., training or team building). Team performance assignment refers to allocating tasks and responsibilities based on existing skills and roles to ensure efficient execution.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Hybrid', 'Hybrid', true),
('L3Q125', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Laquelle des réunions Scrum suivantes est centrée sur le produit ?', 'Which of the following Scrum meetings is product-centered?', '["Daily standup", "Planification du sprint", "Revue de sprint", "Rétrospective du sprint"]'::jsonb, '["Daily standup", "Sprint planning", "Sprint review", "Sprint retrospective"]'::jsonb, '[2]'::jsonb, 'La revue de sprint est une réunion centrée sur le produit au cours de laquelle l’équipe Agile présente les fonctionnalités qu’elle a achevées pendant le sprint afin d’obtenir le feedback et l’approbation du Product Owner (PMBOK, 8e édition, page 199).', 'The Sprint Review is a product-centered meeting, during which the agile team demonstrates the functionalities they have completed during the sprint, seeking the Product Owner''s feedback and approval (PMBOK 8th edition, page 199).', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Scope', 'Scope', 'Agile', 'Agile', true),
('L3Q126', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Après avoir défini les exigences de haut niveau du projet, l’équipe Agile et le Product Owner commencent à dresser une liste des fonctionnalités du produit, accompagnées de brèves descriptions de toutes les fonctionnalités qu’ils vont livrer. Ils vont ensuite prioriser le Product Backlog en fonction de :', 'After defining the project’s high-level requirements, the agile team along with the product owner begins writing down a list of the product features, including short descriptions of all the functionalities they’re going to deliver. Next, they’re going to prioritize the product backlog based on:', '["La valeur des éléments", "La complexité des éléments", "La taille des éléments", "Le risque associé aux éléments"]'::jsonb, '["The value of the items", "The complexity of the items", "The size of the items", "The risk associated with the items"]'::jsonb, '[0]'::jsonb, 'Le Product Backlog doit être priorisé et organisé en fonction de la valeur que chaque élément apporte au produit et au projet. Cette valeur dépend de plusieurs facteurs, tels que la complexité de l’élément, sa criticité et le risque qui lui est associé. Toutefois, ces facteurs ne constituent pas à eux seuls la base permettant de déterminer la valeur des éléments. La valeur de chaque élément est déterminée par le Product Owner, tout comme son ordre dans le Product Backlog.', 'The product backlog should be prioritized and organized based on the value that each item brings to the product and project. This value depends on several factors such as the item’s complexity, criticality, and the risk associated with it. However, these factors are not the basis to determine the items’ value. Each item’s value is dictated by the Product Owner as well as the items’ sequence in the product backlog.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Scope', 'Scope', 'Agile', 'Agile', true),
('L3Q127', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'multiple', 'Un chef de projet a été chargé de diriger un projet de développement d’un site web de réservation de vols. La compagnie aérienne exige que le site puisse prendre en charge mille visiteurs par heure. Cette condition est également appelée : (Choisissez deux réponses.)', 'A project manager was asked to lead a project of flight booking website development. The airline requested that the website should be able to support one thousand visitors per hour. This condition is also known as a(n): (Select two)', '["Exigence", "Périmètre", "Critère d’acceptation", "Livrable"]'::jsonb, '["Requirement", "Scope", "Acceptance criterion", "Deliverable"]'::jsonb, '[0, 2]'::jsonb, 'La condition consistant à prendre en charge mille visiteurs par heure constitue une exigence et un critère d’acceptation du projet. Une exigence est définie comme « une condition ou une capacité qui doit être présente dans un produit, un service ou un résultat afin de satisfaire un besoin business ». Les critères d’acceptation sont les conditions qui doivent être remplies avant que les livrables soient acceptés. Cette condition ne peut pas, à elle seule, être considérée comme un livrable ou comme le périmètre (PMBOK, 8e édition, pages 265 et 272). Option B : le périmètre du projet représente l’ensemble du travail requis pour atteindre les principaux objectifs du projet (PMBOK, 8e édition, page 271). Option D : les livrables désignent les produits ou services quantifiables qui doivent être livrés à la fin du projet, ici le site web de réservation de vols.', 'The condition of supporting one thousand visitors per hour is considered a requirement and an acceptance criterion for the project. A requirement is defined as “a condition or capability that is necessary to be present in a product, service, or result to satisfy a business need.” (PMBOK 8th Edition, page 272). Acceptance criteria are conditions required to be met before deliverables are accepted. This condition cannot be considered a deliverable or scope on its own (PMBOK 8th Edition, page 265). Option B: The project scope represents the overall amount of work required to achieve the project’s main objectives (PMBOK 8th Edition, page 271). Option D: Deliverables refer to quantifiable products or services that must be delivered by the end of the project, i.e., the flight booking website.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Hybrid', 'Hybrid', true),
('L3Q128', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet dirige un projet itératif. Le Product Owner demande une réunion avec l’équipe projet et d’autres parties prenantes importantes afin d’examiner une démonstration du livrable produit. Quand le chef de projet devrait-il organiser cette réunion ?', 'A project manager is leading an iterative project. The product owner calls for a meeting with the project team and other prominent stakeholders to review a demonstration of the produced deliverable. When should the project manager organize this meeting?', '["Au début de chaque itération", "À la fin de chaque itération", "À la fin du projet", "Au démarrage du projet"]'::jsonb, '["At the beginning of every iteration", "At the end of every iteration", "At the end of the project", "At the start of the project"]'::jsonb, '[1]'::jsonb, 'Les réunions de revue d’itération ont lieu à la fin de chaque itération afin de permettre à l’équipe projet d’obtenir régulièrement le feedback du Product Owner et des parties prenantes concernées.', 'Iteration review meetings take place at the end of each iteration to allow the project team to obtain feedback from the product owner and concerned stakeholders on a regular basis.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Scope', 'Scope', 'Agile', 'Agile', true),
('L3Q129', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'L’un des membres clés de l’équipe projet quitte le projet pour des raisons personnelles. Le chef de projet n’avait pas prévu un tel scénario, mais il est parvenu à trouver un remplaçant avec l’aide d’une agence de recrutement. Toutefois, il doit lui verser un salaire plus élevé. Cela entraînera des coûts supplémentaires qui relèvent de :', 'One of the project team’s key members leaves the project for personal reasons. The project manager did not plan for such a scenario but they managed to get a replacement with the help of a staffing agency. However, they have to pay them a higher salary. This will result in extra costs which fall under the project’s:', '["La réserve pour aléas", "Le coût", "La réserve de management", "Le budget"]'::jsonb, '["Contingency reserve", "Cost", "Management reserve", "Budget"]'::jsonb, '[2]'::jsonb, 'La réserve de management correspond à une réserve budgétaire ou temporelle dédiée au traitement des risques non identifiés, ou inconnues inconnues (inconnu = non identifié ; inconnues = risques) (PMBOK, 8e édition, page 269). Cette réserve n’est pas un budget calculé et ne fait pas partie de la référence de base des coûts. Par conséquent, chaque fois qu’un risque inconnu se produit, le chef de projet doit obtenir une autorisation pour utiliser cette réserve. Option A : une réserve pour aléas est utilisée pour les risques identifiés assortis de stratégies de réponse prédéterminées, également appelés inconnues connues (connu = identifié ; inconnues = risques) (PMBOK, 8e édition, page 266).', 'Management reserve involves the dedicated budget or time reserve for handling unidentified risks or unknown unknowns (unknown = unidentified, unknowns = risks) (PMBOK 8th edition, page 269). This type of reserve is not a calculated budget and does not take part in the cost baseline. Therefore, anytime an unknown risk occurs, the project manager will need permission to use this reserve. Option A: A contingency reserve is used for identified risks with predetermined risk response strategies, aka known-unknowns (known = identified, Unknowns = risks) (PMBOK 8th edition, page 266).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Finance', 'Finance', 'Predictive', 'Predictive', true),
('L3Q130', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Laquelle des options suivantes constitue un cycle de vie du projet ?', 'Which of the following is considered a project life cycle?', '["Initialisation, planification, exécution, suivi et maîtrise, et clôture", "Maquettage fonctionnel, prototypage, conception, développement, essais et déploiement", "Développement, introduction, croissance, maturité et déclin", "Formation, turbulence, normalisation, performance et dissolution"]'::jsonb, '["Initiation, planning, executing, monitoring and controlling, and closing.", "Wireframing, prototyping, designing, developing, testing, and deploying.", "Development, introduction, growth, maturity, and decline.", "Forming, storming, norming, performing, and adjourning."]'::jsonb, '[1]'::jsonb, 'Le cycle de vie du projet pouvant être adopté pour un projet de développement d’application mobile est le suivant : maquettage fonctionnel, prototypage, conception, développement, essais et déploiement. Un cycle de vie du projet comprend les différentes phases de développement qu’un projet traverse de son démarrage à son achèvement. Option A : l’initialisation, la planification, l’exécution, le suivi et la maîtrise, et la clôture sont des domaines d’intervention plutôt que des phases du cycle de vie du projet. Option C : le développement, l’introduction, la croissance, la maturité et le déclin sont les étapes typiques que traverse un produit, de sa création à son retrait du marché. Option D : la formation, la turbulence, la normalisation, la performance et la dissolution sont les phases de développement d’une équipe selon la théorie de Tuckman (PMBOK, 8e édition, page 211).', 'The project life cycle that can be adopted for developing a mobile app project is: Wireframing, prototyping, designing, developing, testing, and deploying. A project life cycle comprises the different development phases that a project goes through from its start to its completion. Option A: Initiation, planning, executing, monitoring and controlling, and closing are focus areas rather than project lifecycle phases. Option C: Development, introduction, growth, maturity, and decline are the typical stages a product goes through from creation to withdrawal from the market. Option D: Forming, storming, norming, performing, and adjourning are team development phases according to Tuckman’s theory (PMBOK 8th edition, page 211).', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Gouvernance', 'Gouvernance', 'Predictive', 'Predictive', true),
('L3Q131', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Placez les composantes suivantes du budget du projet à la bonne position dans la figure ci-dessous : budget initial, référence de base des coûts, réserve pour aléas et réserve de management.', 'Place the following project budget components in the right position in the figure below: Initial Budget, Cost Baseline, Contingency Reserve, and Management Reserve.', '["A = Réserve de management, B = Budget initial, C = Réserve pour aléas, D = Référence de base des coûts", "A = Réserve de management, B = Référence de base des coûts, C = Budget initial, D = Réserve pour aléas", "A = Réserve pour aléas, B = Réserve de management, C = Référence de base des coûts, D = Budget initial", "A = Référence de base des coûts, B = Budget initial, C = Réserve de management, D = Réserve pour aléas"]'::jsonb, '["A = Management Reserve, B = Initial Budget, C = Contingency Reserve, D = Cost Baseline", "A = Management reserve, B = Cost Baseline, C = Initial Budget, D = Contingency Reserve", "A = Contingency reserve, B = Management Reserve, C = Cost Baseline, D = Initial Budget", "A = Cost Baseline, B = Initial Budget, C = Management Reserve, D = Contingency Reserve"]'::jsonb, '[0]'::jsonb, 'A = Réserve de management, B = Budget initial, C = Réserve pour aléas et D = Référence de base des coûts. Le montant total du projet est composé de la réserve de management et du budget initial, lequel est à son tour composé de la référence de base des coûts et de la réserve pour aléas.', 'A = Management reserve, B = Initial Budget, C = Contingency reserve, and D = Cost baseline. The project total amount is composed of the Management Reserve and the Initial Budget, which in turn is composed of the Cost Baseline and Contingency Reserve.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Finance', 'Finance', 'Predictive', 'Predictive', true),
('L3Q132', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Afin de gérer des niveaux élevés de changement et d’assurer la participation active de toutes les parties intéressées, un chef de projet adopte une approche de développement du projet pilotée par le changement, également appelée :', 'In order to handle high levels of change and ensure the active participation of all interested parties, a project manager adopts a change-driven project development approach, which is also known as:', '["Approche adaptative", "Approche prédictive", "Approche en cascade", "Approche hybride"]'::jsonb, '["Adaptive approach", "Predictive approach", "Waterfall approach", "Hybrid approach"]'::jsonb, '[0]'::jsonb, 'Une approche pilotée par le changement est également appelée approche adaptative, Agile, flexible ou axée sur le changement. Cette approche de développement se caractérise par la capacité à réagir et à s’adapter à des niveaux élevés de changement, ainsi que par l’implication et la participation constantes des différentes parties (PMBOK, 8e édition, page 63). Option C : une approche en cascade ou prédictive est séquentielle et rigide (PMBOK, 8e édition, page 61). Option D : l’approche hybride combine les approches prédictive et adaptative (PMBOK, 8e édition, page 65).', 'A change-driven approach is also referred to as an adaptive, Agile, flexible, or change-focused approach. This development approach is characterized by the ability to react and adapt to high levels of change as well as the constant involvement and participation of different parties (PMBOK 8th edition, page 63). Option C: A waterfall or predictive approach is sequential and rigid (PMBOK 8th edition, page 61). Option D: Hybrid is a combination of predictive and adaptive approaches (PMBOK 8th edition, page 65).', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Gouvernance', 'Gouvernance', 'Agile', 'Agile', true),
('L3Q133', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un business analyst évalue les besoins business d’un projet donné. Quel outil ou quelle technique consiste à mener une étude évaluant différents facteurs susceptibles de conduire à des recommandations utiles ?', 'A business analyst is assessing the business needs for a certain project. Which tool or technique involves conducting a study in which it evaluates different factors that could lead to valuable recommendations?', '["Analyse de faisabilité", "Analyse SWOT", "Évaluation des risques", "Analyse coûts-bénéfices"]'::jsonb, '["Feasibility analysis", "SWOT analysis", "Risk assessment", "Cost-Benefit Analysis"]'::jsonb, '[0]'::jsonb, 'L’analyse de faisabilité consiste à évaluer différents facteurs afin d’apprécier la viabilité des diverses options envisagées (PMI Guide to Business Analysis, page 86). Option D : une analyse coûts-bénéfices évalue le rendement financier de la mise en œuvre de la solution en comparant les bénéfices attendus aux coûts. Elle constitue un moyen efficace d’évaluer la valeur business d’une solution.', 'Feasibility analysis involves assessing various factors to evaluate the viability of different options being considered (PMI Guide to Business Analysis, page 86). Option D: A cost-benefit analysis evaluates the financial return of implementing the solution by comparing the expected benefits against the costs. It''s an effective way to assess the business value of a solution.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Gouvernance', 'Gouvernance', 'Hybrid', 'Hybrid', true),
('L3Q134', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Travaillant dans un environnement prédictif, un chef de projet a décidé d’utiliser une estimation à trois points avec une distribution bêta afin d’estimer le coût des activités du projet. Laquelle des formules suivantes devrait-il utiliser ?', 'Working in a predictive environment, a project manager has decided to use a three-point estimation with a beta distribution to measure the cost of project activities. Which of the following formulas should the project manager use?', '["(Optimiste + Pessimiste + Plus probable) ÷ 3", "(Optimiste + Pessimiste + (2 × Plus probable)) ÷ 4", "(Optimiste + Pessimiste + (3 × Plus probable)) ÷ 5", "(Optimiste + Pessimiste + (4 × Plus probable)) ÷ 6"]'::jsonb, '["(Optimistic + Pessimistic + Most likely) ÷ 3", "(Optimistic + Pessimistic + (2 × Most likely)) ÷ 4", "(Optimistic + Pessimistic + (3 × Most likely)) ÷ 5", "(Optimistic + Pessimistic + (4 × Most likely)) ÷ 6"]'::jsonb, '[3]'::jsonb, 'La formule d’estimation à trois points utilisant une distribution bêta, ou moyenne pondérée, est la suivante : (Optimiste + Pessimiste + (4 × Plus probable)) ÷ 6. Option A : la formule d’estimation à trois points utilisant une distribution triangulaire, ou moyenne simple, est la suivante : (Optimiste + Pessimiste + Plus probable) ÷ 3 (PMBOK, 8e édition, page 183).', 'The three-point estimation formula using a beta (weighted average) distribution is as follows: (Optimistic + Pessimistic + (4 × Most likely)) ÷ 6. Option A: The three-point estimation formula uses a triangular distribution (simple average) as follows: (Optimistic + Pessimistic + Most likely) ÷ 3 (PMBOK 8th Edition, page 183).', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Finance', 'Finance', 'Predictive', 'Predictive', true),
('L3Q135', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Laquelle des options suivantes n’est pas considérée comme une technique d’élicitation ?', 'Which of the following is not considered an elicitation technique?', '["Brainstorming", "Analyse documentaire", "Observation", "Entretiens", "Cas d’utilisation"]'::jsonb, '["Brainstorming", "Document analysis", "Observation", "Interviews", "Use case"]'::jsonb, '[4]'::jsonb, 'Un cas d’utilisation est un outil et une technique servant à définir et à élaborer les exigences, et non à conduire le processus d’élicitation. Toutes les autres options sont des outils et techniques servant à mener ce processus (PMI Guide to Business Analysis, page 164).', 'A use case is a tool and technique used to define and elaborate requirements, not to conduct the elicitation process. All the other options are tools and techniques for conducting the elicitation process (PMI Guide to Business Analysis, page 164).', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Hybrid', 'Hybrid', true),
('L3Q136', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Afin de suivre l’avancement du projet, le chef de projet définit des jalons dans l’échéancier du projet. Quelle est la durée habituelle d’un jalon ?', 'In order to track the project''s progress, the project manager sets milestones in the project schedule. What is the typical duration of a milestone?', '["La moitié de la durée du projet", "La même durée que le cycle de vie du projet", "Zéro", "Un mois"]'::jsonb, '["Half of the project duration", "The same duration as the project life cycle", "Zero", "One month"]'::jsonb, '[2]'::jsonb, 'La durée d’un jalon est nulle, car il représente une réalisation, un point ou un événement important du projet, comme l’achèvement d’un livrable particulier (PMI, Process Groups: A Practice Guide, page 213).', 'The duration of a milestone is zero because it denotes a significant achievement, point, or event in a project, such as the completion of a particular deliverable for instance (PMI - Process groups guide, page 213).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Schedule', 'Schedule', 'Predictive', 'Predictive', true),
('L3Q137', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Afin de recueillir le feedback des utilisateurs finaux, un chef de projet senior chargé d’un projet de progiciel de gestion intégré (ERP) discute de plusieurs idées avec l’équipe projet, puis ils dessinent le diagramme suivant. Quel outil utilisent-ils ?', 'In order to gather end-user feedback, a senior project manager of an Enterprise Resource Planning (ERP) project discusses several ideas with the project team and then they draw the following diagram. What tool are they using?', '["Mind map", "Diagramme d’affinité", "Arbre de décision", "Représentation des données"]'::jsonb, '["Mind map", "Affinity diagram", "Decision tree", "Data representation"]'::jsonb, '[0]'::jsonb, 'Le chef de projet et son équipe ont utilisé la technique du mind mapping. Dans une mind map, plusieurs options sont discutées, puis organisées visuellement. Option B : ce diagramme n’est pas un diagramme d’affinité, car il ne classe pas un grand nombre d’idées en groupes (PMBOK, 8e édition, page 145). Option C : le diagramme illustré n’est pas un arbre de décision, car il ne présente pas les différentes solutions possibles pour recueillir le feedback des utilisateurs finaux et n’aide pas l’équipe à choisir la meilleure d’entre elles (PMBOK, 8e édition, page 163). Option D : une mind map, un diagramme d’affinité et un arbre de décision sont tous des méthodes de représentation des données, ce qui rend l’option D, « Représentation des données », trop générique pour être considérée comme la réponse correcte.', 'The project manager and their team used the mind mapping technique. In a mind map, several options are discussed and then visually organized. This diagram is not an affinity diagram, as it does not classify a large number of ideas into groups (PMBOK 8th Edition, page 145). The illustrated diagram is not a decision tree because it doesn’t display or help the team choose the best decision among the different alternatives for gathering end-user feedback (PMBOK 8th Edition, page 163). A Mind map, Affinity diagram, and Decision tree are all data representation methods, which makes option D “Data representation” too generic to be considered the Correct Answer.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Hybrid', 'Hybrid', true),
('L3Q138', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Dans Scrum, qui devrait prioriser les éléments du sprint backlog ?', 'In Scrum, who should prioritize items in the sprint backlog?', '["Le Scrum Master", "Le Product Owner", "L’équipe de développement", "L’ensemble de l’équipe Scrum"]'::jsonb, '["The Scrum Master", "The Product Owner", "The development team", "The entire Scrum team"]'::jsonb, '[2]'::jsonb, 'Hormis l’équipe de développement, personne ne devrait décider de l’ordre des stories dans le sprint backlog. Les membres de l’équipe devraient définir eux-mêmes leur travail au niveau des tâches, puis s’auto-organiser de la manière qu’ils jugent la plus appropriée pour atteindre l’objectif du sprint (Essential Scrum, Rubin, Kenneth S., page 23). Le sprint backlog est différent du Product Backlog. Un sprint backlog est l’ensemble des éléments que l’équipe pluridisciplinaire sélectionne dans le Product Backlog pour y travailler au cours du sprint à venir. Le sprint backlog constitue le principal résultat de la planification du sprint.', 'Apart from the development team, nobody should decide the stories’ order in the sprint backlog. Instead, team members should define their own task-level work and then self-organize in any manner they feel best to achieve the sprint goal (Essential Scrum by Rubin, Kenneth S, page 23). The “sprint backlog” is different from the “product backlog”. A sprint backlog is the set of items that the cross-functional team selects from the product backlog to work on during the upcoming sprint. The sprint backlog represents the primary output of sprint planning.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'resources and Risks', 'Resources and Risks', 'Agile', 'Agile', true),
('L3Q139', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet dirige un projet selon une approche de développement adaptative. Comment devrait-il planifier les activités du projet ?', 'A project manager is leading a project using an adaptive development approach. How should the project manager plan the project activities?', '["Planifier le travail de toutes les itérations avant le démarrage du projet", "Élaborer progressivement le périmètre sur la base d’un feedback continu", "Élaborer un plan de haut niveau à mesure que le projet avance", "Exécuter les activités du projet décrites dans l’énoncé des travaux (SOW)"]'::jsonb, '["Plan all of the iterations work before the start of the project.", "Progressively elaborate the scope based on continuous feedback.", "Develop a high-level plan as the project progresses.", "Execute the project activities described in the Statement Of Work (SOW)."]'::jsonb, '[1]'::jsonb, 'Dans une approche adaptative, la planification consiste à élaborer progressivement le périmètre du travail sur la base du feedback continu des parties prenantes. Le projet est divisé en itérations et, à la fin de chacune d’elles, le client examine le travail réalisé sur le produit. Son feedback est ensuite utilisé pour définir le périmètre détaillé de l’itération suivante. Options A et D : définir le travail de toutes les itérations avant le démarrage du projet décrit une approche de développement itérative, tandis que réaliser les activités décrites dans l’énoncé des travaux correspond à une approche de développement prédictive.', 'Planning activities in an adaptive approach entails progressively elaborating the work scope based on the stakeholders’ continuous feedback. The project is split into iterations, and at the end of each iteration, the customer reviews the accomplished work on the product. Then, the customer’s feedback is used to define the detailed scope of the next iteration. Option A & D: Defining all iterations’ work before the start of the project depicts an iterative development approach while implementing activities described in the statement of work depicts a predictive development approach.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'Schedule', 'Schedule', 'Agile', 'Agile', true),
('L3Q140', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Lorsqu’une équipe Agile discutait des choix techniques de son nouveau projet pendant le sprint zéro, un membre senior de l’équipe s’est souvenu d’un projet antérieur similaire qui avait rencontré de grandes difficultés et s’était terminé avec un dépassement budgétaire et un retard sur l’échéancier. Que devrait faire ensuite le chef de projet ?', 'When an agile team was discussing the technical choices of their new project during the zero sprint, a senior team member recalled a similar past project that went through some big challenges and ended up being over budget and behind schedule. What should the project manager do next?', '["Rechercher les détails de performance du projet antérieur mentionné dans les actifs organisationnels.", "Rechercher les détails de performance du projet antérieur mentionné dans les facteurs environnementaux de l’entreprise.", "Rechercher les détails de performance du projet antérieur mentionné dans le registre des problèmes.", "Puisque le projet antérieur mentionné suivait une approche prédictive, ses détails de performance ne sont pas pertinents."]'::jsonb, '["Look for the performance details of the mentioned past project in the Organizational Process Assets (OPAs).", "Look for the performance details of the mentioned past project in the Enterprise Environmental Factors (EEF).", "Look for the performance details of the mentioned past project in the issue log.", "Since the mentioned past project followed a predictive approach, its performance details are irrelevant."]'::jsonb, '[0]'::jsonb, 'Les actifs organisationnels comprennent les processus, les procédures et la base de connaissances de l’entreprise (PMBOK, 8e édition, pages 19-20). Pour comprendre la performance d’un projet antérieur, le chef de projet devrait examiner divers documents, tels que les références de base du périmètre, de l’échéancier, des coûts et de la qualité, les archives administratives, le registre des parties prenantes et le registre des problèmes. Se fier uniquement au registre des problèmes pourrait ne pas révéler toutes les difficultés rencontrées. Option B : contrairement aux actifs organisationnels, les facteurs environnementaux de l’entreprise ne contiennent pas les détails de performance des projets (PMBOK, 8e édition, pages 18-19). Option D : même si le nouveau projet est Agile et que le précédent était prédictif, il est nécessaire d’exploiter les leçons apprises documentées, car les difficultés peuvent ne pas être liées à l’approche du projet.', 'Organizational Process Assets (OPAs) include processes, procedures, and the corporate knowledge base (PMBOK 8th Edition, pages 19-20). To understand a past project''s performance, the project manager should review various documents such as scope, schedule, cost, quality baselines, administrative records, stakeholder register, and issue log. Relying solely on the issue log might not reveal all the challenges faced. Option B: Unlike OPAs, Enterprise Environmental Factors (EEF) do not contain project performance details (PMBOK 8th Edition, pages 18-19). Option D: Even if the new project is agile and the previous one was predictive, leveraging documented lessons learned is necessary, as challenges may not be linked to the project approach.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'resources and Risks', 'Resources and Risks', 'Hybrid', 'Hybrid', true),
('L3Q141', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet a clôturé tous les contrats liés à son projet de construction, sauf celui concernant l’installation de caméras de sécurité. Pour ce dernier contrat, il ne reste plus qu’à faire réaliser une inspection rapide par un expert afin de vérifier la connexion sans fil, la vision nocturne, le stockage dans le cloud, etc. Sachant que les caméras fonctionnent correctement et que le projet doit être clôturé dès que possible, que devrait faire le chef de projet ?', 'A project manager closed all contracts related to their construction project, except one that concerns setting up security cameras. The only thing left for this contract is to go through a quick inspection by an expert in order to check out wireless connection, night vision, cloud storage, etc. Knowing that the security cameras are working fine and that the project needs to be closed as soon as possible, what should the project manager do?', '["Clôturer le contrat et le projet sans inspection", "Clôturer le contrat, mais maintenir le projet ouvert", "Clôturer le projet, mais maintenir le contrat ouvert", "Maintenir le contrat et le projet ouverts"]'::jsonb, '["Close the contract and the project with no inspection", "Close the contract, but keep the project open", "Close the project, but keep the contract open", "Keep the contract and the project open"]'::jsonb, '[3]'::jsonb, 'Le chef de projet devrait maintenir le contrat et le projet ouverts jusqu’à ce que le vendeur réalise l’inspection. Option B : la clôture d’un contrat exige de vérifier que le vendeur a livré son travail conformément aux dispositions prévues dans le contrat. Option C : la clôture d’un projet implique plusieurs processus et étapes, notamment la clôture de tous les contrats.', 'The project manager should keep both the contract and the project open until the seller performs the inspection. Option B: Closing a contract in return requires verifying that the seller has delivered their work as predetermined in the contract. Option C: Closing a project entails conducting several processes and steps including closing out all contracts.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Scope', 'Scope', 'Predictive', 'Predictive', true),
('L3Q142', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Dans un projet Agile, où trouve-t-on la description de haut niveau du périmètre du projet ?', 'In an Agile project, where to find the high-level description of the project scope?', '["Charte de projet", "User stories", "Epics", "Structure de découpage du projet (WBS)"]'::jsonb, '["Project charter", "User stories", "Epics", "Work breakdown structure"]'::jsonb, '[0]'::jsonb, 'La charte de projet comprend la « description de haut niveau » du projet (PMBOK, 8e édition, page 128). La charte de projet est un document formel qui décrit le projet dans son ensemble, notamment ses objectifs, ses processus de travail et ses parties prenantes. Ce document de planification peut être utilisé tout au long du cycle de vie du projet. Options B et C : les user stories et les epics ne représentent que les exigences détaillées, et non la description globale de haut niveau du périmètre du projet. Option D : la structure de découpage du projet (WBS) décrit également les exigences détaillées des projets qui suivent une approche prédictive.', 'The project charter includes the ‘high-level description‘ of the project (PMBOK 8th edition, page 128). The project charter is a formal document that describes the project in its entirety, including its objectives, work processes, and stakeholders. This project planning document can be used throughout the whole project lifecycle. Options B & C: User stories and epics only represent the detailed requirements, not the entire high-level description of the project scope. Option D: The Work Breakdown Structure (WBS) also outlines the detailed requirements of projects that follow a predictive approach.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Scope', 'Scope', 'Agile', 'Agile', true),
('L3Q143', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Une allocation budgétaire prédéfinie constitue une ___________________ du projet.', 'A predefined budget allocation is a project ___________________.', '["Budget", "Hypothèse", "Risque", "Contrainte"]'::jsonb, '["Budget", "Assumption", "Risk", "Constraint"]'::jsonb, '[3]'::jsonb, 'Les contraintes du projet sont des facteurs limitatifs susceptibles d’avoir une incidence sur la livraison, la qualité et la réussite globale du projet (PMBOK, 8e édition, page 266). Une date de livraison imposée ou un budget prédéfini sont considérés comme des contraintes du projet.', 'Project constraints are limiting factors for your project that can impact delivery, quality, and overall project success (PMBOK 8th edition, page 266). An imposed delivery date or a predefined budget are considered project constraints.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Finance', 'Finance', 'Hybrid', 'Hybrid', true),
('L3Q144', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Pour quelles raisons organise-t-on des sessions sur les leçons apprises ?', 'For what reasons are lessons learned sessions conducted? Identify innovative ideas to address a specific problem.', '["Identifier des idées innovantes pour résoudre un problème précis.", "Identifier les personnes responsables des échecs et des erreurs.", "Identifier les possibilités d’améliorer la performance future.", "Identifier les actions à mener lors des prochaines phases du projet."]'::jsonb, '["Identify innovative ideas to address a specific problem.", "Identify individuals accountable for failures and errors.", "Identify opportunities to improve future performance.", "Identify action items for the next project phases."]'::jsonb, '[2]'::jsonb, 'Option A : l’identification d’idées innovantes pour résoudre un problème précis relève davantage du brainstorming ou du design thinking, dont l’objectif est de générer des solutions à un défi particulier. Option B : les réunions sur les leçons apprises ne devraient pas servir à tenir d’autres personnes responsables des erreurs commises pendant le projet. Option C : les sessions sur les leçons apprises permettent de tirer les enseignements des erreurs afin d’éviter de les répéter à l’avenir. Elles offrent également l’occasion d’identifier et d’établir les bonnes pratiques, ainsi que de renforcer la confiance avec les parties prenantes et les membres de l’équipe (PMBOK, 8e édition, page 194). Option D : l’identification des actions à mener lors des prochaines phases du projet relève des sessions de planification.', 'Identifying innovative ideas to address a specific problem is more related to brainstorming or design thinking, where the focus is on generating solutions for a specific challenge. Lessons learned meetings should not be used to hold others accountable for mistakes made during the project. Lessons learned sessions are performed for the purpose of learning from mistakes in order to avoid repeating them in the future. They also serve as an opportunity to identify and establish best practices and build trust with stakeholders and team members (PMBOK 8th edition, page 194). Identifying action items for the next project phases is related to planning sessions.', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Gouvernance', 'Gouvernance', 'Hybrid', 'Hybrid', true),
('L3Q145', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'À la fin du projet, pendant la réunion sur les leçons apprises, un chef de projet présente le graphique suivant et indique que les dépenses du projet au fil du temps forment une ____________.', 'At the end of the project, and during the lessons learned meeting, a project manager presents the following chart, stating that project expenditures over time form a(n) ____________.', '["Ligne inclinée", "Courbe en S", "Courbe en Z", "Courbe intégrale"]'::jsonb, '["Slanted line", "S curve", "Z curve", "Integral curve"]'::jsonb, '[1]'::jsonb, 'Les courbes en S représentent l’évolution du coût d’un projet sur une période donnée (PMBOK, 8e édition, page 273). Leur nom provient de la forme en S que prennent généralement les données : les coûts sont faibles au début et à la fin du projet, et augmentent progressivement au milieu du projet.', 'S-Curves visualize the evolution of a project cost over a period of time (PMBOK 8th Edition, page 273). The name is derived from the S-shape that data usually form, with low costs at the project’s start and end, and increasingly elevated costs mid-project.', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Finance', 'Finance', 'Predictive', 'Predictive', true),
('L3Q146', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'multiple', 'Un chef de projet anime une réunion à laquelle participent les parties prenantes du projet afin de discuter d’un problème récurrent avec l’un des fournisseurs. En tant que facilitateur, le chef de projet devrait : (Choisissez deux réponses.)', 'A project manager facilitates a meeting attended by project stakeholders to discuss a recurring issue with one of the project vendors. As a facilitator, the project manager should: (Select two)', '["Exercer un contrôle total sur la discussion et ses résultats", "Être responsable de la prise des notes de réunion", "Aider les parties prenantes à trouver un terrain d’entente et à résoudre le problème", "Fournir des orientations sans intervenir directement"]'::jsonb, '["Be in full control of the discussion and its outcomes", "Be responsible for taking meeting notes", "Help stakeholders find common ground and solve the issue", "Provide guidance without interfering"]'::jsonb, '[2, 3]'::jsonb, 'La facilitation consiste à aider les autres à gérer un processus, à parvenir à un accord ou à trouver une solution sans s’impliquer personnellement ou directement dans le processus ou la discussion. Pour conserver une position impartiale, le facilitateur devrait aborder la discussion comme une voix neutre (PMBOK, 8e édition, page 170).', 'Facilitation means assisting others in dealing with a process, reaching an agreement, or finding a solution without personally or directly getting involved in the process, discussion, etc. For the facilitator to maintain an impartial position, they should approach the discussion as an unbiased voice (PMBOK 8th Edition, page 170).', 'Principes fondamentaux du management de projet et concepts cl?s', 'Project Management Fundamentals and Core Concepts', 'Stakeholders', 'Stakeholders', 'Hybrid', 'Hybrid', true),
('L3Q147', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un business analyst doit recueillir du feedback en amont, avant le développement complet du produit. Quelle technique devrait-il utiliser ?', 'A business analyst needs to get early feedback before the full development of the product. What technique should the business analyst use?', '["Brainstorming", "Atelier sur les exigences", "Prototypage", "Analyse documentaire"]'::jsonb, '["Brainstorming", "Requirements workshop", "Prototyping", "Document analysis"]'::jsonb, '[2]'::jsonb, 'Le prototypage est une technique utilisée pour recueillir un feedback précoce sur les exigences en présentant un modèle de la solution envisagée avant son développement complet. Ces prototypes, souvent appelés preuves de concept (PoC), permettent de valider les idées et d’affiner les exigences avant la mise en œuvre finale (PMI Guide to Business Analysis, page 168).', 'Prototyping is a technique used to gather early feedback on requirements by presenting a model of the anticipated solution prior to its full development. These prototypes, often referred to as proofs of concept (PoCs), help validate ideas and refine requirements before the final implementation (PMI Guide to Business Analysis, page 168)', 'Cadres d''analyse d''affaires', 'Business Analysis Frameworks', 'Scope', 'Scope', 'Hybrid', 'Hybrid', true),
('L3Q148', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Quelle est la caractéristique la plus importante d’une équipe Agile ?', 'Which is the most important characteristic of an Agile team?', '["Sa capacité à créer et à gérer son propre échéancier de travail", "Sa capacité à faire preuve de flexibilité et d’adaptabilité", "Sa capacité à planifier précisément le projet", "Sa capacité à travailler simultanément sur ses tâches"]'::jsonb, '["Their ability to create and manage their own work schedule", "Their ability to be flexible and adaptable", "Their ability to accurately plan the project", "Their ability to simultaneously work on their tasks"]'::jsonb, '[1]'::jsonb, 'La flexibilité et l’adaptabilité constituent les principes fondamentaux d’Agile. Options A, C et D : toutes les autres compétences peuvent être développées progressivement à mesure que l’équipe Agile apprend de ses propres expériences.', 'Flexibility and adaptability are the core principles of Agile. Options A & C & D: All other skills can be developed over time when the Agile team gets to learn from its own experiences.', 'Cadres de travail/m?thodologies agiles', 'Agile Frameworks/Methodologies', 'resources and Risks', 'Resources and Risks', 'Agile', 'Agile', true),
('L3Q149', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Un chef de projet supervise un projet prédictif au sein d’une organisation fonctionnelle. Pendant l’exécution, il rencontre un problème qui n’avait pas été identifié lors de la planification. Pour le résoudre, des travaux supplémentaires doivent être ajoutés au périmètre du projet, ce qui augmente les coûts. À qui le chef de projet devrait-il transmettre la demande de fonds supplémentaires nécessaires à la réalisation de ces travaux ?', 'A project manager is overseeing a predictive project within a functional organization. During execution, the project manager faced an issue that wasn’t identified in the planning phase. To address this, additional work needs to be added to the project scope, leading to an increase in project costs. To whom should the project manager escalate the request for additional funds to complete this work?', '["Responsable de programme", "Product Owner", "Sponsor du projet", "Responsable fonctionnel"]'::jsonb, '["Program manager", "Product owner", "Project sponsor", "Functional manager"]'::jsonb, '[3]'::jsonb, 'Dans une organisation fonctionnelle, le chef de projet ne gère pas le budget (PMBOK, 8e édition, page 22). Il devrait donc transmettre le besoin de fonds supplémentaires au responsable fonctionnel. Si celui-ci valide son évaluation, il devra à son tour transmettre la demande au sponsor du projet afin qu’il approuve l’allocation de ressources financières supplémentaires. Si le chef de projet travaillait dans une organisation par projets ou dans une organisation matricielle forte, il n’aurait pas à adresser sa demande de fonds supplémentaires au responsable fonctionnel. Option A : un responsable de programme, comme son titre l’indique, ne gère que des programmes, ce qui n’est pas le cas dans ce scénario. Option B : le rôle du Product Owner est limité au cadre Scrum, qui relève d’une approche adaptative. Dans ce cas, le chef de projet devrait signaler ce type de problème au Product Owner, qui le transmettrait au sponsor du projet.', 'In a functional organization, the project manager doesn''t manage the budget (PMBOK 8th Edition, page 22). Thus, they should escalate the need for additional funds to the functional manager. If the functional manager validates their assessment, they will need to escalate their request to the project sponsor to approve allocating additional financial resources. If the project manager was working in a projectized or strong matrix organization, they wouldn''t need to raise their request for more funds to the functional manager. Option A: A program manager, as the name suggests, only handles programs, which is not the case in this scenario. Option B: The product owner’s role is limited to the scrum framework, which is an adaptive approach. If that were the case, the project manager would need to report similar issues to the product owner, who will escalate the matter to the project sponsor.', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Gouvernance', 'Gouvernance', 'Predictive', 'Predictive', true),
('L3Q150', 'capm-2026-lot-3-complet-questions-01-150', 'CAPM', 'single', 'Pendant la phase d’initialisation du projet, le sponsor demande une estimation approximative du coût du projet avant la fin de la journée. Que devrait faire le chef de projet ?', 'In the project initiation phase, the sponsor requested an approximate estimation of the project cost by the end of the day. What should the project manager do?', '["Créer les éléments du Product Backlog, estimer le nombre d’itérations nécessaires pour les achever, puis additionner le coût estimé de chaque itération.", "Créer la structure de découpage du projet (WBS), puis additionner le coût estimé de chaque lot de travaux.", "Créer le plan de management des coûts.", "Fournir une estimation fondée sur des projets antérieurs similaires."]'::jsonb, '["Create the product backlog items, estimate how many iterations are required to complete the items, and then sum up the cost estimate of each iteration.", "Create the WBS and sum up the cost estimate of each work package.", "Create the cost management plan.", "Provide an estimate based on similar past projects."]'::jsonb, '[3]'::jsonb, 'Compte tenu de la demande du sponsor d’obtenir rapidement une estimation des coûts avec des informations limitées, le chef de projet devrait recourir à une estimation par analogie, fondée sur les données de projets antérieurs similaires et sur le jugement à dire d’expert (PMBOK, 8e édition, page 146). Option A : le chef de projet ne peut pas créer les éléments du Product Backlog, car cette responsabilité incombe au Product Owner. Option B : l’élaboration de la structure de découpage du projet (WBS) n’est pas réalisable dans le délai imparti, car elle exige du temps et la participation de l’équipe.', 'Given the sponsor''s request for a cost estimate on short notice with limited information, the project manager should use analogous estimating, relying on data from similar past projects and expert judgment (PMBOK 8th Edition, page 146). Option A: The project manager cannot create product backlog items (a responsibility of the product owner). Option B: Developing the Work Breakdown Structure (WBS) is not feasible due to the time required and the need for team involvement.', 'M?thodologies pr?dictives et m?thodologies bas?es sur la planification', 'Predictive, Plan-Based Methodologies', 'Finance', 'Finance', 'Predictive', 'Predictive', true)
on conflict (id) do update set lot_id = excluded.lot_id, exam_type = excluded.exam_type, question_type = excluded.question_type, prompt_fr = excluded.prompt_fr, prompt_en = excluded.prompt_en, options_fr = excluded.options_fr, options_en = excluded.options_en, correct_indexes = excluded.correct_indexes, explanation_fr = excluded.explanation_fr, explanation_en = excluded.explanation_en, eco_fr = excluded.eco_fr, eco_en = excluded.eco_en, performance_domain_fr = excluded.performance_domain_fr, performance_domain_en = excluded.performance_domain_en, approach_fr = excluded.approach_fr, approach_en = excluded.approach_en, active = excluded.active;
